window.CGL_DATA=window.CGL_DATA||{};window.CGL_DATA["CGL-23-OCT-2026-SHIFT-3"]={"id":"CGL-23-OCT-2026-SHIFT-3","title":"CGL 23 OCT 2026 SHIFT 3","order":["REASONING","GK","MATH","ENGLISH"],"marking":{"correct":2,"negative":0.5},"qualifying":[],"sections":{"REASONING":{"seconds":900,"questions":[{"no":1,"local_id":"50001","quid":"Q1000071281","section":"REASONING","topic":"Mathematical Operations","question":{"en":"If @ &#8594; A is added to B<br>^ &#8594; A is multiplied by B<br>% &#8594; A is divided by B<br>&#36; &#8594; B is subtracted from A<br>Then: [(96 % 12) @ (6 @ 3)] &#36; [(49 % 7) ^ 2] [SSC CGL 23/10/26 Shift 3]","hi":"यदि @ &#8594; A में B जोड़ा जाता है<br>^ &#8594; A को B से गुणा किया जाता है<br>% &#8594; A को B से भाग दिया जाता है<br>&#36; &#8594; A में से B घटाया जाता है<br>तब: [(96 % 12) @ (6 @ 3)] &#36; [(49 % 7) ^ 2] [SSC CGL 23/10/26 Shift 3]"},"options":{"1":{"en":"1"},"2":{"en":"2"},"3":{"en":"3"},"4":{"en":"4"}},"answer":"3","solution":{"en":"96 % 12 means 96 divided by 12 = 8 and 6 @ 3 means 6 added to 3 = 9, so [8 @ 9] = 8 + 9 = 17<br>49 % 7 = 7 and [7 ^ 2] = 7 × 2 = 14<br>17 &#36; 14 means 14 subtracted from 17 = 3<br>So the value of the expression is 3<br><br><b>Hence, the correct answer is option (3): 3.</b>","hi":"96 % 12 का अर्थ 96 में 12 से भाग = 8 तथा 6 @ 3 का अर्थ 6 में 3 जोड़ना = 9, अतः [8 @ 9] = 8 + 9 = 17<br>49 % 7 = 7 तथा [7 ^ 2] = 7 × 2 = 14<br>17 &#36; 14 का अर्थ 17 में से 14 घटाना = 3<br>अतः व्यंजक का मान 3 है<br><br><b>अतः सही उत्तर विकल्प (3): 3 है।</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":2,"local_id":"50002","quid":"Q1000071282","section":"REASONING","topic":"Mathematical Operations","question":{"en":"What is 48 divided by 6 plus 7? [SSC CGL 23/10/26 Shift 3]","hi":"48 में 6 से भाग देकर 7 जोड़ने पर क्या प्राप्त होता है? [SSC CGL 23/10/26 Shift 3]"},"options":{"1":{"en":"13"},"2":{"en":"14"},"3":{"en":"15"},"4":{"en":"16"}},"answer":"3","solution":{"en":"48 divided by 6 = 48 ÷ 6 = 8<br>8 plus 7 = 8 + 7 = 15<br><br><b>Hence, the correct answer is option (3): 15.</b>","hi":"48 में 6 से भाग = 48 ÷ 6 = 8<br>8 में 7 जोड़ने पर = 8 + 7 = 15<br><br><b>अतः सही उत्तर विकल्प (3): 15 है।</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":3,"local_id":"50003","quid":"Q1000071283","section":"REASONING","topic":"Mathematical Operations","question":{"en":"Calculate: \\(\\sqrt{144}+\\sqrt{81}\\) [SSC CGL 23/10/26 Shift 3]","hi":"गणना कीजिए: \\(\\sqrt{144}+\\sqrt{81}\\) [SSC CGL 23/10/26 Shift 3]"},"options":{"1":{"en":"19"},"2":{"en":"20"},"3":{"en":"21"},"4":{"en":"22"}},"answer":"3","solution":{"en":"\\(\\sqrt{144}=12\\) and \\(\\sqrt{81}=9\\)<br>So \\(12+9=21\\)<br><br><b>Hence, the correct answer is option (3): 21.</b>","hi":"\\(\\sqrt{144}=12\\) तथा \\(\\sqrt{81}=9\\)<br>अतः \\(12+9=21\\)<br><br><b>अतः सही उत्तर विकल्प (3): 21 है।</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":4,"local_id":"50004","quid":"Q1000071284","section":"REASONING","topic":"Dictionary / Alphabetical Order","question":{"en":"While arranging the given words in dictionary order, which word will come first?<br>Start, Stall, Stamp, Stand [SSC CGL 23/10/26 Shift 3]","hi":"दिए गए शब्दों को शब्दकोश के क्रम में व्यवस्थित करने पर कौन-सा शब्द पहले आएगा?<br>Start, Stall, Stamp, Stand [SSC CGL 23/10/26 Shift 3]"},"options":{"1":{"en":"Stamp"},"2":{"en":"Stall"},"3":{"en":"Stand"},"4":{"en":"Start"}},"answer":"2","solution":{"en":"All four words begin with “Sta”, so the fourth letter decides the order<br>Stall (l), Stamp (m), Stand (n), Start (r)<br>l comes first in the alphabet, so the order is Stall, Stamp, Stand, Start<br><br><b>Hence, the correct answer is option (2): Stall.</b>","hi":"चारों शब्द “Sta” से शुरू होते हैं, इसलिए चौथा अक्षर क्रम तय करता है<br>Stall (l), Stamp (m), Stand (n), Start (r)<br>वर्णमाला में l सबसे पहले आता है, अतः क्रम है: Stall, Stamp, Stand, Start<br><br><b>अतः सही उत्तर विकल्प (2): Stall है।</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":5,"local_id":"50005","quid":"Q1000071285","section":"REASONING","topic":"Syllogism","question":{"en":"If all students in the science class have a lab coat and Ria is in the science class, what conclusion logically follows? [SSC CGL 23/10/26 Shift 3]","hi":"यदि विज्ञान कक्षा के सभी विद्यार्थियों के पास लैब कोट है और रिया विज्ञान कक्षा में है, तो तार्किक रूप से कौन-सा निष्कर्ष निकलता है? [SSC CGL 23/10/26 Shift 3]"},"options":{"1":{"en":"Ria does not have a lab coat","hi":"रिया के पास लैब कोट नहीं है"},"2":{"en":"Ria has a lab coat","hi":"रिया के पास लैब कोट है"},"3":{"en":"Ria is not in science class","hi":"रिया विज्ञान कक्षा में नहीं है"},"4":{"en":"Ria may be in maths class","hi":"रिया गणित कक्षा में हो सकती है"}},"answer":"2","solution":{"en":"The first statement says that every student of the science class has a lab coat<br>The second statement says that Ria is in the science class<br>So Ria must have a lab coat, and the other options contradict the given information<br><br><b>Hence, the correct answer is option (2): Ria has a lab coat.</b>","hi":"पहला कथन कहता है कि विज्ञान कक्षा के प्रत्येक विद्यार्थी के पास लैब कोट है<br>दूसरा कथन कहता है कि रिया विज्ञान कक्षा में है<br>अतः रिया के पास लैब कोट होगा, तथा अन्य विकल्प दी गई जानकारी के विपरीत हैं<br><br><b>अतः सही उत्तर विकल्प (2): रिया के पास लैब कोट है है।</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":6,"local_id":"50006","quid":"Q1000071286","section":"REASONING","topic":"Word Analogy","question":{"en":"If \"Doctor is related to Hospital\", then in the same manner, which of the following pairs shows a similar relationship? [SSC CGL 23/10/26 Shift 3]","hi":"यदि \"Doctor का संबंध Hospital से है\", तो उसी प्रकार निम्नलिखित में से कौन-सा युग्म समान संबंध दर्शाता है? [SSC CGL 23/10/26 Shift 3]"},"options":{"1":{"en":"Chef : Office"},"2":{"en":"Farmer : Factory"},"3":{"en":"Pilot : Cockpit"},"4":{"en":"Teacher : Market"}},"answer":"3","solution":{"en":"A doctor works in a hospital, so the pair shows the worker and the place of work<br>A pilot works in the cockpit of an aircraft, which is the same worker and workplace relation<br>A chef works in a kitchen, a farmer in a field and a teacher in a school, so those pairs do not fit<br>Hence the pair Pilot : Cockpit is the correct one<br><br><b>Hence, the correct answer is option (3): Pilot : Cockpit.</b>","hi":"एक डॉक्टर अस्पताल में कार्य करता है, अतः युग्म कार्यकर्ता और कार्यस्थल का संबंध दर्शाता है<br>पायलट विमान के कॉकपिट में कार्य करता है, जो वही कार्यकर्ता-कार्यस्थल संबंध है<br>शेफ रसोई में, किसान खेत में तथा शिक्षक विद्यालय में कार्य करता है, अतः वे युग्म इस संबंध में नहीं बैठते<br>इसलिए सही युग्म Pilot : Cockpit है<br><br><b>अतः सही उत्तर विकल्प (3): Pilot : Cockpit है।</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":7,"local_id":"50007","quid":"Q1000071287","section":"REASONING","topic":"Figure Series & Figure Analogy","question":{"en":"In the following question, there is a specific relationship between the first two figures. Establish a similar relationship between the third and fourth figures by selecting a suitable figure from the given alternatives that will replace the question mark (?).<br><img src=\"https://res.cloudinary.com/mc6kb3uo/image/upload/ssc_mock/CGL-23-OCT-2026-SHIFT-3/q7.jpg\" style=\"max-width:100%;height:auto\"> [SSC CGL 23/10/26 Shift 3]","hi":"निम्नलिखित प्रश्न में पहली दो आकृतियों के बीच एक विशिष्ट संबंध है। तीसरी और चौथी आकृति के बीच भी वही संबंध स्थापित कीजिए और प्रश्नवाचक चिह्न (?) के स्थान पर दिए गए विकल्पों में से उपयुक्त आकृति चुनिए।<br><img src=\"https://res.cloudinary.com/mc6kb3uo/image/upload/ssc_mock/CGL-23-OCT-2026-SHIFT-3/q7.jpg\" style=\"max-width:100%;height:auto\"> [SSC CGL 23/10/26 Shift 3]"},"options":{"1":{},"2":{},"3":{},"4":{}},"answer":"4","solution":{"en":"In Image X the small circle with the bent line stays attached to one side of the triangle and in each step it moves along the sides of the triangle, from the lower side to the right side and then to the upper side<br>Along with this the triangle also turns step by step, so in the third figure the dark circle sits at the upper left and the triangle hangs below it<br>Carrying the same movement one step further brings the small circle to the left of the triangle with the bent line rising behind it, which is the figure printed as option 4<br><br><b>Hence, the correct answer is option (4): <img src=\"https://res.cloudinary.com/mc6kb3uo/image/upload/ssc_mock/CGL-23-OCT-2026-SHIFT-3/q7_opt4.jpg\" style=\"max-width:100%;height:auto\">.</b>","hi":"Image X में मुड़ी रेखा के साथ छोटा वृत्त त्रिभुज की एक भुजा से जुड़ा रहता है और प्रत्येक चरण में वह त्रिभुज की भुजाओं के साथ, निचली भुजा से दाईं भुजा और फिर ऊपरी भुजा की ओर बढ़ता है<br>इसके साथ त्रिभुज भी चरण-दर-चरण घूमता है, इसलिए तीसरी आकृति में काला वृत्त ऊपर बाईं ओर और त्रिभुज उसके नीचे है<br>यही गति एक चरण आगे बढ़ाने पर छोटा वृत्त त्रिभुज के बाईं ओर आ जाता है और मुड़ी रेखा उसके पीछे से ऊपर उठती है, जो विकल्प 4 में छपी आकृति है<br><br><b>अतः सही उत्तर विकल्प (4): <img src=\"https://res.cloudinary.com/mc6kb3uo/image/upload/ssc_mock/CGL-23-OCT-2026-SHIFT-3/q7_opt4.jpg\" style=\"max-width:100%;height:auto\"> है।</b>"},"marks":{"correct":2,"negative":0.5},"has_image":true,"images":{"question":["https://res.cloudinary.com/mc6kb3uo/image/upload/ssc_mock/CGL-23-OCT-2026-SHIFT-3/q7.jpg"],"options":{"1":["https://res.cloudinary.com/mc6kb3uo/image/upload/ssc_mock/CGL-23-OCT-2026-SHIFT-3/q7_opt1.jpg"],"2":["https://res.cloudinary.com/mc6kb3uo/image/upload/ssc_mock/CGL-23-OCT-2026-SHIFT-3/q7_opt2.jpg"],"3":["https://res.cloudinary.com/mc6kb3uo/image/upload/ssc_mock/CGL-23-OCT-2026-SHIFT-3/q7_opt3.jpg"],"4":["https://res.cloudinary.com/mc6kb3uo/image/upload/ssc_mock/CGL-23-OCT-2026-SHIFT-3/q7_opt4.jpg"]},"solution":["https://res.cloudinary.com/mc6kb3uo/image/upload/ssc_mock/CGL-23-OCT-2026-SHIFT-3/q7_opt4.jpg"]}},{"no":8,"local_id":"50008","quid":"Q1000071288","section":"REASONING","topic":"Mathematical Operations","question":{"en":"If &#8853; stands for division and &#8855; stands for addition, what is 20 &#8853; 4 &#8855; 3? [SSC CGL 23/10/26 Shift 3]","hi":"यदि &#8853; का अर्थ भाग है और &#8855; का अर्थ जोड़ है, तो 20 &#8853; 4 &#8855; 3 का मान क्या है? [SSC CGL 23/10/26 Shift 3]"},"options":{"1":{"en":"8"},"2":{"en":"10"},"3":{"en":"11"},"4":{"en":"13"}},"answer":"1","solution":{"en":"Replacing the signs, 20 &#8853; 4 &#8855; 3 becomes 20 ÷ 4 + 3<br>20 ÷ 4 = 5 and 5 + 3 = 8<br><br><b>Hence, the correct answer is option (1): 8.</b>","hi":"चिह्न बदलने पर 20 &#8853; 4 &#8855; 3, 20 ÷ 4 + 3 हो जाता है<br>20 ÷ 4 = 5 तथा 5 + 3 = 8<br><br><b>अतः सही उत्तर विकल्प (1): 8 है।</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":9,"local_id":"50009","quid":"Q1000071289","section":"REASONING","topic":"Paper Folding, Cutting & Mirror/Water Images","question":{"en":"Select the figure from Image Y that is the correct mirror image of Image X (assume that the mirror is placed to the right of Image X).<br><img src=\"https://res.cloudinary.com/mc6kb3uo/image/upload/ssc_mock/CGL-23-OCT-2026-SHIFT-3/q9.jpg\" style=\"max-width:100%;height:auto\"> [SSC CGL 23/10/26 Shift 3]","hi":"Image Y में से वह आकृति चुनिए जो Image X का सही दर्पण प्रतिबिंब है (मान लीजिए कि दर्पण Image X के दाईं ओर रखा गया है)।<br><img src=\"https://res.cloudinary.com/mc6kb3uo/image/upload/ssc_mock/CGL-23-OCT-2026-SHIFT-3/q9.jpg\" style=\"max-width:100%;height:auto\"> [SSC CGL 23/10/26 Shift 3]"},"options":{"1":{"en":"A"},"2":{"en":"B"},"3":{"en":"C"},"4":{"en":"D"}},"answer":"1","solution":{"en":"In Image X the pentagon lies in the lower left part, the arrow in the right part points up towards the top right corner and the zigzag lightning lies in the upper left part<br>In a mirror placed on the right side the left and right interchange while up and down stay the same, so the pentagon must come to the lower right and the arrow must point up towards the top left corner<br>Option A shows exactly this arrangement, with the pentagon at the lower right and the arrow rising to the top left<br><br><b>Hence, the correct answer is option (1): A.</b>","hi":"Image X में पंचभुज निचले बाएँ भाग में है, दाईं ओर का तीर ऊपर दाएँ कोने की ओर संकेत करता है और टेढ़ी-मेढ़ी बिजली ऊपरी बाएँ भाग में है<br>दाईं ओर रखे दर्पण में बायाँ और दायाँ भाग परस्पर बदल जाते हैं जबकि ऊपर-नीचे वही रहते हैं, अतः पंचभुज निचले दाएँ भाग में आएगा और तीर ऊपर बाएँ कोने की ओर संकेत करेगा<br>विकल्प A में यही व्यवस्था है, जिसमें पंचभुज निचले दाएँ भाग में और तीर ऊपर बाईं ओर है<br><br><b>अतः सही उत्तर विकल्प (1): A है।</b>"},"marks":{"correct":2,"negative":0.5},"has_image":true,"images":{"question":["https://res.cloudinary.com/mc6kb3uo/image/upload/ssc_mock/CGL-23-OCT-2026-SHIFT-3/q9.jpg"]}},{"no":10,"local_id":"50010","quid":"Q1000071290","section":"REASONING","topic":"Paper Folding, Cutting & Mirror/Water Images","question":{"en":"Choose the figure from Image Y that best represents the folded version of the transparent sheet in Image X along the dotted line.<br><img src=\"https://res.cloudinary.com/mc6kb3uo/image/upload/ssc_mock/CGL-23-OCT-2026-SHIFT-3/q10.jpg\" style=\"max-width:100%;height:auto\"> [SSC CGL 23/10/26 Shift 3]","hi":"Image X की पारदर्शी शीट को बिंदुदार रेखा के अनुदिश मोड़ने पर बनने वाली आकृति Image Y में से चुनिए।<br><img src=\"https://res.cloudinary.com/mc6kb3uo/image/upload/ssc_mock/CGL-23-OCT-2026-SHIFT-3/q10.jpg\" style=\"max-width:100%;height:auto\"> [SSC CGL 23/10/26 Shift 3]"},"options":{"1":{"en":"A"},"2":{"en":"B"},"3":{"en":"C"},"4":{"en":"D"}},"answer":"3","solution":{"en":"The sheet is folded along the dotted vertical line, so the left half comes over the right half and everything printed on the left half is seen mirrored on the right half<br>The small circle of the lower left with the short line above it therefore appears on the right half at the same height, the small circle of the upper right and its line stay where they are, and the dark dot lying on the fold line becomes a dark half at the fold<br>The folded sheet must thus show a dark half on its left edge together with two small circles and two short lines, which is the figure of option 3<br><br><b>Hence, the correct answer is option (3): C.</b>","hi":"शीट को बिंदुदार ऊर्ध्व रेखा के अनुदिश मोड़ा जाता है, अतः बायाँ आधा भाग दाएँ आधे पर आ जाता है और बाएँ आधे पर छपी हर वस्तु दाएँ आधे पर दर्पण रूप में दिखाई देती है<br>इसलिए निचले बाएँ का छोटा वृत्त तथा उसके ऊपर की छोटी रेखा दाएँ आधे पर उसी ऊँचाई पर दिखते हैं, ऊपरी दाएँ का छोटा वृत्त और उसकी रेखा अपने स्थान पर रहते हैं, तथा मोड़ रेखा पर पड़ा काला बिंदु मोड़ पर एक काला आधा भाग बन जाता है<br>अतः मुड़ी शीट के बाईं ओर काले आधे भाग के साथ दो छोटे वृत्त और दो छोटी रेखाएँ दिखनी चाहिए, जो विकल्प 3 की आकृति है<br><br><b>अतः सही उत्तर विकल्प (3): C है।</b>"},"marks":{"correct":2,"negative":0.5},"has_image":true,"images":{"question":["https://res.cloudinary.com/mc6kb3uo/image/upload/ssc_mock/CGL-23-OCT-2026-SHIFT-3/q10.jpg"]}},{"no":11,"local_id":"50011","quid":"Q1000071291","section":"REASONING","topic":"Venn Diagrams","question":{"en":"Select the Venn diagram that best illustrates the relationship between the following classes.<br>Metal, Non metal, Periodic table [SSC CGL 23/10/26 Shift 3]","hi":"निम्नलिखित वर्गों के बीच के संबंध को सर्वोत्तम रूप से दर्शाने वाला वेन आरेख चुनिए।<br>Metal, Non metal, Periodic table [SSC CGL 23/10/26 Shift 3]"},"options":{"1":{},"2":{},"3":{},"4":{}},"answer":"3","solution":{"en":"Both metals and non-metals are groups of elements and together the elements are listed inside the periodic table<br>So the two groups lie inside one big circle, that is the periodic table, and the two groups do not overlap each other<br>The diagram with one large circle holding two separate small circles is the third one, which matches option 3<br><br><b>Hence, the correct answer is option (3): <img src=\"https://res.cloudinary.com/mc6kb3uo/image/upload/ssc_mock/CGL-23-OCT-2026-SHIFT-3/q11_opt3.jpg\" style=\"max-width:100%;height:auto\">.</b>","hi":"धातुएँ और अधातुएँ दोनों तत्वों के समूह हैं तथा सभी तत्व आवर्त सारणी के भीतर आते हैं<br>अतः दोनों समूह एक बड़े वृत्त, अर्थात् आवर्त सारणी, के भीतर हैं और दोनों समूह एक-दूसरे को नहीं काटते<br>एक बड़े वृत्त के भीतर दो अलग-अलग छोटे वृत्त वाला आरेख तीसरा है, जो विकल्प 3 है<br><br><b>अतः सही उत्तर विकल्प (3): <img src=\"https://res.cloudinary.com/mc6kb3uo/image/upload/ssc_mock/CGL-23-OCT-2026-SHIFT-3/q11_opt3.jpg\" style=\"max-width:100%;height:auto\"> है।</b>"},"marks":{"correct":2,"negative":0.5},"has_image":true,"images":{"options":{"1":["https://res.cloudinary.com/mc6kb3uo/image/upload/ssc_mock/CGL-08-OCT-2026-SHIFT-3/q18_opt1.jpg"],"2":["https://res.cloudinary.com/mc6kb3uo/image/upload/ssc_mock/CGL-23-OCT-2026-SHIFT-3/q11_opt2.jpg"],"3":["https://res.cloudinary.com/mc6kb3uo/image/upload/ssc_mock/CGL-23-OCT-2026-SHIFT-3/q11_opt3.jpg"],"4":["https://res.cloudinary.com/mc6kb3uo/image/upload/ssc_mock/CGL-23-OCT-2026-SHIFT-3/q11_opt4.jpg"]},"solution":["https://res.cloudinary.com/mc6kb3uo/image/upload/ssc_mock/CGL-23-OCT-2026-SHIFT-3/q11_opt3.jpg"]}},{"no":12,"local_id":"50012","quid":"Q1000071292","section":"REASONING","topic":"Miscellaneous","question":{"en":"Centre IDs follow the format [Sequence]-[Year]-[Validation Digit]. The Validation Digit is calculated as the last digit of the product of the first two digits of the sequence. Which centre ID is invalid? [SSC CGL 23/10/26 Shift 3]","hi":"केंद्र आईडी का प्रारूप [अनुक्रम]-[वर्ष]-[सत्यापन अंक] है। सत्यापन अंक, अनुक्रम के पहले दो अंकों के गुणनफल का अंतिम अंक होता है। कौन-सी केंद्र आईडी अमान्य है? [SSC CGL 23/10/26 Shift 3]"},"options":{"1":{"en":"785-26-6"},"2":{"en":"561-26-0"},"3":{"en":"940-26-6"},"4":{"en":"432-26-8"}},"answer":"4","solution":{"en":"For 785 the first two digits are 7 and 8, and 7 × 8 = 56, whose last digit 6 is the validation digit ✔<br>For 561, 5 × 6 = 30 gives 0 ✔ and for 940, 9 × 4 = 36 gives 6 ✔<br>For 432, 4 × 3 = 12 gives 2, but the printed validation digit is 8 ✘<br>So 432-26-8 does not follow the rule and is invalid<br><br><b>Hence, the correct answer is option (4): 432-26-8.</b>","hi":"785 के लिए पहले दो अंक 7 और 8 हैं, 7 × 8 = 56, जिसका अंतिम अंक 6 सत्यापन अंक है ✔<br>561 के लिए 5 × 6 = 30 से 0 ✔ तथा 940 के लिए 9 × 4 = 36 से 6 ✔<br>432 के लिए 4 × 3 = 12 से 2 आना चाहिए, परंतु मुद्रित सत्यापन अंक 8 है ✘<br>अतः 432-26-8 नियम का पालन नहीं करता और अमान्य है<br><br><b>अतः सही उत्तर विकल्प (4): 432-26-8 है।</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":13,"local_id":"50013","quid":"Q1000071293","section":"REASONING","topic":"Situational Judgement","question":{"en":"As a hiring manager, you notice a pattern: you consistently give higher interview scores to candidates who share your exact personal hobbies, often overlooking objectively better-qualified applicants. What is the most effective self-regulation strategy to counter this subconscious affinity bias? [SSC CGL 23/10/26 Shift 3]","hi":"एक हायरिंग मैनेजर के रूप में आप एक पैटर्न देखते हैं: आप उन अभ्यर्थियों को लगातार अधिक साक्षात्कार अंक देते हैं जिनके शौक आपके ही शौक जैसे हैं, और अक्सर वस्तुनिष्ठ रूप से अधिक योग्य अभ्यर्थियों की उपेक्षा कर देते हैं। इस अचेतन पक्षपात का सामना करने के लिए सर्वाधिक प्रभावी आत्म-नियंत्रण रणनीति क्या है? [SSC CGL 23/10/26 Shift 3]"},"options":{"1":{"en":"Justify the hiring pattern by claiming shared hobbies naturally create better team cohesion.","hi":"यह कहकर भर्ती पैटर्न को उचित ठहराना कि साझा शौक स्वाभाविक रूप से बेहतर टीम एकजुटता बनाते हैं।"},"2":{"en":"Recognise this subconscious affinity bias and implement structured, blind scoring rubrics.","hi":"इस अचेतन पक्षपात को पहचानना और संरचित तथा ब्लाइंड स्कोरिंग रूब्रिक लागू करना।"},"3":{"en":"Intentionally hire candidates with completely opposite hobbies to forcefully balance the team.","hi":"टीम को संतुलित करने के लिए जानबूझकर पूर्णतः विपरीत शौक वाले अभ्यर्थियों को नियुक्त करना।"},"4":{"en":"Delegate all future hiring decisions permanently to the human resources department entirely.","hi":"सभी भविष्य के भर्ती निर्णय स्थायी रूप से पूरी तरह मानव संसाधन विभाग को सौंप देना।"}},"answer":"2","solution":{"en":"The problem is an unconscious preference for people similar to oneself, which the manager has already recognised<br>Structured and blind scoring judges answers on fixed criteria without knowing personal details, so the effect of the bias is removed at the source<br>Justifying the bias keeps it, hiring opposite hobbies replaces one bias with another, and handing over all decisions avoids the real issue<br>So recognising the bias and using blind scoring rubrics is the most effective strategy<br><br><b>Hence, the correct answer is option (2): Recognise this subconscious affinity bias and implement structured, blind scoring rubrics.</b>","hi":"समस्या अपने जैसे लोगों के प्रति अचेतन झुकाव है, जिसे मैनेजर पहले ही पहचान चुका है<br>संरचित और ब्लाइंड स्कोरिंग में व्यक्तिगत विवरण जाने बिना निश्चित मानदंडों पर मूल्यांकन होता है, अतः पक्षपात का प्रभाव मूल से ही हट जाता है<br>पक्षपात को उचित ठहराने से वह बना रहता है, विपरीत शौक वालों को नियुक्त करने से एक पक्षपात दूसरे से बदल जाता है तथा सभी निर्णय सौंप देने से मूल समस्या टल जाती है<br>अतः पक्षपात को पहचानकर ब्लाइंड स्कोरिंग रूब्रिक अपनाना सर्वाधिक प्रभावी रणनीति है<br><br><b>अतः सही उत्तर विकल्प (2): इस अचेतन पक्षपात को पहचानना और संरचित तथा ब्लाइंड स्कोरिंग रूब्रिक लागू करना। है।</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":14,"local_id":"50014","quid":"Q1000071294","section":"REASONING","topic":"Statement & Conclusion","question":{"en":"In the following question, one statement is given, followed by certain inferences. Consider the statement to be true even if it seems to contradict commonly known facts. Read the inferences carefully and decide which of them logically follow from the given statement.<br><b>Statement:</b><br>A university has launched several online certificate courses to make higher education accessible to working professionals who cannot attend regular classes.<br><b>Inferences:</b><br>I. The university believes online learning can increase educational accessibility.<br>II. Traditional classroom education is no longer useful. [SSC CGL 23/10/26 Shift 3]","hi":"निम्नलिखित प्रश्न में एक कथन और उसके बाद कुछ निष्कर्ष दिए गए हैं। कथन को सत्य मानिए, भले ही वह सामान्यतः ज्ञात तथ्यों के विपरीत प्रतीत हो। निष्कर्षों को ध्यान से पढ़िए और निर्णय कीजिए कि उनमें से कौन-सा कथन से तार्किक रूप से निकलता है।<br><b>कथन:</b><br>एक विश्वविद्यालय ने कामकाजी पेशेवरों के लिए, जो नियमित कक्षाओं में नहीं आ सकते, उच्च शिक्षा को सुलभ बनाने के लिए कई ऑनलाइन सर्टिफिकेट पाठ्यक्रम शुरू किए हैं।<br><b>निष्कर्ष:</b><br>I. विश्वविद्यालय का मानना है कि ऑनलाइन शिक्षा शैक्षिक सुलभता बढ़ा सकती है।<br>II. पारंपरिक कक्षा शिक्षा अब उपयोगी नहीं रही। [SSC CGL 23/10/26 Shift 3]"},"options":{"1":{"en":"Both Inferences I and II follow.","hi":"निष्कर्ष I और II दोनों निकलते हैं।"},"2":{"en":"Only Inference I follows.","hi":"केवल निष्कर्ष I निकलता है।"},"3":{"en":"Neither Inference I nor Inference II follows.","hi":"न तो निष्कर्ष I और न ही निष्कर्ष II निकलता है।"},"4":{"en":"Only Inference II follows.","hi":"केवल निष्कर्ष II निकलता है।"}},"answer":"2","solution":{"en":"The statement says the university started online courses to make higher education accessible, which shows the belief that online learning improves accessibility, so I follows<br>Nothing in the statement says that regular classroom teaching has lost its use, so II is an overstatement and does not follow<br>Hence only inference I follows<br><br><b>Hence, the correct answer is option (2): Only Inference I follows.</b>","hi":"कथन कहता है कि विश्वविद्यालय ने उच्च शिक्षा को सुलभ बनाने के लिए ऑनलाइन पाठ्यक्रम शुरू किए, जिससे यह विश्वास प्रकट होता है कि ऑनलाइन शिक्षा सुलभता बढ़ाती है, अतः I निकलता है<br>कथन में कहीं नहीं कहा गया कि नियमित कक्षा शिक्षा उपयोगी नहीं रही, अतः II अतिशयोक्ति है और नहीं निकलता<br>इसलिए केवल निष्कर्ष I निकलता है<br><br><b>अतः सही उत्तर विकल्प (2): केवल निष्कर्ष I निकलता है। है।</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":15,"local_id":"50015","quid":"Q1000071295","section":"REASONING","topic":"Statement & Conclusion","question":{"en":"Read the statement carefully and assume it to be true. Then examine the two conclusions given below it and decide which conclusion(s), if any, logically follow from the statement.<br><b>Statement:</b><br>A chess federation has arranged advanced training camps for players preparing for international tournaments.<br><b>Conclusions:</b><br>I. All players attending the camps will qualify for international tournaments.<br>II. The federation considers current training methods completely ineffective. [SSC CGL 23/10/26 Shift 3]","hi":"कथन को ध्यान से पढ़िए और उसे सत्य मानिए। फिर उसके नीचे दिए दो निष्कर्षों की जाँच कीजिए और निर्णय कीजिए कि कौन-सा/से निष्कर्ष कथन से तार्किक रूप से निकलता/निकलते हैं।<br><b>कथन:</b><br>एक शतरंज महासंघ ने अंतर्राष्ट्रीय प्रतियोगिताओं की तैयारी कर रहे खिलाड़ियों के लिए उन्नत प्रशिक्षण शिविर आयोजित किए हैं।<br><b>निष्कर्ष:</b><br>I. शिविर में भाग लेने वाले सभी खिलाड़ी अंतर्राष्ट्रीय प्रतियोगिताओं के लिए अर्हता प्राप्त करेंगे।<br>II. महासंघ वर्तमान प्रशिक्षण विधियों को पूर्णतः अप्रभावी मानता है। [SSC CGL 23/10/26 Shift 3]"},"options":{"1":{"en":"Both conclusions I and II follow","hi":"निष्कर्ष I और II दोनों निकलते हैं"},"2":{"en":"Only conclusion II follows","hi":"केवल निष्कर्ष II निकलता है"},"3":{"en":"Neither conclusion I nor conclusion II follows","hi":"न तो निष्कर्ष I और न ही निष्कर्ष II निकलता है"},"4":{"en":"Only conclusion I follows","hi":"केवल निष्कर्ष I निकलता है"}},"answer":"3","solution":{"en":"The camp only gives preparation for international tournaments, and preparation never guarantees qualification, so conclusion I does not follow<br>The statement speaks of advanced camps for selected players, which says nothing against the current methods, so conclusion II also does not follow<br>Hence neither conclusion follows<br><br><b>Hence, the correct answer is option (3): Neither conclusion I nor conclusion II follows.</b>","hi":"शिविर केवल अंतर्राष्ट्रीय प्रतियोगिताओं की तैयारी कराता है, और तैयारी कभी अर्हता की गारंटी नहीं देती, अतः निष्कर्ष I नहीं निकलता<br>कथन चयनित खिलाड़ियों के लिए उन्नत शिविरों की बात करता है, जो वर्तमान विधियों के विरुद्ध कुछ नहीं कहता, अतः निष्कर्ष II भी नहीं निकलता<br>इसलिए कोई भी निष्कर्ष नहीं निकलता<br><br><b>अतः सही उत्तर विकल्प (3): न तो निष्कर्ष I और न ही निष्कर्ष II निकलता है है।</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":16,"local_id":"50016","quid":"Q1000071296","section":"REASONING","topic":"Situational Judgement","question":{"en":"A strategist accurately predicts that a department will reject a highly efficient workflow proposal because the new system directly threatens existing status hierarchies and established job roles within the team. In organizational sociology, this prediction best reflects a deep understanding of: [SSC CGL 23/10/26 Shift 3]","hi":"एक रणनीतिकार सटीक पूर्वानुमान लगाता है कि एक विभाग अत्यधिक कुशल कार्यप्रवाह प्रस्ताव को इसलिए अस्वीकार कर देगा क्योंकि नई प्रणाली टीम के भीतर मौजूद पद-क्रम तथा स्थापित कार्यभूमिकाओं को सीधे चुनौती देती है। संगठनात्मक समाजशास्त्र में यह पूर्वानुमान किसकी गहरी समझ दर्शाता है? [SSC CGL 23/10/26 Shift 3]"},"options":{"1":{"en":"Social structure and institutional power dynamics","hi":"सामाजिक संरचना और संस्थागत शक्ति की गतिशीलता"},"2":{"en":"Abstract quantitative and arithmetic reasoning","hi":"अमूर्त मात्रात्मक तथा अंकगणितीय तर्क"},"3":{"en":"Complex linguistic fluency and vocabulary","hi":"जटिल भाषिक प्रवाह और शब्दावली"},"4":{"en":"Working memory retention and explicit data recall","hi":"कार्यशील स्मृति धारण और स्पष्ट आँकड़ों का स्मरण"}},"answer":"1","solution":{"en":"The rejection is explained through status hierarchies and established roles, which are parts of the social structure of the department<br>Understanding why people resist a change that alters power and position is exactly an understanding of social structure and institutional power dynamics<br>Arithmetic, language and memory have no role in this prediction<br>So the first option is the correct one<br><br><b>Hence, the correct answer is option (1): Social structure and institutional power dynamics.</b>","hi":"अस्वीकृति को पद-क्रम तथा स्थापित भूमिकाओं से समझाया गया है, जो विभाग की सामाजिक संरचना के भाग हैं<br>जो परिवर्तन शक्ति और स्थान बदलता है, उसका विरोध क्यों होता है, यह समझना वस्तुतः सामाजिक संरचना तथा संस्थागत शक्ति की गतिशीलता की समझ है<br>अंकगणित, भाषा और स्मृति की इसमें कोई भूमिका नहीं है<br>अतः पहला विकल्प सही है<br><br><b>अतः सही उत्तर विकल्प (1): सामाजिक संरचना और संस्थागत शक्ति की गतिशीलता है।</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":17,"local_id":"50017","quid":"Q1000071297","section":"REASONING","topic":"Situational Judgement","question":{"en":"Direction:<br>Choose the most effective decision.<br>A school introduces a new curriculum that improves analytical skills but initially reduces average examination scores because students require time to adapt. [SSC CGL 23/10/26 Shift 3]","hi":"निर्देश:<br>सर्वाधिक प्रभावी निर्णय चुनिए।<br>एक विद्यालय नई पाठ्यचर्या शुरू करता है जो विश्लेषणात्मक कौशल सुधारती है, परंतु विद्यार्थियों को अनुकूलन में समय लगने के कारण प्रारंभ में औसत परीक्षा अंक घटा देती है। [SSC CGL 23/10/26 Shift 3]"},"options":{"1":{"en":"Withdraw the curriculum immediately because examination scores have decreased.","hi":"परीक्षा अंक घटने के कारण पाठ्यचर्या तुरंत वापस ले लेना।"},"2":{"en":"Retain the curriculum permanently without monitoring future outcomes.","hi":"भविष्य के परिणामों की निगरानी किए बिना पाठ्यचर्या स्थायी रूप से बनाए रखना।"},"3":{"en":"Review long-term educational benefits and monitor adaptation before deciding.","hi":"निर्णय लेने से पहले दीर्घकालिक शैक्षिक लाभों की समीक्षा करना और अनुकूलन की निगरानी करना।"},"4":{"en":"Replace examinations entirely to eliminate concerns about lower scores.","hi":"कम अंकों की चिंता मिटाने के लिए परीक्षाएँ पूरी तरह हटा देना।"}},"answer":"3","solution":{"en":"The curriculum is improving analytical skills, so the early fall in scores is only a temporary effect of adaptation and a hasty withdrawal would lose a real benefit<br>Keeping it forever without watching the results is equally careless, and removing examinations does not solve the learning question<br>Reviewing the long-term benefits while monitoring how students adapt gives the school the facts it needs before a final decision<br>So the third course of action is the most effective<br><br><b>Hence, the correct answer is option (3): Review long-term educational benefits and monitor adaptation before deciding.</b>","hi":"पाठ्यचर्या विश्लेषणात्मक कौशल सुधार रही है, अतः अंकों का प्रारंभिक गिरना अनुकूलन का अस्थायी प्रभाव है और जल्दबाजी में हटाने से वास्तविक लाभ छिन जाएगा<br>परिणाम देखे बिना स्थायी रूप से जारी रखना भी लापरवाही है, तथा परीक्षाएँ हटा देना सीखने के प्रश्न का समाधान नहीं है<br>छात्रों के अनुकूलन की निगरानी के साथ दीर्घकालिक लाभों की समीक्षा विद्यालय को अंतिम निर्णय के लिए आवश्यक तथ्य देती है<br>अतः तीसरा कार्यवाही-क्रम सर्वाधिक प्रभावी है<br><br><b>अतः सही उत्तर विकल्प (3): निर्णय लेने से पहले दीर्घकालिक शैक्षिक लाभों की समीक्षा करना और अनुकूलन की निगरानी करना। है।</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":18,"local_id":"50018","quid":"Q1000071298","section":"REASONING","topic":"Venn Diagrams","question":{"en":"Identify the Venn diagram that represents the relationship between \"Natural Numbers, Integers, Rational Numbers\". [SSC CGL 23/10/26 Shift 3]","hi":"वह वेन आरेख पहचानिए जो \"प्राकृत संख्याएँ, पूर्णांक, परिमेय संख्याएँ\" के बीच संबंध दर्शाता है। [SSC CGL 23/10/26 Shift 3]"},"options":{"1":{},"2":{},"3":{},"4":{}},"answer":"1","solution":{"en":"Every natural number is an integer and every integer is a rational number, so the three sets are nested one inside the other<br>Natural numbers lie inside integers, and integers lie inside rational numbers<br>Only the diagram of three concentric circles shows this nesting, which is option 1<br>Hence the first diagram is correct<br><br><b>Hence, the correct answer is option (1): <img src=\"https://res.cloudinary.com/mc6kb3uo/image/upload/ssc_mock/CGL-23-OCT-2026-SHIFT-3/q18_opt1.jpg\" style=\"max-width:100%;height:auto\">.</b>","hi":"प्रत्येक प्राकृत संख्या पूर्णांक है और प्रत्येक पूर्णांक परिमेय संख्या है, अतः तीनों समुच्चय एक-दूसरे के भीतर स्थित हैं<br>प्राकृत संख्याएँ पूर्णांकों के भीतर तथा पूर्णांक परिमेय संख्याओं के भीतर आते हैं<br>केवल तीन संकेंद्री वृत्तों वाला आरेख यही निवेशन दर्शाता है, जो विकल्प 1 है<br>अतः पहला आरेख सही है<br><br><b>अतः सही उत्तर विकल्प (1): <img src=\"https://res.cloudinary.com/mc6kb3uo/image/upload/ssc_mock/CGL-23-OCT-2026-SHIFT-3/q18_opt1.jpg\" style=\"max-width:100%;height:auto\"> है।</b>"},"marks":{"correct":2,"negative":0.5},"has_image":true,"images":{"options":{"1":["https://res.cloudinary.com/mc6kb3uo/image/upload/ssc_mock/CGL-23-OCT-2026-SHIFT-3/q18_opt1.jpg"],"2":["https://res.cloudinary.com/mc6kb3uo/image/upload/ssc_mock/CGL-10-OCT-2026-SHIFT-3/q18_opt4.jpg"],"3":["https://res.cloudinary.com/mc6kb3uo/image/upload/ssc_mock/CGL-23-OCT-2026-SHIFT-3/q18_opt3.jpg"],"4":["https://res.cloudinary.com/mc6kb3uo/image/upload/ssc_mock/CGL-10-OCT-2026-SHIFT-3/q18_opt1.jpg"]},"solution":["https://res.cloudinary.com/mc6kb3uo/image/upload/ssc_mock/CGL-23-OCT-2026-SHIFT-3/q18_opt1.jpg"]}},{"no":19,"local_id":"50019","quid":"Q1000071299","section":"REASONING","topic":"Dice & Cube","question":{"en":"Four different positions of the same dice are shown. Select the number that will be on the face opposite to the one showing '6'.<br><img src=\"https://res.cloudinary.com/mc6kb3uo/image/upload/ssc_mock/CGL-23-OCT-2026-SHIFT-3/q19.jpg\" style=\"max-width:100%;height:auto\"> [SSC CGL 23/10/26 Shift 3]","hi":"एक ही पासे की चार अलग-अलग स्थितियाँ दर्शाई गई हैं। उस संख्या का चयन कीजिए जो '6' वाले फलक के विपरीत फलक पर होगी।<br><img src=\"https://res.cloudinary.com/mc6kb3uo/image/upload/ssc_mock/CGL-23-OCT-2026-SHIFT-3/q19.jpg\" style=\"max-width:100%;height:auto\"> [SSC CGL 23/10/26 Shift 3]"},"options":{"1":{"en":"1"},"2":{"en":"2"},"3":{"en":"3"},"4":{"en":"4"}},"answer":"1","solution":{"en":"In the first position 6 is seen with the faces 2 and 5, in the third position 6 is seen with 4 and 2, and in the fourth position 6 is seen with 3 and 5<br>So 6 is adjacent to 2, 5, 4 and 3 and cannot be opposite any of them<br>The only number left is 1, so 1 lies on the face opposite to 6<br><br><b>Hence, the correct answer is option (1): 1.</b>","hi":"पहली स्थिति में 6 के साथ फलक 2 और 5 दिखते हैं, तीसरी स्थिति में 6 के साथ 4 और 2 तथा चौथी स्थिति में 6 के साथ 3 और 5 दिखते हैं<br>अतः 6, फलक 2, 5, 4 और 3 के सन्निकट है और इनमें से किसी के भी विपरीत नहीं हो सकता<br>शेष बची एकमात्र संख्या 1 है, इसलिए 6 के विपरीत फलक पर 1 है<br><br><b>अतः सही उत्तर विकल्प (1): 1 है।</b>"},"marks":{"correct":2,"negative":0.5},"has_image":true,"images":{"question":["https://res.cloudinary.com/mc6kb3uo/image/upload/ssc_mock/CGL-23-OCT-2026-SHIFT-3/q19.jpg"]}},{"no":20,"local_id":"50020","quid":"Q1000071300","section":"REASONING","topic":"Odd One Out","question":{"en":"In the following question, out of the five figures marked (a), (b), (c), (d), and (e), four are similar in a certain manner. However, one figure is not like the other four. Choose the figure which is different from the rest.<br><img src=\"https://res.cloudinary.com/mc6kb3uo/image/upload/ssc_mock/CGL-23-OCT-2026-SHIFT-3/q20.jpg\" style=\"max-width:100%;height:auto\"> [SSC CGL 23/10/26 Shift 3]","hi":"निम्नलिखित प्रश्न में (a), (b), (c), (d) तथा (e) से अंकित पाँच आकृतियों में से चार किसी निश्चित प्रकार से समान हैं। परंतु एक आकृति अन्य चार से भिन्न है। शेष से भिन्न आकृति चुनिए।<br><img src=\"https://res.cloudinary.com/mc6kb3uo/image/upload/ssc_mock/CGL-23-OCT-2026-SHIFT-3/q20.jpg\" style=\"max-width:100%;height:auto\"> [SSC CGL 23/10/26 Shift 3]"},"options":{"1":{"en":"b"},"2":{"en":"d"},"3":{"en":"e"},"4":{"en":"c"}},"answer":"2","solution":{"en":"In figures (a), (b), (c) and (e) the two small shapes joined by the slanting line are of two different kinds: a star with a circle, an oval with a square, a square with a hexagon and a hexagon with a pentagon<br>In figure (d) both ends of the line carry the same shape, a hexagon at the top left and a hexagon at the bottom right<br>So figure (d) is not like the other four and is the different one<br><br><b>Hence, the correct answer is option (2): d.</b>","hi":"आकृति (a), (b), (c) तथा (e) में तिरछी रेखा से जुड़े दोनों छोटे आकार दो भिन्न प्रकार के हैं: तारा और वृत्त, अंडाकार और वर्ग, वर्ग और षट्भुज तथा षट्भुज और पंचभुज<br>आकृति (d) में रेखा के दोनों सिरों पर एक ही आकार है, ऊपर बाईं ओर षट्भुज और नीचे दाईं ओर भी षट्भुज<br>अतः आकृति (d) अन्य चार के समान नहीं है और भिन्न आकृति है<br><br><b>अतः सही उत्तर विकल्प (2): d है।</b>"},"marks":{"correct":2,"negative":0.5},"has_image":true,"images":{"question":["https://res.cloudinary.com/mc6kb3uo/image/upload/ssc_mock/CGL-23-OCT-2026-SHIFT-3/q20.jpg"]}},{"no":21,"local_id":"50021","quid":"Q1000071301","section":"REASONING","topic":"Odd One Out","question":{"en":"In the following question, out of the five figures marked (a), (b), (c), (d), and (e), four are similar in a certain manner. However, one figure is not like the other four. Choose the figure which is different from the rest.<br><img src=\"https://res.cloudinary.com/mc6kb3uo/image/upload/ssc_mock/CGL-23-OCT-2026-SHIFT-3/q21.jpg\" style=\"max-width:100%;height:auto\"> [SSC CGL 23/10/26 Shift 3]","hi":"निम्नलिखित प्रश्न में (a), (b), (c), (d) तथा (e) से अंकित पाँच आकृतियों में से चार किसी निश्चित प्रकार से समान हैं। परंतु एक आकृति अन्य चार से भिन्न है। शेष से भिन्न आकृति चुनिए।<br><img src=\"https://res.cloudinary.com/mc6kb3uo/image/upload/ssc_mock/CGL-23-OCT-2026-SHIFT-3/q21.jpg\" style=\"max-width:100%;height:auto\"> [SSC CGL 23/10/26 Shift 3]"},"options":{"1":{"en":"e"},"2":{"en":"d"},"3":{"en":"b"},"4":{"en":"a"}},"answer":"3","solution":{"en":"Each figure is a square divided into four parts, and in four of them one small part carries slanting shaded lines of the same slope in a fixed position<br>In figure (b) the fourth part is filled with thin vertical lines and the position of the shaded part is also changed, so this figure does not follow the shading pattern of the rest<br>Hence the figure in (b) is different from the other four, which is option 3<br><br><b>Hence, the correct answer is option (3): b.</b>","hi":"प्रत्येक आकृति एक वर्ग है जो चार भागों में विभाजित है, और इनमें से चार में एक छोटा भाग एक ही ढाल की तिरछी छायांकित रेखाओं से भरा है<br>आकृति (b) में चौथा भाग पतली ऊर्ध्व रेखाओं से भरा है और छायांकित भाग का स्थान भी बदल गया है, अतः यह आकृति शेष के छायांकन पैटर्न का पालन नहीं करती<br>इसलिए (b) वाली आकृति अन्य चार से भिन्न है, जो विकल्प 3 है<br><br><b>अतः सही उत्तर विकल्प (3): b है।</b>"},"marks":{"correct":2,"negative":0.5},"has_image":true,"images":{"question":["https://res.cloudinary.com/mc6kb3uo/image/upload/ssc_mock/CGL-23-OCT-2026-SHIFT-3/q21.jpg"]}},{"no":22,"local_id":"50022","quid":"Q1000071302","section":"REASONING","topic":"Statement, Assumption & Argument","question":{"en":"A publishing house has adopted a digital-first release strategy to reach a broader audience in less time. Which assumption underlies this decision? [SSC CGL 23/10/26 Shift 3]","hi":"एक प्रकाशन संस्थान ने कम समय में अधिक व्यापक पाठकवर्ग तक पहुँचने के लिए डिजिटल-प्रथम रिलीज़ रणनीति अपनाई है। इस निर्णय के पीछे कौन-सी अवधारणा निहित है? [SSC CGL 23/10/26 Shift 3]"},"options":{"1":{"en":"Printed books will become completely obsolete in the near future.","hi":"निकट भविष्य में मुद्रित पुस्तकें पूर्णतः अप्रचलित हो जाएँगी।"},"2":{"en":"Authors cannot publish work without digital distribution systems today.","hi":"आज लेखक डिजिटल वितरण व्यवस्था के बिना कार्य प्रकाशित नहीं कर सकते।"},"3":{"en":"Readers generally avoid reading books in traditional print formats.","hi":"पाठक सामान्यतः पारंपरिक मुद्रित रूपों में पुस्तकें पढ़ने से बचते हैं।"},"4":{"en":"Digital platforms allow reaching a larger audience very quickly.","hi":"डिजिटल मंच बहुत शीघ्रता से अधिक व्यापक पाठकवर्ग तक पहुँचने में सहायक हैं।"}},"answer":"4","solution":{"en":"The stated aim of the strategy is to reach a broader audience in less time, so the decision assumes that digital platforms really do spread the work to more readers quickly<br>Nothing in the statement suggests that printed books will vanish, that authors cannot publish otherwise or that readers avoid print<br>The fourth statement is the only one the decision actually depends on<br>So the assumption is that digital platforms reach a larger audience quickly<br><br><b>Hence, the correct answer is option (4): Digital platforms allow reaching a larger audience very quickly.</b>","hi":"रणनीति का घोषित उद्देश्य कम समय में अधिक व्यापक पाठकवर्ग तक पहुँचना है, अतः निर्णय यह मानकर लिया गया है कि डिजिटल मंच वास्तव में कृति को अधिक पाठकों तक शीघ्र पहुँचाते हैं<br>कथन में कहीं नहीं कहा गया कि मुद्रित पुस्तकें समाप्त हो जाएँगी, या लेखक अन्यथा प्रकाशित नहीं कर सकते, या पाठक मुद्रण से बचते हैं<br>निर्णय वस्तुतः केवल चौथे कथन पर निर्भर है<br>अतः अवधारणा यह है कि डिजिटल मंच शीघ्र अधिक पाठकवर्ग तक पहुँचाते हैं<br><br><b>अतः सही उत्तर विकल्प (4): डिजिटल मंच बहुत शीघ्रता से अधिक व्यापक पाठकवर्ग तक पहुँचने में सहायक हैं। है।</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":23,"local_id":"50023","quid":"Q1000071303","section":"REASONING","topic":"Letter & Alphanumeric Series","question":{"en":"Fill in the blanks ( _ ) using one of the following four options such that the series follows a specific pattern in the given order.<br>m _ qr _ pqrmp _ rm _ qr [SSC CGL 23/10/26 Shift 3]","hi":"दी गई श्रेणी में एक विशिष्ट पैटर्न बना रहे, इसके लिए निम्नलिखित चार विकल्पों में से किसी एक का प्रयोग करके रिक्त स्थान ( _ ) भरिए।<br>m _ qr _ pqrmp _ rm _ qr [SSC CGL 23/10/26 Shift 3]"},"options":{"1":{"en":"pmpq"},"2":{"en":"mpqp"},"3":{"en":"pqmp"},"4":{"en":"mqpm"}},"answer":"1","solution":{"en":"Putting p, m, p and q in the four blanks gives m p q r m p q r m p p r m q q r<br>The block m p q r is repeated from the very first letter, since the first eight letters are m p q r m p q r<br>The other options break this block within the first eight letters itself<br>So the correct set of letters is pmpq<br><br><b>Hence, the correct answer is option (1): pmpq.</b>","hi":"चारों रिक्त स्थानों में p, m, p तथा q भरने पर m p q r m p q r m p p r m q q r प्राप्त होता है<br>प्रथम अक्षर से ही m p q r खंड दोहराया जाता है, क्योंकि पहले आठ अक्षर m p q r m p q r हैं<br>अन्य विकल्प पहले आठ अक्षरों में ही इस खंड को तोड़ देते हैं<br>अतः सही अक्षर-समूह pmpq है<br><br><b>अतः सही उत्तर विकल्प (1): pmpq है।</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":24,"local_id":"50024","quid":"Q1000071304","section":"REASONING","topic":"Figure Series & Figure Analogy","question":{"en":"Select a figure from amongst the alternatives that will continue the same series as established by the Problem Figures.<br><img src=\"https://res.cloudinary.com/mc6kb3uo/image/upload/ssc_mock/CGL-23-OCT-2026-SHIFT-3/q24.jpg\" style=\"max-width:100%;height:auto\"> [SSC CGL 23/10/26 Shift 3]","hi":"उन विकल्पों में से आकृति चुनिए जो समस्या आकृतियों द्वारा स्थापित उसी श्रेणी को आगे बढ़ाएगी।<br><img src=\"https://res.cloudinary.com/mc6kb3uo/image/upload/ssc_mock/CGL-23-OCT-2026-SHIFT-3/q24.jpg\" style=\"max-width:100%;height:auto\"> [SSC CGL 23/10/26 Shift 3]"},"options":{"1":{},"2":{},"3":{},"4":{}},"answer":"1","solution":{"en":"In each step the number of small dots increases by two, so the figures carry 1, 3, 5 and 7 dots and the next figure must carry 9 dots, arranged as three rows of three<br>The other three corners move through their symbols, and in the fourth problem figure the top left has a square, the top right an arrow pointing left and the bottom right a triangle<br>Continuing the series gives the pentagon at the top left, the arrow pointing up at the top right, the block of nine dots at the bottom left and the small circle at the bottom right<br>That is the figure printed as option 1, so the first alternative continues the series<br><br><b>Hence, the correct answer is option (1): <img src=\"https://res.cloudinary.com/mc6kb3uo/image/upload/ssc_mock/CGL-23-OCT-2026-SHIFT-3/q24_opt1.jpg\" style=\"max-width:100%;height:auto\">.</b>","hi":"प्रत्येक चरण में छोटे बिंदुओं की संख्या दो से बढ़ती है, अतः आकृतियों में 1, 3, 5 तथा 7 बिंदु हैं और अगली आकृति में 9 बिंदु, अर्थात् तीन-तीन की तीन पंक्तियाँ, होने चाहिए<br>अन्य तीन कोनों के चिह्न भी क्रम से बदलते हैं, और चौथी समस्या आकृति में ऊपर बाएँ वर्ग, ऊपर दाएँ बाईं ओर संकेत करता तीर तथा नीचे दाएँ त्रिभुज है<br>श्रेणी आगे बढ़ाने पर ऊपर बाएँ पंचभुज, ऊपर दाएँ ऊपर की ओर तीर, नीचे बाएँ नौ बिंदुओं का खंड तथा नीचे दाएँ छोटा वृत्त आता है<br>यही आकृति विकल्प 1 में छपी है, अतः पहला विकल्प श्रेणी को आगे बढ़ाता है<br><br><b>अतः सही उत्तर विकल्प (1): <img src=\"https://res.cloudinary.com/mc6kb3uo/image/upload/ssc_mock/CGL-23-OCT-2026-SHIFT-3/q24_opt1.jpg\" style=\"max-width:100%;height:auto\"> है।</b>"},"marks":{"correct":2,"negative":0.5},"has_image":true,"images":{"question":["https://res.cloudinary.com/mc6kb3uo/image/upload/ssc_mock/CGL-23-OCT-2026-SHIFT-3/q24.jpg"],"options":{"1":["https://res.cloudinary.com/mc6kb3uo/image/upload/ssc_mock/CGL-23-OCT-2026-SHIFT-3/q24_opt1.jpg"],"2":["https://res.cloudinary.com/mc6kb3uo/image/upload/ssc_mock/CGL-23-OCT-2026-SHIFT-3/q24_opt2.jpg"],"3":["https://res.cloudinary.com/mc6kb3uo/image/upload/ssc_mock/CGL-23-OCT-2026-SHIFT-3/q24_opt3.jpg"],"4":["https://res.cloudinary.com/mc6kb3uo/image/upload/ssc_mock/CGL-23-OCT-2026-SHIFT-3/q24_opt4.jpg"]},"solution":["https://res.cloudinary.com/mc6kb3uo/image/upload/ssc_mock/CGL-23-OCT-2026-SHIFT-3/q24_opt1.jpg"]}},{"no":25,"local_id":"50025","quid":"Q1000071305","section":"REASONING","topic":"Odd One Out","question":{"en":"Which number does not belong to the group? [SSC CGL 23/10/26 Shift 3]","hi":"कौन-सी संख्या समूह से संबंधित नहीं है? [SSC CGL 23/10/26 Shift 3]"},"options":{"1":{"en":"121"},"2":{"en":"169"},"3":{"en":"225"},"4":{"en":"289"}},"answer":"3","solution":{"en":"121 = 11 × 11, 169 = 13 × 13 and 289 = 17 × 17, so these three are squares of prime numbers<br>225 = 15 × 15, and 15 is not a prime number<br>So 225 does not belong to the group<br><br><b>Hence, the correct answer is option (3): 225.</b>","hi":"121 = 11 × 11, 169 = 13 × 13 तथा 289 = 17 × 17, अतः ये तीनों अभाज्य संख्याओं के वर्ग हैं<br>225 = 15 × 15, और 15 अभाज्य संख्या नहीं है<br>अतः 225 इस समूह से संबंधित नहीं है<br><br><b>अतः सही उत्तर विकल्प (3): 225 है।</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false}]},"GK":{"seconds":900,"questions":[{"no":26,"local_id":"50026","quid":"Q1000071306","section":"GK","topic":"Modern History: Gandhian Era","question":{"en":"Who launched the Champaran campaign in 1917? [SSC CGL 23/10/26 Shift 3]","hi":"1917 में चंपारण आंदोलन किसने आरंभ किया? [SSC CGL 23/10/26 Shift 3]"},"options":{"1":{"en":"Sardar Vallabhai Patel","hi":"सरदार वल्लभभाई पटेल"},"2":{"en":"Mahatma Gandhi","hi":"महात्मा गांधी"},"3":{"en":"Rabindranath Tagore","hi":"रवींद्रनाथ टैगोर"},"4":{"en":"Jyotiba Phule","hi":"ज्योतिबा फुले"}},"answer":"2","solution":{"en":"<b>Correct Answer: Option (2) – Mahatma Gandhi</b><br>The <b>Champaran Satyagraha of 1917</b> was launched by <b>Mahatma Gandhi</b> in Bihar against the exploitation of peasants forced by European planters to grow indigo under the tinkathia system.<br><br><br><b><u>Important Points:</u></b><br>• It was Gandhi's <b>first satyagraha in India</b>, undertaken at the request of Rajkumar Shukla, and it established his method of non-violent mass action.<br>• The government appointed the <b>Champaran Agrarian Committee</b>, which led to the Champaran Agrarian Act of 1918 and the abolition of tinkathia.<br>• Gandhi was assisted by <b>Rajendra Prasad, Brajkishore Prasad, Mahadev Desai, J.B. Kripalani and Anugraha Narayan Sinha</b>.<br>• The Kheda Satyagraha (1918) and the Ahmedabad mill strike (1918) followed Champaran; Vallabhbhai Patel led Kheda.<br><b>Correct option = (2)</b>, because Mahatma Gandhi launched the Champaran campaign in 1917.","hi":"<b>सही उत्तर: विकल्प (2) – महात्मा गांधी</b><br><b>1917 का चंपारण सत्याग्रह</b> <b>महात्मा गांधी</b> ने बिहार में उन किसानों के शोषण के विरुद्ध आरंभ किया, जिन्हें यूरोपीय नीलहेड़ों द्वारा तिनकठिया प्रथा के अंतर्गत नील उगाने के लिए बाध्य किया जाता था।<br><br><br><b><u>महत्वपूर्ण बिंदु:</u></b><br>• यह भारत में गांधी का <b>पहला सत्याग्रह</b> था, जो राजकुमार शुक्ल के अनुरोध पर हुआ और इसने उनकी अहिंसक जन-आंदोलन की पद्धति को स्थापित किया।<br>• सरकार ने <b>चंपारण कृषि समिति</b> नियुक्त की, जिससे 1918 का चंपारण कृषि अधिनियम आया और तिनकठिया प्रथा समाप्त हुई।<br>• गांधी को <b>राजेंद्र प्रसाद, ब्रजकिशोर प्रसाद, महादेव देसाई, जे. बी. कृपलानी तथा अनुग्रह नारायण सिन्हा</b> ने सहयोग दिया।<br>• चंपारण के बाद खेड़ा सत्याग्रह (1918) तथा अहमदाबाद मिल हड़ताल (1918) हुए; खेड़ा का नेतृत्व वल्लभभाई पटेल ने किया।<br><b>सही विकल्प = (2)</b>, क्योंकि 1917 में चंपारण आंदोलन महात्मा गांधी ने आरंभ किया।"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":27,"local_id":"50027","quid":"Q1000071307","section":"GK","topic":"Environment: Ecosystem","question":{"en":"Which plant is used as a bio-indicator to detect pollution from automobile exhaust? [SSC CGL 23/10/26 Shift 3]","hi":"किस पौधे का उपयोग मोटर वाहन निष्कासन (ऑटोमोबाइल एग्जॉस्ट) से होने वाले प्रदूषण के संसूचन हेतु जैव-संकेतक के रूप में किया जाता है? [SSC CGL 23/10/26 Shift 3]"},"options":{"1":{"en":"Tulsi","hi":"तुलसी"},"2":{"en":"Neem","hi":"नीम"},"3":{"en":"Lichen","hi":"लाइकेन"},"4":{"en":"Lettuce","hi":"सलाद पत्ता (Lettuce)"}},"answer":"3","solution":{"en":"<b>Correct Answer: Option (3) – Lichen</b><br><b>Lichens</b> are used as <b>bio-indicators</b> of air pollution, especially of <b>sulphur dioxide</b> and other pollutants from automobile exhaust, because they absorb nutrients directly through their surface and are highly sensitive even to low pollution levels.<br><br><br><b><u>Important Points:</u></b><br>• A lichen is a <b>symbiotic association</b> of an alga (or cyanobacterium) and a fungus; the fungus provides shelter and the alga prepares food.<br>• Lichens are absent or sparse in polluted cities and reappear as air quality improves, so they act as a <b>biological indicator of air quality</b>.<br>• Automobile exhaust releases <b>carbon monoxide, nitrogen oxides, hydrocarbons and particulate matter</b> along with sulphur dioxide.<br>• <b>Tulsi and neem</b> are medicinal plants valued for air purification, but they are not pollution indicators; lettuce is sensitive to ozone but lichens are the classic indicator.<br><b>Correct option = (3)</b>, because lichens are the bio-indicator of automobile exhaust pollution.","hi":"<b>सही उत्तर: विकल्प (3) – लाइकेन</b><br><b>लाइकेन (Lichen)</b> का उपयोग वायु प्रदूषण, विशेषतः मोटर वाहनों के निष्कासन से निकलने वाली <b>सल्फर डाइऑक्साइड</b> तथा अन्य प्रदूषकों के <b>जैव-संकेतक</b> के रूप में होता है, क्योंकि ये अपनी सतह से सीधे पोषक तत्व अवशोषित करते हैं और अल्प प्रदूषण के प्रति भी अत्यधिक संवेदनशील होते हैं।<br><br><br><b><u>महत्वपूर्ण बिंदु:</u></b><br>• लाइकेन शैवाल (या सायनोबैक्टीरिया) तथा कवक का <b>सहजीवी संबंध</b> है; कवक आश्रय देता है और शैवाल भोजन बनाता है।<br>• प्रदूषित नगरों में लाइकेन अनुपस्थित या विरल रहते हैं और वायु गुणवत्ता सुधरने पर लौट आते हैं, अतः ये <b>वायु गुणवत्ता के जैविक संकेतक</b> हैं।<br>• मोटर वाहन निष्कासन से <b>कार्बन मोनोऑक्साइड, नाइट्रोजन ऑक्साइड, हाइड्रोकार्बन तथा कणिकीय पदार्थ</b> के साथ सल्फर डाइऑक्साइड भी निकलती है।<br>• <b>तुलसी तथा नीम</b> वायु शुद्ध करने वाले औषधीय पौधे हैं, परंतु प्रदूषण संकेतक नहीं; सलाद पत्ता ओज़ोन के प्रति संवेदनशील है, किंतु प्रतिष्ठित संकेतक लाइकेन ही हैं।<br><b>सही विकल्प = (3)</b>, क्योंकि मोटर वाहन प्रदूषण का जैव-संकेतक लाइकेन है।"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":28,"local_id":"50028","quid":"Q1000071308","section":"GK","topic":"Static GK: Sports(Static & Current)","question":{"en":"What does the term \"Chukker\" refer to in polo? [SSC CGL 23/10/26 Shift 3]","hi":"पोलो में 'चक्कर' (Chukker) शब्द किससे संबंधित है? [SSC CGL 23/10/26 Shift 3]"},"options":{"1":{"en":"Type of penalty","hi":"दंड का प्रकार"},"2":{"en":"Number of players","hi":"खिलाड़ियों की संख्या"},"3":{"en":"A period of play","hi":"खेल की एक अवधि"},"4":{"en":"Horse breed","hi":"घोड़े की नस्ल"}},"answer":"3","solution":{"en":"<b>Correct Answer: Option (3) – A period of play</b><br>In polo, a <b>chukker</b> is a <b>period of play</b>; a match is divided into a fixed number of chukkers, each of about seven and a half minutes.<br><br><br><b><u>Important Points:</u></b><br>• A standard polo match has <b>four chukkers</b>, and each team has <b>four players</b> mounted on horses.<br>• The word 'polo' derives from the Tibetan 'pulu', meaning ball, and the game was popularised in India in Manipur (Sagol Kangjei).<br>• Polo is played on a ground of <b>300 yards by 160 yards</b>, and goals are scored by driving the ball between the posts.<br>• The <b>Indian Polo Association</b> governs the sport in India, and the Indian team has won several international tournaments.<br><b>Correct option = (3)</b>, because a chukker is a period of play in polo.","hi":"<b>सही उत्तर: विकल्प (3) – खेल की एक अवधि</b><br>पोलो में <b>चक्कर (Chukker)</b> <b>खेल की एक अवधि</b> होती है; एक मैच निश्चित संख्या के चक्करों में विभाजित होता है, जिनमें प्रत्येक लगभग साढ़े सात मिनट का होता है।<br><br><br><b><u>महत्वपूर्ण बिंदु:</u></b><br>• मानक पोलो मैच में <b>चार चक्कर</b> होते हैं तथा प्रत्येक टीम में घोड़ों पर सवार <b>चार खिलाड़ी</b> होते हैं।<br>• 'पोलो' शब्द तिब्बती 'पुलु' (गेंद) से बना है और यह खेल भारत में मणिपुर (सगोल कांगजेई) में लोकप्रिय हुआ।<br>• पोलो <b>300 गज × 160 गज</b> के मैदान में खेला जाता है और गोल खंभों के बीच गेंद पहुँचाकर किए जाते हैं।<br>• भारत में इस खेल का नियंत्रण <b>इंडियन पोलो एसोसिएशन</b> के पास है और भारतीय टीम ने कई अंतरराष्ट्रीय टूर्नामेंट जीते हैं।<br><b>सही विकल्प = (3)</b>, क्योंकि चक्कर पोलो में खेल की एक अवधि है।"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":29,"local_id":"50029","quid":"Q1000071309","section":"GK","topic":"Static GK: Sports(Static & Current)","question":{"en":"Which Indian chess grandmaster became the first to win the FIDE World Chess Championship in 2000? [SSC CGL 23/10/26 Shift 3]","hi":"कौन-से भारतीय शतरंज ग्रैंडमास्टर 2000 में FIDE विश्व शतरंज चैंपियनशिप जीतने वाले पहले खिलाड़ी बने? [SSC CGL 23/10/26 Shift 3]"},"options":{"1":{"en":"Viswanathan Anand","hi":"विश्वनाथन आनंद"},"2":{"en":"Pentala Harikrishna","hi":"पेंटाला हरिकृष्ण"},"3":{"en":"Vidit Gujrathi","hi":"विदित गुजराती"},"4":{"en":"Rameshbabu Praggnanandhaa","hi":"रमेशबाबू प्रग्गनानंद"}},"answer":"1","solution":{"en":"<b>Correct Answer: Option (1) – Viswanathan Anand</b><br><b>Viswanathan Anand</b> became the first Indian to win the <b>FIDE World Chess Championship</b> in <b>2000</b>, defeating Alexei Shirov in the final held at New Delhi and Tehran.<br><br><br><b><u>Important Points:</u></b><br>• Anand won the world title again in <b>2007, 2008, 2010 and 2012</b>, and was the first player to win the title in knockout, tournament and match formats.<br>• He was India's <b>first Grandmaster</b> (1988) and received the <b>Rajiv Gandhi Khel Ratna</b> (1991-92) and the Padma Vibhushan (2007).<br>• <b>D. Gukesh</b> became the youngest world chess champion in 2024 by defeating Ding Liren, and <b>R. Praggnanandhaa and Vidit Gujrathi</b> are leading Indian GMs.<br>• The FIDE headquarters is at <b>Lausanne, Switzerland</b>, and the All India Chess Federation runs the game in India.<br><b>Correct option = (1)</b>, because Viswanathan Anand won the FIDE world title in 2000.","hi":"<b>सही उत्तर: विकल्प (1) – विश्वनाथन आनंद</b><br><b>विश्वनाथन आनंद (Viswanathan Anand)</b> <b>2000</b> में नई दिल्ली और तेहरान में हुए फाइनल में अलेक्सई शिरोव को हराकर <b>FIDE विश्व शतरंज चैंपियनशिप</b> जीतने वाले पहले भारतीय बने।<br><br><br><b><u>महत्वपूर्ण बिंदु:</u></b><br>• आनंद ने <b>2007, 2008, 2010 तथा 2012</b> में पुनः विश्व खिताब जीता और वे नॉकआउट, टूर्नामेंट तथा मैच — तीनों प्रारूपों में खिताब जीतने वाले पहले खिलाड़ी थे।<br>• वे भारत के <b>प्रथम ग्रैंडमास्टर</b> (1988) थे और उन्हें <b>राजीव गांधी खेल रत्न</b> (1991-92) तथा पद्म विभूषण (2007) मिला।<br>• <b>डी. गुकेश</b> ने 2024 में डिंग लिरेन को हराकर सबसे युवा विश्व शतरंज चैंपियन का खिताब जीता, तथा <b>आर. प्रग्गनानंद एवं विदित गुजराती</b> अग्रणी भारतीय ग्रैंडमास्टर हैं।<br>• FIDE का मुख्यालय <b>लुसाने, स्विट्ज़रलैंड</b> में है और भारत में इस खेल का संचालन अखिल भारतीय शतरंज महासंघ करता है।<br><b>सही विकल्प = (1)</b>, क्योंकि 2000 में विश्वनाथन आनंद ने FIDE विश्व खिताब जीता।"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":30,"local_id":"50030","quid":"Q1000071310","section":"GK","topic":"Static GK: Music and Musical Instruments","question":{"en":"Consider the following statements about the musical instrument <b>Santoor</b>:<br>1. Santoor is a trapezoidal instrument .<br>2. It is traditionally associated with Kashmir.<br>3. It is primarily used in Carnatic music.<br>Which of the above statements is/are <b>correct</b>? [SSC CGL 23/10/26 Shift 3]","hi":"वाद्य यंत्र <b>संतूर</b> के बारे में निम्नलिखित कथनों पर विचार करें:<br>1. संतूर एक समलंबाकार (trapezoidal) वाद्य यंत्र है।<br>2. यह परंपरागत रूप से कश्मीर से संबंधित है।<br>3. इसका उपयोग मुख्यतः कर्नाटक संगीत में होता है।<br>उपर्युक्त में से कौन-से कथन <b>सही</b> है/हैं? [SSC CGL 23/10/26 Shift 3]"},"options":{"1":{"en":"1 and 2 only","hi":"केवल 1 तथा 2"},"2":{"en":"2 and 3 only","hi":"केवल 2 तथा 3"},"3":{"en":"1 and 3 only","hi":"केवल 1 तथा 3"},"4":{"en":"1,2 and 3 all","hi":"1, 2 तथा 3 सभी"}},"answer":"1","solution":{"en":"<b>Correct Answer: Option (1) – 1 and 2 only</b><br>The <b>santoor</b> is a <b>trapezoidal</b> hammered dulcimer played with light wooden mallets and is traditionally associated with <b>Kashmir</b>, but it belongs to <b>Hindustani</b> music, not Carnatic music.<br><br><br><b><u>Important Points:</u></b><br>• The santoor has a hundred strings (in the Kashmiri form) stretched over a wooden sound box and gives a shimmering, resonant tone.<br>• <b>Pandit Shivkumar Sharma</b> is credited with establishing the santoor as a solo Hindustani classical instrument.<br>• Other stringed instruments include the <b>sitar, sarod, veena (Carnatic) and sarangi</b>, while the tabla and mridangam are percussion instruments.<br>• Statement 3 is wrong because Carnatic music's string instruments are the <b>veena, violin and gottuvadhyam</b>.<br><b>Correct option = (1)</b>, because only statements 1 and 2 are correct.","hi":"<b>सही उत्तर: विकल्प (1) – केवल 1 तथा 2</b><br><b>संतूर</b> एक <b>समलंबाकार (trapezoidal)</b> तार वाद्य है, जिसे हल्की लकड़ी की मुँगरी से बजाया जाता है और यह परंपरागत रूप से <b>कश्मीर</b> से संबंधित है, परंतु यह <b>हिंदुस्तानी</b> संगीत का वाद्य है, कर्नाटक संगीत का नहीं।<br><br><br><b><u>महत्वपूर्ण बिंदु:</u></b><br>• संतूर में (कश्मीरी रूप में) सौ तार लकड़ी के स्वर-पेटी पर तने रहते हैं और यह चमकीली, गुंजायमान ध्वनि देता है।<br>• <b>पंडित शिवकुमार शर्मा</b> को संतूर को एकल हिंदुस्तानी शास्त्रीय वाद्य के रूप में स्थापित करने का श्रेय है।<br>• अन्य तार वाद्यों में <b>सितार, सरोद, वीणा (कर्नाटक) तथा सारंगी</b> आते हैं, जबकि तबला तथा मृदंग ताल वाद्य हैं।<br>• कथन 3 गलत है, क्योंकि कर्नाटक संगीत के तार वाद्य <b>वीणा, वायलिन तथा गोट्टुवाद्यम</b> हैं।<br><b>सही विकल्प = (1)</b>, क्योंकि केवल कथन 1 तथा 2 सही हैं।"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":31,"local_id":"50031","quid":"Q1000071311","section":"GK","topic":"Ancient History: Post-Maurya Dynasties","question":{"en":"Which material was used in the Mathura School for sculpting Buddha images? [SSC CGL 23/10/26 Shift 3]","hi":"मथुरा शैली में बुद्ध प्रतिमाओं के निर्माण हेतु किस सामग्री का उपयोग किया जाता था? [SSC CGL 23/10/26 Shift 3]"},"options":{"1":{"en":"Bronze","hi":"कांस्य"},"2":{"en":"Grey schist","hi":"धूसर शिस्ट"},"3":{"en":"Red sandstone","hi":"लाल बलुआ पत्थर"},"4":{"en":"Terracotta","hi":"टेराकोटा"}},"answer":"3","solution":{"en":"<b>Correct Answer: Option (3) – Red sandstone</b><br>The <b>Mathura school</b> of sculpture used <b>spotted red sandstone</b> from Sikri, which gives its Buddha images a warm reddish tone and a robust, fleshy modelling.<br><br><br><b><u>Important Points:</u></b><br>• The Mathura school flourished from the 1st century CE under the <b>Kushanas</b> and produced the earliest indigenous Buddha images, with a halo, right hand in abhaya mudra and a shaven head or ushnisha.<br>• The <b>Gandhara school</b> used <b>grey schist</b> and showed Hellenistic influence, with drapery and wavy hair, while <b>Amaravati</b> used white marble.<br>• <b>Bronze</b> images belong mainly to the later Chola and Pala periods, and terracotta was used for smaller figurines.<br>• Mathura was also a great centre of <b>Jain and Brahmanical</b> sculpture and of the Sarvastivada school of Buddhism.<br><b>Correct option = (3)</b>, because Mathura sculpture used red sandstone.","hi":"<b>सही उत्तर: विकल्प (3) – लाल बलुआ पत्थर</b><br>मूर्तिकला की <b>मथुरा शैली</b> में सीकरी के <b>चित्तीदार लाल बलुआ पत्थर</b> का उपयोग होता था, जिससे बुद्ध प्रतिमाओं में गर्म लालिमा तथा सुदृढ़, पुष्ट गठन दिखता है।<br><br><br><b><u>महत्वपूर्ण बिंदु:</u></b><br>• मथुरा शैली <b>कुषाणों</b> के अंतर्गत प्रथम शताब्दी ईस्वी से फली-फूली और उसने सबसे प्राचीन देशी बुद्ध प्रतिमाएँ बनाईं, जिनमें प्रभामंडल, अभय मुद्रा में दाहिना हाथ तथा मुंडित शीर्ष या उष्णीष होता था।<br>• <b>गांधार शैली</b> में <b>धूसर शिस्ट</b> का उपयोग होता था और उसमें यूनानी प्रभाव, वस्त्र-वल्लियाँ तथा घुँघराले बाल दिखते थे, जबकि <b>अमरावती</b> में श्वेत संगमरमर का।<br>• <b>कांस्य</b> प्रतिमाएँ मुख्यतः परवर्ती चोल तथा पाल काल की हैं और टेराकोटा का उपयोग छोटी मूर्तियों के लिए होता था।<br>• मथुरा <b>जैन तथा ब्राह्मणीय</b> मूर्तिकला का भी बड़ा केंद्र था और वहाँ सर्वास्तिवाद बौद्ध संप्रदाय सक्रिय था।<br><b>सही विकल्प = (3)</b>, क्योंकि मथुरा मूर्तिकला में लाल बलुआ पत्थर का उपयोग हुआ।"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":32,"local_id":"50032","quid":"Q1000071312","section":"GK","topic":"Ancient History: South Indian History & Tripartite Struggle and Cholas","question":{"en":"Read the following statements and choose the <b>correct</b> option.<br>1. Dravidian temples use Vimanas.<br>2. Gopurams serve as monumental gateways. [SSC CGL 23/10/26 Shift 3]","hi":"निम्नलिखित कथनों को पढ़ें और <b>सही</b> विकल्प चुनें।<br>1. द्रविड़ मंदिरों में विमान का उपयोग होता है।<br>2. गोपुरम भव्य प्रवेशद्वार के रूप में कार्य करते हैं। [SSC CGL 23/10/26 Shift 3]"},"options":{"1":{"en":"Only Statement 1 is correct.","hi":"केवल कथन 1 सही है।"},"2":{"en":"Only Statement 2 is correct.","hi":"केवल कथन 2 सही है।"},"3":{"en":"Both statements are correct.","hi":"दोनों कथन सही हैं।"},"4":{"en":"Neither statement is correct.","hi":"कोई भी कथन सही नहीं है।"}},"answer":"3","solution":{"en":"<b>Correct Answer: Option (3) – Both statements are correct.</b><br>In Dravidian temple architecture, the <b>vimana</b> is the pyramidal tower over the sanctum housing the deity, and the <b>gopuram</b> is the monumental gateway tower at the temple entrance; both statements are correct.<br><br><br><b><u>Important Points:</u></b><br>• The Dravidian style has four parts – <b>garbhagriha, vimana, mandapa and gopuram</b> – along with the courtyard enclosure and the temple tank.<br>• The <b>Brihadeshwara temple at Thanjavur</b> (Rajaraja Chola) has one of the tallest vimanas, while the <b>Meenakshi temple at Madurai</b> is famous for its gopurams.<br>• In the <b>Nagara (North Indian)</b> style the tower over the sanctum is called the <b>shikhara</b>, and the gateway is not normally a towering gopuram.<br>• Dravidian temples are enclosed within a compound wall and often have pillared halls called <b>mandapas</b> and thousand-pillared corridors.<br><b>Correct option = (3)</b>, because both the statements about vimanas and gopurams are correct.","hi":"<b>सही उत्तर: विकल्प (3) – दोनों कथन सही हैं।</b><br>द्रविड़ मंदिर वास्तुकला में <b>विमान</b> देवता के गर्भगृह के ऊपर का पिरामिडाकार शिखर होता है तथा <b>गोपुरम</b> मंदिर के प्रवेश पर भव्य द्वार-मीनार होता है; दोनों कथन सही हैं।<br><br><br><b><u>महत्वपूर्ण बिंदु:</u></b><br>• द्रविड़ शैली के चार भाग हैं – <b>गर्भगृह, विमान, मंडप तथा गोपुरम</b> – साथ ही प्रांगण-प्राचीर तथा मंदिर सरोवर।<br>• <b>तंजावुर का बृहदेश्वर मंदिर</b> (राजराज चोल) में सबसे ऊँचे विमानों में से एक है, जबकि <b>मदुरै का मीनाक्षी मंदिर</b> अपने गोपुरमों के लिए प्रसिद्ध है।<br>• <b>नागर (उत्तर भारतीय)</b> शैली में गर्भगृह के ऊपर का शिखर <b>शिखर</b> कहलाता है और प्रवेशद्वार सामान्यतः ऊँचा गोपुरम नहीं होता।<br>• द्रविड़ मंदिर प्राचीर से घिरे होते हैं और उनमें स्तंभयुक्त मंडप तथा सहस्र-स्तंभ मंडप होते हैं।<br><b>सही विकल्प = (3)</b>, क्योंकि विमान तथा गोपुरम से संबंधित दोनों कथन सही हैं।"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":33,"local_id":"50033","quid":"Q1000071313","section":"GK","topic":"Current Affairs: Government Schemes and Policies (Current)","question":{"en":"Which scheme is aimed at promoting entrepreneurship among SC/ST and women entrepreneurs? [SSC CGL 23/10/26 Shift 3]","hi":"कौन-सी योजना अनुसूचित जाति/अनुसूचित जनजाति तथा महिला उद्यमियों में उद्यमशीलता को बढ़ावा देने का लक्ष्य रखती है? [SSC CGL 23/10/26 Shift 3]"},"options":{"1":{"en":"Pradhan Mantri Kaushal Vikas Yojana","hi":"प्रधानमंत्री कौशल विकास योजना"},"2":{"en":"Start-Up India","hi":"स्टार्ट-अप इंडिया"},"3":{"en":"Stand-Up India Scheme","hi":"स्टैंड-अप इंडिया योजना"},"4":{"en":"Skill India Mission","hi":"स्किल इंडिया मिशन"}},"answer":"3","solution":{"en":"<b>Correct Answer: Option (3) – Stand-Up India Scheme</b><br>The <b>Stand-Up India Scheme</b>, launched in 2016, facilitates bank loans of <b>₹10 lakh to ₹1 crore</b> to at least one SC/ST and one woman entrepreneur per bank branch for setting up a greenfield enterprise.<br><br><br><b><u>Important Points:</u></b><br>• The scheme covers manufacturing, services and trading, and the loan is a composite loan including working capital, with a moratorium of up to 18 months.<br>• It is implemented through the <b>Department of Financial Services</b> with SIDBI providing hand-holding support.<br>• <b>Start-up India (2016)</b> promotes new enterprises generally, <b>PMKVY</b> and <b>Skill India</b> focus on skilling, not entrepreneurship finance.<br>• Stand-Up India addresses the credit gap faced by women and SC/ST entrepreneurs, who often lack collateral and formal credit history.<br><b>Correct option = (3)</b>, because Stand-Up India targets SC/ST and women entrepreneurs.","hi":"<b>सही उत्तर: विकल्प (3) – स्टैंड-अप इंडिया योजना</b><br>2016 में शुरू <b>स्टैंड-अप इंडिया योजना</b> प्रत्येक बैंक शाखा में कम से कम एक अनुसूचित जाति/जनजाति तथा एक महिला उद्यमी को ग्रीनफील्ड उद्यम स्थापित करने के लिए <b>₹10 लाख से ₹1 करोड़</b> तक का बैंक ऋण सुलभ कराती है।<br><br><br><b><u>महत्वपूर्ण बिंदु:</u></b><br>• योजना विनिर्माण, सेवा तथा व्यापार को सम्मिलित करती है और ऋण कार्यशील पूँजी सहित मिश्रित ऋण है, जिसमें 18 माह तक की मोहलत होती है।<br>• इसे <b>वित्तीय सेवाएँ विभाग</b> क्रियान्वित करता है, तथा SIDBI हस्तधारण सहायता देता है।<br>• <b>स्टार्ट-अप इंडिया (2016)</b> सामान्य रूप से नए उद्यमों को बढ़ावा देता है, जबकि <b>PMKVY</b> तथा <b>स्किल इंडिया</b> कौशल पर केंद्रित हैं, उद्यम वित्त पर नहीं।<br>• स्टैंड-अप इंडिया महिलाओं तथा SC/ST उद्यमियों की उस ऋण-अंतराल को दूर करती है जो प्रायः जमानत तथा औपचारिक ऋण-इतिहास के अभाव में होती है।<br><b>सही विकल्प = (3)</b>, क्योंकि स्टैंड-अप इंडिया SC/ST तथा महिला उद्यमियों को लक्षित करती है।"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":34,"local_id":"50034","quid":"Q1000071314","section":"GK","topic":"Current Affairs: Appointments and Resignations","question":{"en":"Who is the Comptroller and Auditor General (CAG) of India in 2025? [SSC CGL 23/10/26 Shift 3]","hi":"2025 में भारत के नियंत्रक एवं महालेखापरीक्षक (CAG) कौन हैं? [SSC CGL 23/10/26 Shift 3]"},"options":{"1":{"en":"Rajiv Mehrishi","hi":"राजीव महर्षि"},"2":{"en":"Shashi Kant Sharma","hi":"शशिकांत शर्मा"},"3":{"en":"K. Sanjay Murthy","hi":"के. संजय मूर्ति"},"4":{"en":"Girish Chandra Murmu","hi":"गिरीश चंद्र मुर्मू"}},"answer":"3","solution":{"en":"<b>Correct Answer: Option (3) – K. Sanjay Murthy</b><br><b>K. Sanjay Murthy</b> took office as the <b>Comptroller and Auditor General of India</b> in <b>November 2024</b>, succeeding Girish Chandra Murmu, and continues as CAG in 2025.<br><br><br><b><u>Important Points:</u></b><br>• The CAG is appointed by the <b>President</b> under Article 148 and holds office for <b>six years or up to 65 years of age</b>, whichever is earlier.<br>• The CAG is called the <b>guardian of the public purse</b> and audits all receipts and expenditure of the Union and the states.<br>• <b>Girish Chandra Murmu</b> was CAG from 2020 to 2024, <b>Rajiv Mehrishi</b> from 2017 to 2020 and <b>Shashi Kant Sharma</b> from 2013 to 2017.<br>• The CAG's reports are examined by the <b>Public Accounts Committee</b> of Parliament, and the CAG is removed only in the manner of a Supreme Court judge.<br><b>Correct option = (3)</b>, because K. Sanjay Murthy is the CAG of India in 2025.","hi":"<b>सही उत्तर: विकल्प (3) – के. संजय मूर्ति</b><br><b>के. संजय मूर्ति (K. Sanjay Murthy)</b> ने <b>नवंबर 2024</b> में गिरीश चंद्र मुर्मू के स्थान पर <b>भारत के नियंत्रक एवं महालेखापरीक्षक</b> का पदभार ग्रहण किया और 2025 में भी CAG हैं।<br><br><br><b><u>महत्वपूर्ण बिंदु:</u></b><br>• CAG की नियुक्ति <b>राष्ट्रपति</b> अनुच्छेद 148 के अंतर्गत करता है और उसका कार्यकाल <b>छह वर्ष या 65 वर्ष की आयु</b> तक, जो पहले हो, होता है।<br>• CAG को <b>लोक कोष का संरक्षक</b> कहा जाता है और वह संघ तथा राज्यों की समस्त प्राप्तियों एवं व्ययों का लेखापरीक्षण करता है।<br>• <b>गिरीश चंद्र मुर्मू</b> 2020 से 2024 तक, <b>राजीव महर्षि</b> 2017 से 2020 तक तथा <b>शशिकांत शर्मा</b> 2013 से 2017 तक CAG रहे।<br>• CAG के प्रतिवेदन संसद की <b>लोक लेखा समिति</b> द्वारा परीक्षित होते हैं, तथा CAG को केवल सर्वोच्च न्यायालय के न्यायाधीश की रीति से ही हटाया जा सकता है।<br><b>सही विकल्प = (3)</b>, क्योंकि 2025 में के. संजय मूर्ति भारत के CAG हैं।"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":35,"local_id":"50035","quid":"Q1000071315","section":"GK","topic":"Environment: National Parks","question":{"en":"Which Indian state's Eravikulam National Park closed for the Nilgiri Tahr calving season in February 2025? [SSC CGL 23/10/26 Shift 3]","hi":"फरवरी 2025 में नीलगिरि तहर के बच्चे जनने के मौसम के कारण किस भारतीय राज्य का एराविकुलम राष्ट्रीय उद्यान बंद किया गया? [SSC CGL 23/10/26 Shift 3]"},"options":{"1":{"en":"Tamil Nadu","hi":"तमिलनाडु"},"2":{"en":"Kerala","hi":"केरल"},"3":{"en":"Karnataka","hi":"कर्नाटक"},"4":{"en":"Andhra Pradesh","hi":"आंध्र प्रदेश"}},"answer":"2","solution":{"en":"<b>Correct Answer: Option (2) – Kerala</b><br><b>Eravikulam National Park</b> in <b>Kerala</b>, near Munnar in Idukki district, is closed to visitors every year during the <b>calving season of the Nilgiri Tahr</b>, and the closure in February 2025 followed this practice.<br><br><br><b><u>Important Points:</u></b><br>• Eravikulam is famous for the largest surviving population of the <b>Nilgiri Tahr (Nilgiritragus hylocrius)</b>, the state animal of Tamil Nadu.<br>• It is also home to the <b>Neelakurinji</b> flower, which blooms once in about 12 years, and to Anamudi, the highest peak in South India.<br>• The park was declared a <b>national park in 1978</b> and is part of the Western Ghats and a UNESCO World Heritage site.<br>• Other tahr habitats include the <b>Mukurthi and Anamalai hills</b> in Tamil Nadu's Nilgiris, but Eravikulam lies in Kerala.<br><b>Correct option = (2)</b>, because Eravikulam National Park is in Kerala.","hi":"<b>सही उत्तर: विकल्प (2) – केरल</b><br>इडुक्की जिले के मुन्नार के निकट <b>केरल</b> स्थित <b>एराविकुलम राष्ट्रीय उद्यान</b> प्रत्येक वर्ष <b>नीलगिरि तहर के बच्चे जनने के मौसम</b> में पर्यटकों के लिए बंद रहता है, और फरवरी 2025 में बंदी इसी परंपरा के अनुसार हुई।<br><br><br><b><u>महत्वपूर्ण बिंदु:</u></b><br>• एराविकुलम <b>नीलगिरि तहर (Nilgiritragus hylocrius)</b> की सर्वाधिक शेष आबादी के लिए प्रसिद्ध है, जो तमिलनाडु का राज्य पशु है।<br>• यहाँ <b>नीलकुरिंजी</b> फूल भी मिलता है, जो लगभग 12 वर्ष में एक बार खिलता है, तथा दक्षिण भारत की सर्वोच्च चोटी अनामुडी भी यहीं है।<br>• उद्यान को <b>1978 में राष्ट्रीय उद्यान</b> घोषित किया गया और यह पश्चिमी घाट तथा यूनेस्को विश्व धरोहर स्थल का भाग है।<br>• तहर के अन्य आवास तमिलनाडु के नीलगिरि में <b>मुकुर्थी तथा अन्नामलाई पहाड़ियाँ</b> हैं, परंतु एराविकुलम केरल में है।<br><b>सही विकल्प = (2)</b>, क्योंकि एराविकुलम राष्ट्रीय उद्यान केरल में है।"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":36,"local_id":"50036","quid":"Q1000071316","section":"GK","topic":"Polity: New Criminal Laws 2023","question":{"en":"What does the term \"audio-video electronic means\" include under BNSS, 2023? [SSC CGL 23/10/26 Shift 3]","hi":"भारतीय नागरिक सुरक्षा संहिता (BNSS), 2023 के अंतर्गत 'श्रव्य-दृश्य इलेक्ट्रॉनिक माध्यम' (audio-video electronic means) शब्द में क्या सम्मिलित है? [SSC CGL 23/10/26 Shift 3]"},"options":{"1":{"en":"Telephonic conversations only","hi":"केवल दूरभाष वार्तालाप"},"2":{"en":"Written correspondence through post","hi":"डाक द्वारा लिखित पत्राचार"},"3":{"en":"Video conferencing and electronic communication devices","hi":"वीडियो कॉन्फ्रेंसिंग तथा इलेक्ट्रॉनिक संचार उपकरण"},"4":{"en":"Telegram or fax only","hi":"केवल टेलीग्राम या फैक्स"}},"answer":"3","solution":{"en":"<b>Correct Answer: Option (3) – Video conferencing and electronic communication devices</b><br>Under the <b>Bharatiya Nagarik Suraksha Sanhita, 2023</b>, 'audio-video electronic means' includes <b>video conferencing and other electronic communication devices</b> by which a person can be seen and heard, such as mobile phones and computers.<br><br><br><b><u>Important Points:</u></b><br>• The BNSS expressly allows the use of audio-video electronic means for <b>recording confessions, conducting searches, examining witnesses and holding trials</b>.<br>• <b>Section 35</b> requires the arrest and the grounds of arrest to be informed, and the BNSS provides for <b>electronic service of summons</b> and notices.<br>• The provision supports the policy of <b>digital courts and e-evidence</b>, reducing the need to transport undertrials and witnesses.<br>• Telephonic conversation alone, postal correspondence and telegram or fax do not satisfy the definition of audio-video electronic means.<br><b>Correct option = (3)</b>, because the term covers video conferencing and electronic communication devices.","hi":"<b>सही उत्तर: विकल्प (3) – वीडियो कॉन्फ्रेंसिंग तथा इलेक्ट्रॉनिक संचार उपकरण</b><br><b>भारतीय नागरिक सुरक्षा संहिता, 2023</b> के अंतर्गत 'श्रव्य-दृश्य इलेक्ट्रॉनिक माध्यम' में <b>वीडियो कॉन्फ्रेंसिंग तथा अन्य इलेक्ट्रॉनिक संचार उपकरण</b> सम्मिलित हैं, जिनसे व्यक्ति को देखा और सुना जा सकता है, जैसे मोबाइल फोन तथा कंप्यूटर।<br><br><br><b><u>महत्वपूर्ण बिंदु:</u></b><br>• BNSS श्रव्य-दृश्य इलेक्ट्रॉनिक माध्यम के उपयोग को <b>कबूलनामा रिकॉर्ड करने, तलाशी लेने, गवाहों की परीक्षा तथा विचारण</b> के लिए स्पष्ट रूप से अनुमत करती है।<br>• <b>धारा 35</b> में गिरफ्तारी तथा गिरफ्तारी के आधार की सूचना देना आवश्यक है, और BNSS में <b>समन तथा नोटिस की इलेक्ट्रॉनिक तामील</b> का प्रावधान है।<br>• यह प्रावधान <b>डिजिटल न्यायालय तथा ई-साक्ष्य</b> की नीति को सहारा देता है, जिससे विचाराधीन बंदियों तथा गवाहों को लाने-ले जाने की आवश्यकता घटती है।<br>• केवल दूरभाष वार्तालाप, डाक पत्राचार तथा टेलीग्राम या फैक्स श्रव्य-दृश्य इलेक्ट्रॉनिक माध्यम की परिभाषा में नहीं आते।<br><b>सही विकल्प = (3)</b>, क्योंकि इस शब्द में वीडियो कॉन्फ्रेंसिंग तथा इलेक्ट्रॉनिक संचार उपकरण सम्मिलित हैं।"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":37,"local_id":"50037","quid":"Q1000071317","section":"GK","topic":"Chemistry: Matter","question":{"en":"What is the process of converting a solid directly into gas called? [SSC CGL 23/10/26 Shift 3]","hi":"किसी ठोस को सीधे गैस में परिवर्तित करने की प्रक्रिया को क्या कहा जाता है? [SSC CGL 23/10/26 Shift 3]"},"options":{"1":{"en":"Evaporation","hi":"वाष्पीकरण"},"2":{"en":"Sublimation","hi":"उर्ध्वपातन"},"3":{"en":"Condensation","hi":"संघनन"},"4":{"en":"Deposition","hi":"निक्षेपण"}},"answer":"2","solution":{"en":"<b>Correct Answer: Option (2) – Sublimation</b><br>The direct change of a <b>solid into gas</b> without passing through the liquid state is called <b>sublimation</b>, as seen in camphor, naphthalene, iodine and dry ice.<br><br><br><b><u>Important Points:</u></b><br>• The reverse process, gas changing directly into solid, is called <b>deposition</b>.<br>• <b>Evaporation</b> is the change of a liquid into vapour at the surface, and <b>condensation</b> is vapour changing into liquid.<br>• Substances that sublime have a high vapour pressure at a temperature below their melting point.<br>• Sublimation is used in <b>freeze drying, purification of iodine and separating camphor from sand</b>.<br><b>Correct option = (2)</b>, because solid to gas directly is sublimation.","hi":"<b>सही उत्तर: विकल्प (2) – उर्ध्वपातन</b><br>द्रव अवस्था से गुज़रे बिना <b>ठोस के सीधे गैस में</b> परिवर्तित होने की प्रक्रिया <b>उर्ध्वपातन (Sublimation)</b> कहलाती है, जैसे कपूर, नैफ्थलीन, आयोडीन तथा शुष्क बर्फ में।<br><br><br><b><u>महत्वपूर्ण बिंदु:</u></b><br>• विपरीत प्रक्रिया, अर्थात गैस का सीधे ठोस में बदलना, <b>निक्षेपण (Deposition)</b> कहलाती है।<br>• <b>वाष्पीकरण</b> द्रव के सतह से वाष्प में बदलने की प्रक्रिया है, तथा <b>संघनन</b> वाष्प के द्रव में बदलने की।<br>• उर्ध्वपातन करने वाले पदार्थों का गलनांक से नीचे के तापमान पर वाष्प दाब ऊँचा होता है।<br>• उर्ध्वपातन का उपयोग <b>फ्रीज़ ड्राइंग, आयोडीन के शुद्धीकरण तथा कपूर को रेत से पृथक करने</b> में होता है।<br><b>सही विकल्प = (2)</b>, क्योंकि ठोस से सीधे गैस बनना उर्ध्वपातन है।"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":38,"local_id":"50038","quid":"Q1000071318","section":"GK","topic":"Geography: Himalayas","question":{"en":"The Himalayan mountain system is an example of: [SSC CGL 23/10/26 Shift 3]","hi":"हिमालय पर्वत प्रणाली किसका उदाहरण है? [SSC CGL 23/10/26 Shift 3]"},"options":{"1":{"en":"Block mountains","hi":"ब्लॉक पर्वत"},"2":{"en":"Residual mountains","hi":"अवशिष्ट पर्वत"},"3":{"en":"Fold mountains","hi":"वलित पर्वत"},"4":{"en":"Volcanic mountains","hi":"ज्वालामुखी पर्वत"}},"answer":"3","solution":{"en":"<b>Correct Answer: Option (3) – Fold mountains</b><br>The <b>Himalayas</b> are <b>fold mountains</b>, formed by the collision of the Indian Plate with the Eurasian Plate, which crumpled and folded the sedimentary rocks of the Tethys Sea floor.<br><br><br><b><u>Important Points:</u></b><br>• Fold mountains form at <b>convergent plate boundaries</b>; the Himalayas, the Alps and the Andes are the main examples.<br>• The Himalayas comprise the <b>Trans-Himalaya, Greater Himalaya (Himadri), Lesser Himalaya (Himachal) and the Shiwaliks</b>.<br>• <b>Block mountains</b> form by faulting (Vosges, Black Forest) and <b>volcanic mountains</b> by lava accumulation (Mt Fuji, Mt Etna).<br>• <b>Residual mountains</b> are eroded remains of older uplands, such as the Aravallis and the Vindhyas.<br><b>Correct option = (3)</b>, because the Himalayas are fold mountains.","hi":"<b>सही उत्तर: विकल्प (3) – वलित पर्वत</b><br><b>हिमालय</b> <b>वलित पर्वत</b> है, जो भारतीय प्लेट के यूरेशियाई प्लेट से टकराने से बना, जिससे टेथिस सागर के तल की तलछटी चट्टानें मुड़कर वलित हो गईं।<br><br><br><b><u>महत्वपूर्ण बिंदु:</u></b><br>• वलित पर्वत <b>अभिसारी प्लेट सीमाओं</b> पर बनते हैं; हिमालय, आल्प्स तथा एंडीज़ इसके प्रमुख उदाहरण हैं।<br>• हिमालय में <b>ट्रांस-हिमालय, वृहद हिमालय (हिमाद्रि), लघु हिमालय (हिमाचल) तथा शिवालिक</b> सम्मिलित हैं।<br>• <b>ब्लॉक पर्वत</b> भ्रंशन से बनते हैं (वॉस्जेज़, ब्लैक फॉरेस्ट) तथा <b>ज्वालामुखी पर्वत</b> लावा जमा होने से (माउंट फ़ूजी, माउंट एटना)।<br>• <b>अवशिष्ट पर्वत</b> पुराने ऊँचे भूभागों के अपरदित अवशेष हैं, जैसे अरावली तथा विंध्य।<br><b>सही विकल्प = (3)</b>, क्योंकि हिमालय वलित पर्वत है।"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":39,"local_id":"50039","quid":"Q1000071319","section":"GK","topic":"Medieval History: Marathas","question":{"en":"The Treaty of Purandar (1665) was signed between Shivaji and which Mughal general? [SSC CGL 23/10/26 Shift 3]","hi":"पुरंदर की संधि (1665) शिवाजी तथा किस मुगल सेनापति के बीच हुई थी? [SSC CGL 23/10/26 Shift 3]"},"options":{"1":{"en":"Shaista Khan","hi":"शाइस्ता खान"},"2":{"en":"Jai Singh I","hi":"जय सिंह प्रथम"},"3":{"en":"Aurangzeb","hi":"औरंगज़ेब"},"4":{"en":"Murad Baksh","hi":"मुराद बख्श"}},"answer":"2","solution":{"en":"<b>Correct Answer: Option (2) – Jai Singh I</b><br>The <b>Treaty of Purandar (1665)</b> was concluded between <b>Chhatrapati Shivaji</b> and the Mughal general <b>Mirza Raja Jai Singh I</b>, after Jai Singh besieged the Purandar fort.<br><br><br><b><u>Important Points:</u></b><br>• By the treaty Shivaji surrendered <b>23 of his 35 forts</b> and agreed to visit the Mughal court, where he was later put under house arrest at Agra in 1666 and escaped.<br>• Jai Singh I was the Mughal governor of the Deccan and a <b>Kachhwaha Rajput ruler of Amber</b>, and he was assisted by Dilir Khan.<br>• <b>Shaista Khan</b> was Aurangzeb's uncle and governor of the Deccan whom Shivaji attacked in 1663; <b>Murad Baksh</b> was Aurangzeb's brother.<br>• Shivaji was crowned <b>Chhatrapati at Raigad in 1674</b>, and he had earlier signed the Treaty of Purandar as a Mughal vassal before rebelling again.<br><b>Correct option = (2)</b>, because the Treaty of Purandar was signed with Jai Singh I.","hi":"<b>सही उत्तर: विकल्प (2) – जय सिंह प्रथम</b><br><b>पुरंदर की संधि (1665)</b> <b>छत्रपति शिवाजी</b> तथा मुगल सेनापति <b>मिर्जा राजा जय सिंह प्रथम</b> के बीच हुई, जब जय सिंह ने पुरंदर किले को घेर लिया था।<br><br><br><b><u>महत्वपूर्ण बिंदु:</u></b><br>• संधि द्वारा शिवाजी ने अपने <b>35 में से 23 किले</b> समर्पित किए और मुगल दरबार जाने पर सहमति दी, जहाँ 1666 में आगरा में उन्हें नज़रबंद किया गया और वे भाग निकले।<br>• जय सिंह प्रथम दक्कन के मुगल गवर्नर तथा <b>आमेर के कछवाहा राजपूत शासक</b> थे, और दिलीर खान उनका सहायक था।<br>• <b>शाइस्ता खान</b> औरंगज़ेब के मामा तथा दक्कन के गवर्नर थे, जिन पर शिवाजी ने 1663 में आक्रमण किया; <b>मुराद बख्श</b> औरंगज़ेब के भाई थे।<br>• शिवाजी का राज्याभिषेक <b>1674 में रायगढ़ में छत्रपति</b> के रूप में हुआ, और इससे पहले उन्होंने मुगल सामंत के रूप में पुरंदर की संधि की थी, फिर पुनः विद्रोह किया।<br><b>सही विकल्प = (2)</b>, क्योंकि पुरंदर की संधि जय सिंह प्रथम के साथ हुई थी।"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":40,"local_id":"50040","quid":"Q1000071320","section":"GK","topic":"Polity: Local Government","question":{"en":"Name of the tribal panchayat in Kerala? [SSC CGL 23/10/26 Shift 3]","hi":"केरल में जनजातीय पंचायत का नाम क्या है? [SSC CGL 23/10/26 Shift 3]"},"options":{"1":{"en":"Attappady","hi":"अट्टापाडी"},"2":{"en":"Sholayur","hi":"शोलायूर"},"3":{"en":"Edamalakkudy","hi":"एडामलक्कुडी"},"4":{"en":"Amboori","hi":"अंबूरी"}},"answer":"3","solution":{"en":"<b>Correct Answer: Option (3) – Edamalakkudy</b><br><b>Edamalakkudy</b>, in the Munnar region of Idukki district, is Kerala's <b>first tribal grama panchayat</b>, formed in 2010 and inhabited mainly by the <b>Muthuvan</b> tribal community.<br><br><br><b><u>Important Points:</u></b><br>• Edamalakkudy is one of the most remote panchayats in Kerala, located inside the <b>Munnar wildlife division</b> and accessible only on foot.<br>• <b>Attappady</b> is a tribal development block in Palakkad district, home to Irula, Muduga and Kurumba communities, and <b>Sholayur and Amboori</b> are panchayats in Palakkad and Thiruvananthapuram districts.<br>• Kerala's major tribal groups include the <b>Muthuvan, Irula, Kurumba, Kadar, Paniya and Cholanaickan</b>.<br>• The <b>Fifth Schedule</b> of the Constitution deals with Scheduled Areas and Scheduled Tribes in states other than the north-east.<br><b>Correct option = (3)</b>, because Edamalakkudy is the tribal panchayat of Kerala.","hi":"<b>सही उत्तर: विकल्प (3) – एडामलक्कुडी</b><br>इडुक्की जिले के मुन्नार क्षेत्र में स्थित <b>एडामलक्कुडी (Edamalakkudy)</b> केरल की <b>प्रथम जनजातीय ग्राम पंचायत</b> है, जो 2010 में बनी और जहाँ मुख्यतः <b>मुथुवन</b> जनजाति निवास करती है।<br><br><br><b><u>महत्वपूर्ण बिंदु:</u></b><br>• एडामलक्कुडी केरल की सर्वाधिक दूरस्थ पंचायतों में है, जो <b>मुन्नार वन्यजीव प्रभाग</b> के भीतर स्थित है और केवल पैदल पहुँची जा सकती है।<br>• <b>अट्टापाडी</b> पालक्काड जिले का जनजातीय विकास खंड है, जहाँ इरुला, मुदुगा तथा कुरुम्बा समुदाय रहते हैं, और <b>शोलायूर तथा अंबूरी</b> क्रमशः पालक्काड तथा तिरुवनंतपुरम जिलों की पंचायतें हैं।<br>• केरल के प्रमुख जनजातीय समूहों में <b>मुथुवन, इरुला, कुरुम्बा, कादर, पनिया तथा चोलनाइकन</b> सम्मिलित हैं।<br>• संविधान की <b>पाँचवीं अनुसूची</b> उत्तर-पूर्व के अतिरिक्त राज्यों के अनुसूचित क्षेत्रों तथा अनुसूचित जनजातियों से संबंधित है।<br><b>सही विकल्प = (3)</b>, क्योंकि एडामलक्कुडी केरल की जनजातीय पंचायत है।"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":41,"local_id":"50041","quid":"Q1000071321","section":"GK","topic":"Polity: Constitutional and Non-Constitutional Bodies","question":{"en":"______ was the first Comptroller and Auditor General of India. [SSC CGL 23/10/26 Shift 3]","hi":"______ भारत के प्रथम नियंत्रक एवं महालेखापरीक्षक थे। [SSC CGL 23/10/26 Shift 3]"},"options":{"1":{"en":"Rajendra Prasad","hi":"राजेंद्र प्रसाद"},"2":{"en":"V. Narahari Rao","hi":"वी. नरहरि राव"},"3":{"en":"George Mathai","hi":"जॉर्ज मथाई"},"4":{"en":"Vil as rao Deshmukh","hi":"विलासराव देशमुख"}},"answer":"2","solution":{"en":"<b>Correct Answer: Option (2) – V. Narahari Rao</b><br><b>V. Narahari Rao</b> was the <b>first Comptroller and Auditor General of India</b>, serving from <b>1948 to 1954</b>, after India became independent and the office was reconstituted under the Constitution.<br><br><br><b><u>Important Points:</u></b><br>• Before him, the Auditor General of India under the Government of India Act, 1935 was <b>Sir Bertie Staig</b>, and Narahari Rao took charge as Auditor General in 1944 and continued as the first CAG under the Constitution.<br>• The CAG is appointed under <b>Article 148</b> and is described as the guardian of the public purse.<br>• <b>George Mathai</b> was the second CAG (1954-1960), and <b>Rajendra Prasad</b> was India's first President.<br>• The CAG audits the accounts of the Union, states and government companies and submits reports to the President and governors.<br><b>Correct option = (2)</b>, because V. Narahari Rao was the first CAG of India.","hi":"<b>सही उत्तर: विकल्प (2) – वी. नरहरि राव</b><br><b>वी. नरहरि राव (V. Narahari Rao)</b> <b>भारत के प्रथम नियंत्रक एवं महालेखापरीक्षक</b> थे, जिन्होंने स्वतंत्रता के बाद संविधान के अंतर्गत इस पद के पुनर्गठन पर <b>1948 से 1954</b> तक कार्य किया।<br><br><br><b><u>महत्वपूर्ण बिंदु:</u></b><br>• उनसे पहले भारत सरकार अधिनियम, 1935 के अंतर्गत महालेखापरीक्षक <b>सर बर्टी स्टेग</b> थे; नरहरि राव 1944 में महालेखापरीक्षक बने और संविधान के अंतर्गत प्रथम CAG रहे।<br>• CAG की नियुक्ति <b>अनुच्छेद 148</b> के अंतर्गत होती है और उसे लोक कोष का संरक्षक कहा जाता है।<br>• <b>जॉर्ज मथाई</b> द्वितीय CAG (1954-1960) थे, तथा <b>राजेंद्र प्रसाद</b> भारत के प्रथम राष्ट्रपति थे।<br>• CAG संघ, राज्यों तथा सरकारी कंपनियों के लेखों का परीक्षण करता है और प्रतिवेदन राष्ट्रपति तथा राज्यपालों को देता है।<br><b>सही विकल्प = (2)</b>, क्योंकि भारत के प्रथम CAG वी. नरहरि राव थे।"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":42,"local_id":"50042","quid":"Q1000071322","section":"GK","topic":"Science and Technology: Science and Technology","question":{"en":"What is the function of India's NavIC system? [SSC CGL 23/10/26 Shift 3]","hi":"भारत की NavIC प्रणाली का क्या कार्य है? [SSC CGL 23/10/26 Shift 3]"},"options":{"1":{"en":"Solar imaging","hi":"सौर चित्रण"},"2":{"en":"Climate modeling","hi":"जलवायु मॉडलिंग"},"3":{"en":"Satellite TV broadcasting","hi":"उपग्रह टीवी प्रसारण"},"4":{"en":"Regional navigation","hi":"क्षेत्रीय नौवहन"}},"answer":"4","solution":{"en":"<b>Correct Answer: Option (4) – Regional navigation</b><br><b>NavIC (Navigation with Indian Constellation)</b> is India's regional satellite navigation system, providing accurate position, navigation and timing services over India and a surrounding region of about 1,500 km.<br><br><br><b><u>Important Points:</u></b><br>• NavIC, earlier called <b>IRNSS</b>, is built by ISRO and consists of a constellation of satellites in geostationary and geosynchronous orbits.<br>• It offers a <b>Standard Positioning Service</b> for general users and a <b>Restricted Service</b> for strategic users.<br>• NavIC supports <b>vehicle tracking, disaster management, fisheries, surveying and the 'Khanan' and 'Poshan' applications</b>.<br>• Solar imaging is done by missions such as Aditya-L1, climate modelling uses earth observation satellites, and TV broadcasting is handled by communication satellites.<br><b>Correct option = (4)</b>, because NavIC provides regional navigation.","hi":"<b>सही उत्तर: विकल्प (4) – क्षेत्रीय नौवहन</b><br><b>NavIC (Navigation with Indian Constellation)</b> भारत की क्षेत्रीय उपग्रह नौवहन प्रणाली है, जो भारत तथा लगभग 1,500 किमी के आसपास के क्षेत्र में सटीक स्थिति, नौवहन एवं समय सेवाएँ देती है।<br><br><br><b><u>महत्वपूर्ण बिंदु:</u></b><br>• NavIC, जिसे पहले <b>IRNSS</b> कहा जाता था, ISRO द्वारा निर्मित है और इसमें भू-स्थैतिक तथा भू-तुल्यकालिक कक्षाओं के उपग्रहों का समूह है।<br>• यह सामान्य उपयोगकर्ताओं के लिए <b>मानक स्थिति सेवा</b> तथा रणनीतिक उपयोगकर्ताओं के लिए <b>प्रतिबंधित सेवा</b> प्रदान करता है।<br>• NavIC <b>वाहन ट्रैकिंग, आपदा प्रबंधन, मत्स्य पालन, सर्वेक्षण तथा 'खनन' एवं 'पोषण' अनुप्रयोगों</b> में सहायक है।<br>• सौर चित्रण आदित्य-L1 जैसे मिशन करते हैं, जलवायु मॉडलिंग में भू-प्रेक्षण उपग्रह प्रयुक्त होते हैं, तथा टीवी प्रसारण संचार उपग्रहों द्वारा होता है।<br><b>सही विकल्प = (4)</b>, क्योंकि NavIC क्षेत्रीय नौवहन प्रदान करता है।"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":43,"local_id":"50043","quid":"Q1000071323","section":"GK","topic":"Economics: National Income","question":{"en":"Which region showed a per capita income increase from 55% to 89% of the national average between 2001 and 2024? [SSC CGL 23/10/26 Shift 3]","hi":"2001 से 2024 के बीच किस क्षेत्र की प्रति व्यक्ति आय राष्ट्रीय औसत के 55% से बढ़कर 89% हो गई? [SSC CGL 23/10/26 Shift 3]"},"options":{"1":{"en":"Bihar","hi":"बिहार"},"2":{"en":"Uttar Pradesh","hi":"उत्तर प्रदेश"},"3":{"en":"Odisha","hi":"ओडिशा"},"4":{"en":"Chhattisgarh","hi":"छत्तीसगढ़"}},"answer":"3","solution":{"en":"<b>Correct Answer: Option (3) – Odisha</b><br>As per economic survey analysis, <b>Odisha's per capita income rose from about 55% to 89% of the national average</b> between 2001 and 2024, reflecting strong growth in mining, manufacturing and services.<br><br><br><b><u>Important Points:</u></b><br>• Odisha's growth has been driven by <b>mineral and metal industries, ports, and improved infrastructure</b>, along with higher capital expenditure by the state.<br>• <b>Bihar and Uttar Pradesh</b> continue to have per capita incomes well below the national average, and Chhattisgarh has improved but not at this scale.<br>• Per capita income is <b>NSDP per capita</b> at constant prices, and convergence across states is a key theme of the Economic Survey.<br>• Odisha's success in <b>disaster management and mining revenue</b> has supported its fiscal position.<br><b>Correct option = (3)</b>, because Odisha's per capita income rose from 55% to 89% of the national average.","hi":"<b>सही उत्तर: विकल्प (3) – ओडिशा</b><br>आर्थिक समीक्षा-विश्लेषण के अनुसार 2001 से 2024 के बीच <b>ओडिशा की प्रति व्यक्ति आय राष्ट्रीय औसत के लगभग 55% से बढ़कर 89%</b> हो गई, जो खनन, विनिर्माण तथा सेवाओं में प्रबल वृद्धि को दर्शाती है।<br><br><br><b><u>महत्वपूर्ण बिंदु:</u></b><br>• ओडिशा की वृद्धि <b>खनिज एवं धातु उद्योग, बंदरगाहों तथा बेहतर अवसंरचना</b> और राज्य के ऊँचे पूँजीगत व्यय से संचालित रही है।<br>• <b>बिहार तथा उत्तर प्रदेश</b> की प्रति व्यक्ति आय अब भी राष्ट्रीय औसत से काफी नीचे है, तथा छत्तीसगढ़ में सुधार हुआ है, परंतु इस स्तर तक नहीं।<br>• प्रति व्यक्ति आय <b>स्थिर मूल्यों पर NSDP प्रति व्यक्ति</b> है, और राज्यों के बीच अभिसरण आर्थिक समीक्षा का प्रमुख विषय है।<br>• <b>आपदा प्रबंधन तथा खनन राजस्व</b> में ओडिशा की सफलता ने उसकी राजकोषीय स्थिति को सहारा दिया है।<br><b>सही विकल्प = (3)</b>, क्योंकि ओडिशा की प्रति व्यक्ति आय राष्ट्रीय औसत के 55% से 89% हो गई।"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":44,"local_id":"50044","quid":"Q1000071324","section":"GK","topic":"Science and Technology: Science and Technology","question":{"en":"What is the focus of ISRO's Ladakh Human Analogue Mission? [SSC CGL 23/10/26 Shift 3]","hi":"ISRO के लद्दाख मानव अनुरूप मिशन (Ladakh Human Analogue Mission) का केंद्रबिंदु क्या है? [SSC CGL 23/10/26 Shift 3]"},"options":{"1":{"en":"Testing AI-based rovers on glaciers","hi":"हिमनदों पर AI आधारित रोवरों का परीक्षण"},"2":{"en":"Simulating lunar/Martian habitats for astronaut training","hi":"अंतरिक्ष यात्री प्रशिक्षण हेतु चंद्र/मंगल आवासों का अनुकरण"},"3":{"en":"Launching nanosatellites for LEO","hi":"LEO के लिए नैनोउपग्रह प्रक्षेपण"},"4":{"en":"Measuring Himalayan tectonic movements","hi":"हिमालयी विवर्तनिक गतियों का मापन"}},"answer":"2","solution":{"en":"<b>Correct Answer: Option (2) – Simulating lunar/Martian habitats for astronaut training</b><br>ISRO's <b>Ladakh Human Analogue Mission</b> uses the cold, dry, high-altitude terrain of Ladakh to <b>simulate lunar and Martian conditions</b> for testing habitats, spacesuits, rovers and astronaut training ahead of future human spaceflight missions.<br><br><br><b><u>Important Points:</u></b><br>• The mission is part of India's preparations for <b>Gaganyaan</b> and future long-duration missions, and involves ISRO with partners such as AAKA Space Studio and the University of Ladakh.<br>• Ladakh's <b>high altitude, low oxygen, extreme temperature and barren geology</b> closely resemble conditions on the Moon and Mars.<br>• Analogue missions help test <b>life support systems, communication delays, human performance and habitat design</b> at low cost.<br>• AI rover testing on glaciers and Himalayan tectonic measurement are separate research activities, not the focus of this mission.<br><b>Correct option = (2)</b>, because the mission simulates lunar/Martian habitats for astronaut training.","hi":"<b>सही उत्तर: विकल्प (2) – अंतरिक्ष यात्री प्रशिक्षण हेतु चंद्र/मंगल आवासों का अनुकरण</b><br>ISRO का <b>लद्दाख मानव अनुरूप मिशन</b> लद्दाख के ठंडे, शुष्क तथा अधिक ऊँचाई वाले भूभाग का उपयोग <b>चंद्र एवं मंगल स्थितियों का अनुकरण</b> करने के लिए करता है, जिससे भावी मानव अंतरिक्ष उड़ानों से पहले आवास, अंतरिक्ष-पोशाक, रोवर तथा अंतरिक्ष यात्रियों का प्रशिक्षण परखा जाता है।<br><br><br><b><u>महत्वपूर्ण बिंदु:</u></b><br>• यह मिशन भारत की <b>गगनयान</b> तथा भावी दीर्घकालिक मिशनों की तैयारी का भाग है, जिसमें ISRO के साथ AAKA स्पेस स्टूडियो तथा लद्दाख विश्वविद्यालय जैसे सहयोगी सम्मिलित हैं।<br>• लद्दाख की <b>अधिक ऊँचाई, कम ऑक्सीजन, अत्यधिक तापमान तथा वंजर भूविज्ञान</b> चंद्रमा एवं मंगल की स्थितियों से मिलता-जुलता है।<br>• अनुरूप मिशन कम लागत पर <b>जीवन-समर्थन प्रणाली, संचार विलंब, मानव प्रदर्शन तथा आवास डिज़ाइन</b> का परीक्षण करते हैं।<br>• हिमनदों पर AI रोवर परीक्षण तथा हिमालयी विवर्तनिक मापन पृथक अनुसंधान गतिविधियाँ हैं, इस मिशन का केंद्र नहीं।<br><b>सही विकल्प = (2)</b>, क्योंकि मिशन अंतरिक्ष यात्री प्रशिक्षण हेतु चंद्र/मंगल आवासों का अनुकरण करता है।"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":45,"local_id":"50045","quid":"Q1000071325","section":"GK","topic":"Environment: Miscellaneous","question":{"en":"Consider the following statements about the One Sun, One World, One Grid (OSOWOG) initiative:<br>1) It promotes cross-border solar energy sharing among nations.<br>2) It replaces energy storage with coal-based backup systems.<br>Which of the above <b>is/are correct</b>? [SSC CGL 23/10/26 Shift 3]","hi":"एक सूर्य, एक विश्व, एक ग्रिड (OSOWOG) पहल के बारे में निम्नलिखित कथनों पर विचार करें:<br>1) यह राष्ट्रों के बीच सीमा-पार सौर ऊर्जा साझाकरण को बढ़ावा देती है।<br>2) यह ऊर्जा भंडारण के स्थान पर कोयला आधारित बैकअप प्रणाली लाती है।<br>उपर्युक्त में से कौन <b>सही</b> है/हैं? [SSC CGL 23/10/26 Shift 3]"},"options":{"1":{"en":"Only 1","hi":"केवल 1"},"2":{"en":"Only 2","hi":"केवल 2"},"3":{"en":"1 and 2 Both","hi":"1 तथा 2 दोनों"},"4":{"en":"Neither 1 nor 2","hi":"न तो 1 न ही 2"}},"answer":"1","solution":{"en":"<b>Correct Answer: Option (1) – Only 1</b><br>The <b>One Sun, One World, One Grid (OSOWOG)</b> initiative promotes <b>cross-border sharing of solar energy</b> through interconnected grids, so statement 1 is correct; it does not replace energy storage with coal-based backup, so statement 2 is wrong.<br><br><br><b><u>Important Points:</u></b><br>• OSOWOG was proposed by India at the <b>first assembly of the International Solar Alliance (ISA) in 2018</b> and envisages a global interconnected solar grid.<br>• The plan has three phases – <b>interconnected grids in Asia, then Africa, then a global grid</b>.<br>• The initiative relies on <b>storage, transmission and demand management</b> rather than coal backup, and supports round-the-clock renewable power.<br>• The <b>International Solar Alliance</b> is a treaty-based organisation of over 100 solar-rich countries headquartered at Gurugram, India.<br><b>Correct option = (1)</b>, because only statement 1 about OSOWOG is correct.","hi":"<b>सही उत्तर: विकल्प (1) – केवल 1</b><br><b>एक सूर्य, एक विश्व, एक ग्रिड (OSOWOG)</b> पहल परस्पर जुड़े ग्रिडों के माध्यम से <b>सीमा-पार सौर ऊर्जा साझाकरण</b> को बढ़ावा देती है, इसलिए कथन 1 सही है; यह ऊर्जा भंडारण के स्थान पर कोयला आधारित बैकअप नहीं लाती, इसलिए कथन 2 गलत है।<br><br><br><b><u>महत्वपूर्ण बिंदु:</u></b><br>• OSOWOG भारत ने <b>2018 में अंतरराष्ट्रीय सौर गठबंधन (ISA) की प्रथम सभा</b> में प्रस्तावित किया और इसमें वैश्विक परस्पर जुड़ा सौर ग्रिड परिकल्पित है।<br>• इस योजना के तीन चरण हैं – <b>एशिया में परस्पर जुड़े ग्रिड, फिर अफ्रीका, फिर वैश्विक ग्रिड</b>।<br>• यह पहल कोयला बैकअप के स्थान पर <b>भंडारण, संचरण तथा माँग प्रबंधन</b> पर निर्भर है और चौबीसों घंटे अक्षय ऊर्जा को सहारा देती है।<br>• <b>अंतरराष्ट्रीय सौर गठबंधन</b> सौ से अधिक सौर-संपन्न देशों का संधि-आधारित संगठन है, जिसका मुख्यालय भारत के गुरुग्राम में है।<br><b>सही विकल्प = (1)</b>, क्योंकि OSOWOG के बारे में केवल कथन 1 सही है।"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":46,"local_id":"50046","quid":"Q1000071326","section":"GK","topic":"Polity: New Criminal Laws 2023","question":{"en":"The scrapping of the IPC, CrPC, and Evidence Act is seen as a step toward: [SSC CGL 23/10/26 Shift 3]","hi":"IPC, CrPC तथा साक्ष्य अधिनियम को समाप्त करना किस दिशा में एक कदम माना जाता है? [SSC CGL 23/10/26 Shift 3]"},"options":{"1":{"en":"Strengthening colonial rule","hi":"औपनिवेशिक शासन को सुदृढ़ करना"},"2":{"en":"Enhancing presidential powers","hi":"राष्ट्रपति की शक्तियाँ बढ़ाना"},"3":{"en":"Decolonization of laws","hi":"विधियों का विऔपनिवेशीकरण"},"4":{"en":"Centralizing the judiciary","hi":"न्यायपालिका का केंद्रीकरण"}},"answer":"3","solution":{"en":"<b>Correct Answer: Option (3) – Decolonization of laws</b><br>The replacement of the <b>Indian Penal Code, 1860</b>, the <b>Code of Criminal Procedure, 1973</b> and the <b>Indian Evidence Act, 1872</b> by the Bharatiya Nyaya Sanhita, Bharatiya Nagarik Suraksha Sanhita and Bharatiya Sakshya Adhiniyam, 2023 is seen as a step towards the <b>decolonisation of Indian laws</b>.<br><br><br><b><u>Important Points:</u></b><br>• The new laws came into force on <b>1 July 2024</b> and replace colonial-era statutes framed mainly to protect British rule.<br>• The stated aims include a shift from <b>punishment-centric to justice-centric</b> administration, use of technology and e-evidence, and time-bound investigation and trial.<br>• New offences include <b>organised crime, terrorism, mob lynching and hit-and-run</b> provisions, and sedition was replaced by a provision on acts endangering sovereignty.<br>• These changes neither strengthen colonial rule nor increase presidential powers or centralise the judiciary.<br><b>Correct option = (3)</b>, because scrapping the colonial laws is a step towards decolonisation of laws.","hi":"<b>सही उत्तर: विकल्प (3) – विधियों का विऔपनिवेशीकरण</b><br><b>भारतीय दंड संहिता, 1860</b>, <b>दंड प्रक्रिया संहिता, 1973</b> तथा <b>भारतीय साक्ष्य अधिनियम, 1872</b> के स्थान पर भारतीय न्याय संहिता, भारतीय नागरिक सुरक्षा संहिता तथा भारतीय साक्ष्य अधिनियम, 2023 लाना <b>भारतीय विधियों के विऔपनिवेशीकरण</b> की दिशा में कदम माना जाता है।<br><br><br><b><u>महत्वपूर्ण बिंदु:</u></b><br>• नई विधियाँ <b>1 जुलाई 2024</b> से प्रभावी हुईं और उन्होंने मुख्यतः ब्रिटिश शासन की रक्षा हेतु बनाए गए औपनिवेशिक अधिनियमों का स्थान लिया।<br>• घोषित उद्देश्यों में <b>दंड-केंद्रित से न्याय-केंद्रित</b> प्रशासन की ओर बदलाव, प्रौद्योगिकी एवं ई-साक्ष्य का उपयोग तथा समयबद्ध जाँच एवं विचारण सम्मिलित हैं।<br>• नए अपराधों में <b>संगठित अपराध, आतंकवाद, भीड़ द्वारा लिंचिंग तथा हिट-एंड-रन</b> के प्रावधान हैं, और राजद्रोह के स्थान पर संप्रभुता को संकट में डालने वाले कृत्यों का प्रावधान आया है।<br>• ये परिवर्तन न औपनिवेशिक शासन को सुदृढ़ करते हैं, न राष्ट्रपति की शक्तियाँ बढ़ाते हैं और न न्यायपालिका का केंद्रीकरण करते हैं।<br><b>सही विकल्प = (3)</b>, क्योंकि औपनिवेशिक विधियों को समाप्त करना विधियों के विऔपनिवेशीकरण की दिशा में कदम है।"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":47,"local_id":"50047","quid":"Q1000071327","section":"GK","topic":"Static GK: Music and Musical Instruments","question":{"en":"Sitar maestro Ravi Shankar contributed significantly to: [SSC CGL 23/10/26 Shift 3]","hi":"सितार वादक पंडित रविशंकर ने किस क्षेत्र में महत्वपूर्ण योगदान दिया? [SSC CGL 23/10/26 Shift 3]"},"options":{"1":{"en":"Popularizing Indian folk traditions in the West exclusively","hi":"पश्चिम में केवल भारतीय लोक परंपराओं को लोकप्रिय बनाना"},"2":{"en":"Introducing Indian classical music to Western audiences","hi":"पश्चिमी श्रोताओं का भारतीय शास्त्रीय संगीत से परिचय कराना"},"3":{"en":"Promoting only Bollywood-style music","hi":"केवल बॉलीवुड शैली के संगीत को बढ़ावा देना"},"4":{"en":"Declining cross-cultural collaborations","hi":"अंतर-सांस्कृतिक सहयोग घटाना"}},"answer":"2","solution":{"en":"<b>Correct Answer: Option (2) – Introducing Indian classical music to Western audiences</b><br>Sitar maestro <b>Pandit Ravi Shankar</b> is best known for <b>introducing Indian classical music to Western audiences</b>, through performances, collaborations with the Beatles and Yehudi Menuhin, and the Concert for Bangladesh.<br><br><br><b><u>Important Points:</u></b><br>• He won the <b>Bharat Ratna (1999)</b>, the Padma Vibhushan and three Grammy Awards, and was a Rajya Sabha member.<br>• His <b>fusion work and teaching</b> created a lasting interest in the sitar and Indian ragas in the West during the 1960s.<br>• His daughters <b>Anoushka Shankar</b> and <b>Norah Jones</b> are famous musicians in their own right.<br>• He was not associated exclusively with folk traditions or Bollywood music, and he expanded rather than reduced cross-cultural collaboration.<br><b>Correct option = (2)</b>, because Ravi Shankar introduced Indian classical music to Western audiences.","hi":"<b>सही उत्तर: विकल्प (2) – पश्चिमी श्रोताओं का भारतीय शास्त्रीय संगीत से परिचय कराना</b><br>सितार वादक <b>पंडित रविशंकर</b> <b>पश्चिमी श्रोताओं का भारतीय शास्त्रीय संगीत से परिचय कराने</b> के लिए सर्वाधिक जाने जाते हैं, जो उन्होंने प्रस्तुतियों, बीटल्स तथा यहूदी मेनुहिन के साथ सहयोग और कंसर्ट फॉर बांग्लादेश के माध्यम से किया।<br><br><br><b><u>महत्वपूर्ण बिंदु:</u></b><br>• उन्हें <b>भारत रत्न (1999)</b>, पद्म विभूषण तथा तीन ग्रैमी पुरस्कार मिले और वे राज्यसभा के सदस्य भी रहे।<br>• उनके <b>समन्वित (fusion) कार्य तथा शिक्षण</b> ने 1960 के दशक में पश्चिम में सितार तथा भारतीय रागों के प्रति स्थायी रुचि पैदा की।<br>• उनकी पुत्रियाँ <b>अनुष्का शंकर</b> तथा <b>नोरा जोन्स</b> स्वयं प्रसिद्ध संगीतकार हैं।<br>• वे न केवल लोक परंपराओं से या केवल बॉलीवुड संगीत से जुड़े थे, और उन्होंने अंतर-सांस्कृतिक सहयोग बढ़ाया, घटाया नहीं।<br><b>सही विकल्प = (2)</b>, क्योंकि रविशंकर ने पश्चिमी श्रोताओं का भारतीय शास्त्रीय संगीत से परिचय कराया।"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":48,"local_id":"50048","quid":"Q1000071328","section":"GK","topic":"Static GK: Music and Musical Instruments","question":{"en":"Which folk tradition is associated with the Manganiyar and Langa communities? [SSC CGL 23/10/26 Shift 3]","hi":"मंगणियार तथा लंगा समुदाय किस लोक परंपरा से संबंधित हैं? [SSC CGL 23/10/26 Shift 3]"},"options":{"1":{"en":"Baul Songs","hi":"बाउल गीत"},"2":{"en":"Rajasthani Folk","hi":"राजस्थानी लोक"},"3":{"en":"Bhojpuri Folk","hi":"भोजपुरी लोक"},"4":{"en":"Yakshagana","hi":"यक्षगान"}},"answer":"2","solution":{"en":"<b>Correct Answer: Option (2) – Rajasthani Folk</b><br>The <b>Manganiyar and Langa</b> are hereditary musician communities of <b>western Rajasthan</b>, whose folk songs and instrumental music are central to <b>Rajasthani folk</b> tradition.<br><br><br><b><u>Important Points:</u></b><br>• The Manganiyar sing <b>devotional and Sufi songs</b> for their patrons, and the Langa are famous for the <b>sindhi sarangi</b> and the kartal.<br>• Famous artists include <b>Allah Jilai Bai, Kheta Khan and the group Rajasthan Roots</b>, and the communities perform at the Jaisalmer Desert Festival.<br>• <b>Baul</b> songs belong to Bengal, <b>Bhojpuri</b> folk to Bihar and eastern Uttar Pradesh, and <b>Yakshagana</b> is a theatre form of Karnataka.<br>• Rajasthan's other folk forms include the <b>Ghoomar and Kalbeliya</b> dances and the Maand singing style.<br><b>Correct option = (2)</b>, because Manganiyar and Langa belong to Rajasthani folk tradition.","hi":"<b>सही उत्तर: विकल्प (2) – राजस्थानी लोक</b><br><b>मंगणियार तथा लंगा</b> <b>पश्चिमी राजस्थान</b> के वंशानुगत संगीतकार समुदाय हैं, जिनके लोकगीत तथा वाद्य संगीत <b>राजस्थानी लोक</b> परंपरा के केंद्र में हैं।<br><br><br><b><u>महत्वपूर्ण बिंदु:</u></b><br>• मंगणियार अपने जजमानों के लिए <b>भक्ति तथा सूफी गीत</b> गाते हैं, और लंगा <b>सिंधी सारंगी</b> तथा करताल के लिए प्रसिद्ध हैं।<br>• प्रसिद्ध कलाकारों में <b>अल्लाह जिलाई बाई, खेता खान तथा समूह राजस्थान रूट्स</b> सम्मिलित हैं, और ये समुदाय जैसलमेर मरु महोत्सव में प्रस्तुति देते हैं।<br>• <b>बाउल</b> गीत बंगाल के, <b>भोजपुरी</b> लोक बिहार तथा पूर्वी उत्तर प्रदेश के, और <b>यक्षगान</b> कर्नाटक का रंगमंच रूप है।<br>• राजस्थान के अन्य लोक रूपों में <b>घूमर तथा कालबेलिया</b> नृत्य एवं मांड गायन शैली सम्मिलित हैं।<br><b>सही विकल्प = (2)</b>, क्योंकि मंगणियार तथा लंगा राजस्थानी लोक परंपरा से हैं।"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":49,"local_id":"50049","quid":"Q1000071329","section":"GK","topic":"Polity: Salient Features of the Constitution","question":{"en":"The Constitution is described as: [SSC CGL 23/10/26 Shift 3]","hi":"संविधान का वर्णन किस प्रकार किया जाता है? [SSC CGL 23/10/26 Shift 3]"},"options":{"1":{"en":"A rigid, ceremonial text","hi":"एक अनम्य, औपचारिक दस्तावेज़"},"2":{"en":"A purely legal code without moral content","hi":"नैतिक तत्व से रहित एक पूर्णतः विधिक संहिता"},"3":{"en":"A moral compass and embodiment of people's aspirations","hi":"एक नैतिक दिशासूचक तथा लोगों की आकांक्षाओं का मूर्त रूप"},"4":{"en":"A relic of colonial rule","hi":"औपनिवेशिक शासन का अवशेष"}},"answer":"3","solution":{"en":"<b>Correct Answer: Option (3) – A moral compass and embodiment of people's aspirations</b><br>The Constitution is described as a <b>moral compass and the embodiment of the aspirations of the people</b>, because it lays down the values, rights and goals that the nation set for itself through the Preamble and the Directive Principles.<br><br><br><b><u>Important Points:</u></b><br>• The <b>Preamble</b> declares the ideals of justice, liberty, equality and fraternity, which guide constitutional interpretation.<br>• <b>Granville Austin</b> called the Indian Constitution a 'seamless web' and a 'cornerstone of a nation', and <b>Dr B.R. Ambedkar</b> described it as a means to social revolution.<br>• The Constitution is neither purely legal nor ceremonial; it combines <b>justiciable fundamental rights with non-justiciable Directive Principles</b>.<br>• It is a living document that has been amended over 100 times to meet changing needs.<br><b>Correct option = (3)</b>, because the Constitution is a moral compass and embodiment of people's aspirations.","hi":"<b>सही उत्तर: विकल्प (3) – एक नैतिक दिशासूचक तथा लोगों की आकांक्षाओं का मूर्त रूप</b><br>संविधान को <b>नैतिक दिशासूचक तथा लोगों की आकांक्षाओं का मूर्त रूप</b> कहा जाता है, क्योंकि वह प्रस्तावना तथा नीति निर्देशक तत्वों के माध्यम से वे मूल्य, अधिकार एवं लक्ष्य निर्धारित करता है जो राष्ट्र ने स्वयं के लिए तय किए।<br><br><br><b><u>महत्वपूर्ण बिंदु:</u></b><br>• <b>प्रस्तावना</b> न्याय, स्वतंत्रता, समता तथा बंधुत्व के आदर्श घोषित करती है, जो संवैधानिक व्याख्या का मार्गदर्शन करते हैं।<br>• <b>ग्रैनविल ऑस्टिन</b> ने भारतीय संविधान को 'अखंड वस्त्र' (seamless web) तथा 'राष्ट्र की आधारशिला' कहा, और <b>डॉ. बी. आर. आंबेडकर</b> ने इसे सामाजिक क्रांति का साधन बताया।<br>• संविधान न तो पूर्णतः विधिक है न औपचारिक; वह <b>न्याययोग्य मूल अधिकारों को अन्याययोग्य नीति निर्देशक तत्वों</b> से जोड़ता है।<br>• यह एक जीवंत दस्तावेज़ है, जिसे बदलती आवश्यकताओं की पूर्ति हेतु सौ से अधिक बार संशोधित किया गया है।<br><b>सही विकल्प = (3)</b>, क्योंकि संविधान नैतिक दिशासूचक तथा लोगों की आकांक्षाओं का मूर्त रूप है।"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":50,"local_id":"50050","quid":"Q1000071330","section":"GK","topic":"Polity: Supreme Court and High Court","question":{"en":"The Supreme Court's decision in Supriyo v. Union of India (2023) concerned: [SSC CGL 23/10/26 Shift 3]","hi":"सुप्रीयो बनाम भारत संघ (2023) में सर्वोच्च न्यायालय का निर्णय किससे संबंधित था? [SSC CGL 23/10/26 Shift 3]"},"options":{"1":{"en":"Data protection and privacy","hi":"आँकड़ा संरक्षण तथा निजता"},"2":{"en":"Same-sex marriage","hi":"समलैंगिक विवाह"},"3":{"en":"Electoral funding","hi":"चुनावी चंदा"},"4":{"en":"Article 370","hi":"अनुच्छेद 370"}},"answer":"2","solution":{"en":"<b>Correct Answer: Option (2) – Same-sex marriage</b><br>In <b>Supriyo v. Union of India (2023)</b> the Supreme Court declined to recognise <b>same-sex marriage</b>, holding that only Parliament can create a legal right to marry for same-sex couples, while affirming equal rights and dignity for LGBTQIA+ persons.<br><br><br><b><u>Important Points:</u></b><br>• A five-judge Constitution Bench headed by <b>Chief Justice D.Y. Chandrachud</b> delivered the judgment in October 2023.<br>• The Court upheld the validity of the <b>Special Marriage Act</b>'s opposite-sex requirement and left the issue to the legislature.<br>• <b>K.S. Puttaswamy (2017)</b> concerned privacy and data protection, and <b>In re: Article 370 (2023)</b> upheld the abrogation of Article 370.<br>• Electoral funding was dealt with in the <b>Electoral Bond case (2024)</b>, which struck down the electoral bond scheme.<br><b>Correct option = (2)</b>, because Supriyo v. Union of India concerned same-sex marriage.","hi":"<b>सही उत्तर: विकल्प (2) – समलैंगिक विवाह</b><br><b>सुप्रीयो बनाम भारत संघ (2023)</b> में सर्वोच्च न्यायालय ने <b>समलैंगिक विवाह</b> को मान्यता देने से इनकार किया और अभिनिर्धारित किया कि समलैंगिक जोड़ों को विवाह का विधिक अधिकार केवल संसद दे सकती है, जबकि LGBTQIA+ व्यक्तियों के समान अधिकार तथा गरिमा की पुष्टि की।<br><br><br><b><u>महत्वपूर्ण बिंदु:</u></b><br>• <b>मुख्य न्यायाधीश डी. वाई. चंद्रचूड़</b> की अध्यक्षता वाली पाँच-न्यायाधीशों की संविधान पीठ ने अक्टूबर 2023 में यह निर्णय दिया।<br>• न्यायालय ने <b>विशेष विवाह अधिनियम</b> की विपरीत-लिंग अनिवार्यता की वैधता बनाए रखी और यह मुद्दा विधानमंडल पर छोड़ा।<br>• <b>के. एस. पुट्टास्वामी (2017)</b> निजता तथा आँकड़ा संरक्षण से संबंधित था, और <b>अनुच्छेद 370 मामले (2023)</b> में अनुच्छेद 370 हटाने को वैध ठहराया गया।<br>• चुनावी चंदे का मामला <b>इलेक्टोरल बॉन्ड मामले (2024)</b> में था, जिसमें इलेक्टोरल बॉन्ड योजना रद्द की गई।<br><b>सही विकल्प = (2)</b>, क्योंकि सुप्रीयो बनाम भारत संघ समलैंगिक विवाह से संबंधित था।"},"marks":{"correct":2,"negative":0.5},"has_image":false}]},"MATH":{"seconds":900,"questions":[{"no":51,"local_id":"50051","quid":"Q1000071331","section":"MATH","topic":"Compound Interest (CI)","question":{"en":"A remote district had a population of 2,50,000 which grew to 2,81,382 over a span of few years. If the average annual population growth rate was 4%, approximately how many years did it take to reach the new population? [SSC CGL 23/10/26 Shift 3]","hi":"एक दूरस्थ जिले की जनसंख्या 2,50,000 थी जो कुछ वर्षों में बढ़कर 2,81,382 हो गई। यदि औसत वार्षिक जनसंख्या वृद्धि दर 4% थी, तो नई जनसंख्या तक पहुँचने में लगभग कितने वर्ष लगे? [SSC CGL 23/10/26 Shift 3]"},"options":{"1":{"en":"2 years","hi":"2 वर्ष"},"2":{"en":"3 years","hi":"3 वर्ष"},"3":{"en":"4 years","hi":"4 वर्ष"},"4":{"en":"5 years","hi":"5 वर्ष"}},"answer":"2","solution":{"en":"\\(250000(1.04)^n = 281382 \\Rightarrow (1.04)^n = 1.1255\\)<br>\\((1.04)^2 = 1.0816\\) and \\((1.04)^3 = 1.1249 \\approx 1.1255\\)<br>So \\(n \\approx \\boxed{3}\\) years<br><br><b>Hence, the correct answer is option (2): 3 years.</b>","hi":"\\(250000(1.04)^n = 281382 \\Rightarrow (1.04)^n = 1.1255\\)<br>\\((1.04)^2 = 1.0816\\) और \\((1.04)^3 = 1.1249 \\approx 1.1255\\)<br>अतः \\(n \\approx \\boxed{3}\\) वर्ष<br><br><b>अतः सही उत्तर विकल्प (2): 3 वर्ष है।</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":52,"local_id":"50052","quid":"Q1000071332","section":"MATH","topic":"Compound Interest (CI)","question":{"en":"A retailer borrows ₹2,00,000 from a bank at a 10% compound interest rate per annum for 2 years to set up a delivery system. After 2 years, the total amount paid includes a 15% service tax on the compound interest. He then distributes this total cost equally across 1000 deliveries. Estimate the average delivery cost (in ₹), rounded to the nearest rupee? [SSC CGL 23/10/26 Shift 3]","hi":"एक खुदरा विक्रेता डिलीवरी प्रणाली स्थापित करने के लिए बैंक से 2 वर्षों के लिए 10% प्रति वर्ष चक्रवृद्धि ब्याज दर पर ₹2,00,000 उधार लेता है। 2 वर्षों के बाद चुकाई गई कुल राशि में चक्रवृद्धि ब्याज पर 15% सेवा कर भी शामिल है। फिर वह इस कुल लागत को 1000 डिलीवरी में समान रूप से बाँटता है। प्रति डिलीवरी औसत लागत (₹ में) निकटतम रुपये तक ज्ञात कीजिए। [SSC CGL 23/10/26 Shift 3]"},"options":{"1":{"en":"₹250"},"2":{"en":"₹254"},"3":{"en":"₹248"},"4":{"en":"₹262"}},"answer":"3","solution":{"en":"Amount = \\(200000\\left(1 + \\frac{10}{100}\\right)^2 = 200000 \\times 1.21 = 2{,}42{,}000\\)<br>Compound interest = \\(2{,}42{,}000 - 2{,}00{,}000 = 42{,}000\\)<br>Service tax = \\(15\\%\\) of \\(42{,}000 = 6{,}300\\)<br>Total cost = \\(2{,}42{,}000 + 6{,}300 = 2{,}48{,}300\\)<br>Cost per delivery = ₹\\(\\frac{248300}{1000} = 248.3 \\approx \\boxed{248}\\)<br><br><b>Hence, the correct answer is option (3): ₹248.</b>","hi":"राशि = \\(200000\\left(1 + \\frac{10}{100}\\right)^2 = 200000 \\times 1.21 = 2{,}42{,}000\\)<br>चक्रवृद्धि ब्याज = \\(2{,}42{,}000 - 2{,}00{,}000 = 42{,}000\\)<br>सेवा कर = \\(42{,}000\\) का \\(15\\% = 6{,}300\\)<br>कुल लागत = \\(2{,}42{,}000 + 6{,}300 = 2{,}48{,}300\\)<br>प्रति डिलीवरी लागत = ₹\\(\\frac{248300}{1000} = 248.3 \\approx \\boxed{248}\\)<br><br><b>अतः सही उत्तर विकल्प (3): ₹248 है।</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":53,"local_id":"50053","quid":"Q1000071333","section":"MATH","topic":"Data Interpretation (DI)","question":{"en":"Using the information in the pie chart, answer the following question.<br><img src=\"https://res.cloudinary.com/mc6kb3uo/image/upload/ssc_mock/CGL-23-OCT-2026-SHIFT-3/q53.jpg\" style=\"max-width:100%;height:auto\"><br>An investor initially allocated ₹12,00,000 based on the sector-wise percentages shown. In the next year, he decided to increase his investment in Online Tutors by 20% and decrease investment in AR/VR Learning by 10%, while keeping all other sector allocations the same. What is the new amount invested in Online Tutors?<br><img src=\"https://res.cloudinary.com/mc6kb3uo/image/upload/ssc_mock/CGL-23-OCT-2026-SHIFT-3/q53.jpg\" style=\"max-width:100%;height:auto\"> [SSC CGL 23/10/26 Shift 3]","hi":"पाई चार्ट में दी गई जानकारी के आधार पर निम्नलिखित प्रश्न का उत्तर दीजिए।<br><img src=\"https://res.cloudinary.com/mc6kb3uo/image/upload/ssc_mock/CGL-23-OCT-2026-SHIFT-3/q53.jpg\" style=\"max-width:100%;height:auto\"><br>एक निवेशक ने दर्शाए गए क्षेत्रवार प्रतिशत के आधार पर शुरू में ₹12,00,000 का आवंटन किया। अगले वर्ष उसने Online Tutors में निवेश 20% बढ़ाने और AR/VR Learning में निवेश 10% घटाने का निर्णय लिया, जबकि अन्य सभी क्षेत्रों का आवंटन समान रखा। Online Tutors में निवेश की नई राशि क्या है?<br><img src=\"https://res.cloudinary.com/mc6kb3uo/image/upload/ssc_mock/CGL-23-OCT-2026-SHIFT-3/q53.jpg\" style=\"max-width:100%;height:auto\"> [SSC CGL 23/10/26 Shift 3]"},"options":{"1":{"en":"₹2,00,000"},"2":{"en":"₹2,16,000"},"3":{"en":"₹2,10,000"},"4":{"en":"₹2,25,000"}},"answer":"2","solution":{"en":"From the pie chart: EdTech 40%, AR/VR Learning 25%, Online Tutors 15%, Exam Portals 10%, Skill Platforms 10%<br>Initial Online Tutors investment = \\(15\\%\\) of 12,00,000 = ₹1,80,000<br>Increase of \\(20\\%\\): ₹\\(1{,}80{,}000 \\times 1.20 = \\boxed{2{,}16{,}000}\\)<br><br><b>Hence, the correct answer is option (2): ₹2,16,000.</b>","hi":"पाई चार्ट से: EdTech 40%, AR/VR Learning 25%, Online Tutors 15%, Exam Portals 10%, Skill Platforms 10%<br>Online Tutors में प्रारंभिक निवेश = 12,00,000 का \\(15\\%\\) = ₹1,80,000<br>\\(20\\%\\) की वृद्धि: ₹\\(1{,}80{,}000 \\times 1.20 = \\boxed{2{,}16{,}000}\\)<br><br><b>अतः सही उत्तर विकल्प (2): ₹2,16,000 है।</b>"},"marks":{"correct":2,"negative":0.5},"has_image":true,"images":{"question":["https://res.cloudinary.com/mc6kb3uo/image/upload/ssc_mock/CGL-23-OCT-2026-SHIFT-3/q53.jpg"]}},{"no":54,"local_id":"50054","quid":"Q1000071334","section":"MATH","topic":"Coordinate Geometry","question":{"en":"A triangle ABC has its vertices at A(1, 1), B(5, 1), and C(3, 1+2√3). If a point P within the triangle is such that its perpendicular distance to AB, BC, and CA are all equal, which of the following is true about point P? [SSC CGL 23/10/26 Shift 3]","hi":"त्रिभुज ABC के शीर्ष A(1, 1), B(5, 1) और C(3, 1+2√3) हैं। यदि त्रिभुज के भीतर एक बिंदु P ऐसा है कि AB, BC और CA से उसकी लंब दूरियाँ बराबर हैं, तो बिंदु P के बारे में निम्नलिखित में से क्या सत्य है? [SSC CGL 23/10/26 Shift 3]"},"options":{"1":{"en":"P is the centroid of triangle ABC.","hi":"P, त्रिभुज ABC का केंद्रक है।"},"2":{"en":"P is the orthocenter of triangle ABC, and it lies on the line x=3.","hi":"P, त्रिभुज ABC का लंबकेंद्र है और यह रेखा x=3 पर स्थित है।"},"3":{"en":"P is the circumcenter of triangle ABC, and it is located outside the triangle.","hi":"P, त्रिभुज ABC का परिकेंद्र है और यह त्रिभुज के बाहर स्थित है।"},"4":{"en":"P is the incentre of triangle ABC, and triangle ABC is equilateral.","hi":"P, त्रिभुज ABC का अंतःकेंद्र है और त्रिभुज ABC समबाहु है।"}},"answer":"4","solution":{"en":"\\(AB = 4\\)<br>\\(AC = \\sqrt{(3-1)^2 + (2\\sqrt{3})^2} = \\sqrt{4 + 12} = 4\\)<br>\\(BC = \\sqrt{(3-5)^2 + (2\\sqrt{3})^2} = \\sqrt{4 + 12} = 4\\)<br>All three sides are equal, so ΔABC is equilateral, and the point equidistant from all three sides is the incentre.<br>Hence \\(\\boxed{P \\text{ is the incentre of } \\triangle ABC \\text{ and } \\triangle ABC \\text{ is equilateral}}\\)<br><br><b>Hence, the correct answer is option (4): P is the incentre of triangle ABC, and triangle ABC is equilateral.</b>","hi":"\\(AB = 4\\)<br>\\(AC = \\sqrt{(3-1)^2 + (2\\sqrt{3})^2} = \\sqrt{4 + 12} = 4\\)<br>\\(BC = \\sqrt{(3-5)^2 + (2\\sqrt{3})^2} = \\sqrt{4 + 12} = 4\\)<br>तीनों भुजाएँ बराबर हैं, अतः ΔABC समबाहु है, और तीनों भुजाओं से समान दूरी पर स्थित बिंदु अंतःकेंद्र होता है।<br>अतः \\(\\boxed{P, \\triangle ABC \\text{ का अंतःकेंद्र है और } \\triangle ABC \\text{ समबाहु है}}\\)<br><br><b>अतः सही उत्तर विकल्प (4): P, त्रिभुज ABC का अंतःकेंद्र है और त्रिभुज ABC समबाहु है। है।</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":55,"local_id":"50055","quid":"Q1000071335","section":"MATH","topic":"Time Speed and Distance","question":{"en":"A crane operator moves along two base edges of a cubical container (volume = 1000 m³), then ascends vertically to the top. If speeds along the base are in the ratio 2:1 and it takes 6 seconds to move along the slower side, and the crane ascends vertically at 0.5 m/s, what is the total distance and time? [SSC CGL 23/10/26 Shift 3]","hi":"एक क्रेन ऑपरेटर एक घनाकार कंटेनर (आयतन = 1000 m³) के दो आधार किनारों के अनुदिश चलता है, फिर ऊर्ध्वाधर रूप से ऊपर तक जाता है। यदि आधार पर चालें 2:1 के अनुपात में हैं और धीमी भुजा पर चलने में 6 सेकंड लगते हैं, तथा क्रेन 0.5 m/s की चाल से ऊर्ध्वाधर ऊपर जाता है, तो कुल दूरी और समय क्या है? [SSC CGL 23/10/26 Shift 3]"},"options":{"1":{"en":"30 m; 28 s"},"2":{"en":"30 m; 29 s"},"3":{"en":"32 m; 30 s"},"4":{"en":"34 m; 31 s"}},"answer":"2","solution":{"en":"Volume \\(= 1000\\) m³, so each edge \\(= 10\\) m.<br>Slower speed: \\(\\frac{10}{6}\\) m/s; faster speed is twice that, so the same edge takes 3 s.<br>Vertical ascent: 10 m at 0.5 m/s = 20 s<br>Total distance = \\(10 + 10 + 10 = 30\\) m<br>Total time = \\(6 + 3 + 20 = \\boxed{29\\ \\text{s}}\\) (distance 30 m)<br><br><b>Hence, the correct answer is option (2): 30 m; 29 s.</b>","hi":"आयतन \\(= 1000\\) m³, अतः प्रत्येक कोर \\(= 10\\) m<br>धीमी चाल: \\(\\frac{10}{6}\\) m/s; तेज़ चाल उसकी दोगुनी है, अतः वही कोर 3 s में तय होगा।<br>ऊर्ध्वाधर चढ़ाई: 10 m, 0.5 m/s पर = 20 s<br>कुल दूरी = \\(10 + 10 + 10 = 30\\) m<br>कुल समय = \\(6 + 3 + 20 = \\boxed{29\\ \\text{s}}\\) (दूरी 30 m)<br><br><b>अतः सही उत्तर विकल्प (2): 30 m; 29 s है।</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":56,"local_id":"50056","quid":"Q1000071336","section":"MATH","topic":"Time and Work","question":{"en":"A group of workers working individually can complete the project in 60 days. On the first day, only one worker starts the work. Each subsequent day, one more worker joins the team. That is 1 worker on day 1, 2 workers on day 2, 3 workers on day 3, and so on. Assuming every worker contributes equally and continuously from the day they join, estimate in how many days will the project be completed? [SSC CGL 23/10/26 Shift 3]","hi":"अलग-अलग कार्य करने पर एक श्रमिक समूह परियोजना को 60 दिनों में पूरा कर सकता है। पहले दिन केवल एक श्रमिक कार्य शुरू करता है। प्रत्येक अगले दिन एक और श्रमिक टीम में शामिल होता है, अर्थात् पहले दिन 1, दूसरे दिन 2, तीसरे दिन 3 श्रमिक और इसी प्रकार। यदि प्रत्येक श्रमिक शामिल होने के दिन से समान और निरंतर योगदान देता है, तो परियोजना लगभग कितने दिनों में पूरी होगी? [SSC CGL 23/10/26 Shift 3]"},"options":{"1":{"en":"10.5"},"2":{"en":"10"},"3":{"en":"9.5"},"4":{"en":"9"}},"answer":"1","solution":{"en":"One worker does \\(\\frac{1}{60}\\) of the work per day.<br>Work done in \\(n\\) days = \\(\\frac{1 + 2 + \\cdots + n}{60} = \\frac{n(n+1)}{120}\\)<br>\\(\\frac{n(n+1)}{120} = 1 \\Rightarrow n(n+1) = 120\\)<br>\\(n \\approx 10.46\\), so the work is completed in about \\(\\boxed{10.5}\\) days<br><br><b>Hence, the correct answer is option (1): 10.5.</b>","hi":"एक श्रमिक प्रतिदिन कार्य का \\(\\frac{1}{60}\\) करता है।<br>\\(n\\) दिनों में किया गया कार्य = \\(\\frac{1 + 2 + \\cdots + n}{60} = \\frac{n(n+1)}{120}\\)<br>\\(\\frac{n(n+1)}{120} = 1 \\Rightarrow n(n+1) = 120\\)<br>\\(n \\approx 10.46\\), अतः कार्य लगभग \\(\\boxed{10.5}\\) दिनों में पूरा होगा।<br><br><b>अतः सही उत्तर विकल्प (1): 10.5 है।</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":57,"local_id":"50057","quid":"Q1000071337","section":"MATH","topic":"Mensuration (3D)","question":{"en":"If the base edge of a regular square pyramid is 8 cm and its height is 3 cm, what is the slant height? [SSC CGL 23/10/26 Shift 3]","hi":"यदि एक समकोणीय वर्गीय पिरामिड की आधार भुजा 8 cm और ऊँचाई 3 cm है, तो तिर्यक ऊँचाई क्या है? [SSC CGL 23/10/26 Shift 3]"},"options":{"1":{"en":"5 cm"},"2":{"en":"√73 cm"},"3":{"en":"√41 cm"},"4":{"en":"√7 cm"}},"answer":"1","solution":{"en":"<svg width=\"252\" height=\"127\" viewBox=\"0 0 252 127\" fill=\"none\" stroke=\"#000\" stroke-width=\"1.5\" font-size=\"12\"><path d=\"M26 101L126 26L226 101ZM133 101L133 94L126 94\"/><path stroke-dasharray=\"4 3\" d=\"M126 26L126 101\"/><circle cx=\"126\" cy=\"101\" r=\"2\" fill=\"#000\"/><g fill=\"#000\" stroke=\"#fff\" stroke-width=\"3\" paint-order=\"stroke\" stroke-linejoin=\"round\" text-anchor=\"middle\"><text x=\"121\" y=\"68\" text-anchor=\"end\" font-size=\"11\">h = 3 cm</text><text x=\"184\" y=\"57\">l</text><text x=\"176\" y=\"115\" font-size=\"11\">a/2 = 4 cm</text></g></svg><br>Half of the base edge = \\(\\frac{8}{2} = 4\\) cm<br>Slant height \\(l = \\sqrt{h^2 + \\left(\\frac{a}{2}\\right)^2} = \\sqrt{3^2 + 4^2}\\)<br>\\(= \\sqrt{25} = \\boxed{5}\\) cm<br><br><b>Hence, the correct answer is option (1): 5 cm.</b>","hi":"<svg width=\"252\" height=\"127\" viewBox=\"0 0 252 127\" fill=\"none\" stroke=\"#000\" stroke-width=\"1.5\" font-size=\"12\"><path d=\"M26 101L126 26L226 101ZM133 101L133 94L126 94\"/><path stroke-dasharray=\"4 3\" d=\"M126 26L126 101\"/><circle cx=\"126\" cy=\"101\" r=\"2\" fill=\"#000\"/><g fill=\"#000\" stroke=\"#fff\" stroke-width=\"3\" paint-order=\"stroke\" stroke-linejoin=\"round\" text-anchor=\"middle\"><text x=\"121\" y=\"68\" text-anchor=\"end\" font-size=\"11\">h = 3 cm</text><text x=\"184\" y=\"57\">l</text><text x=\"176\" y=\"115\" font-size=\"11\">a/2 = 4 cm</text></g></svg><br>आधार भुजा का आधा = \\(\\frac{8}{2} = 4\\) cm<br>तिर्यक ऊँचाई \\(l = \\sqrt{h^2 + \\left(\\frac{a}{2}\\right)^2} = \\sqrt{3^2 + 4^2}\\)<br>\\(= \\sqrt{25} = \\boxed{5}\\) cm<br><br><b>अतः सही उत्तर विकल्प (1): 5 cm है।</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":58,"local_id":"50058","quid":"Q1000071338","section":"MATH","topic":"Mensuration (3D)","question":{"en":"A regular right pyramid has an equilateral triangle with 12 cm sides as its base. If each lateral edge is 13 cm long, what's the pyramid's volume? [SSC CGL 23/10/26 Shift 3]","hi":"एक समकोणीय पिरामिड का आधार 12 cm भुजा वाला समबाहु त्रिभुज है। यदि प्रत्येक पार्श्व कोर 13 cm लंबा है, तो पिरामिड का आयतन क्या है? [SSC CGL 23/10/26 Shift 3]"},"options":{"1":{"en":"\\(132\\sqrt{3}\\ \\text{cm}^3\\)"},"2":{"en":"\\(132\\ \\text{cm}^3\\)"},"3":{"en":"\\(102\\sqrt{13}\\ \\text{cm}^3\\)"},"4":{"en":"\\(15\\sqrt{3}\\ \\text{cm}^3\\)"}},"answer":"1","solution":{"en":"<svg width=\"193\" height=\"222\" viewBox=\"0 0 193 222\" fill=\"none\" stroke=\"#000\" stroke-width=\"1.5\" font-size=\"12\"><path d=\"M54 196L167 135M54 196L82 26M167 135L82 26M26 135L54 196M26 135L82 26\"/><path stroke-dasharray=\"4 3\" d=\"M167 135L26 135M82 26L82 155\"/><circle cx=\"82\" cy=\"155\" r=\"2\" fill=\"#000\"/><g fill=\"#000\" stroke=\"#fff\" stroke-width=\"3\" paint-order=\"stroke\" stroke-linejoin=\"round\" text-anchor=\"middle\"><text x=\"78\" y=\"110\" text-anchor=\"end\" font-size=\"11\">h</text><text x=\"131\" y=\"84\" text-anchor=\"start\" font-size=\"11\">13 cm</text><text x=\"120\" y=\"187\">12 cm</text></g></svg><br>Circumradius of the equilateral base = \\(\\frac{a}{\\sqrt{3}} = \\frac{12}{\\sqrt{3}} = 4\\sqrt{3}\\) cm<br>Height \\(h = \\sqrt{13^2 - (4\\sqrt{3})^2} = \\sqrt{169 - 48} = 11\\) cm<br>Base area = \\(\\frac{\\sqrt{3}}{4} \\times 144 = 36\\sqrt{3}\\) cm²<br>Volume = \\(\\frac{1}{3} \\times 36\\sqrt{3} \\times 11 = \\boxed{132\\sqrt{3}}\\) cm³<br><br><b>Hence, the correct answer is option (1): \\(132\\sqrt{3}\\ \\text{cm}^3\\).</b>","hi":"<svg width=\"193\" height=\"222\" viewBox=\"0 0 193 222\" fill=\"none\" stroke=\"#000\" stroke-width=\"1.5\" font-size=\"12\"><path d=\"M54 196L167 135M54 196L82 26M167 135L82 26M26 135L54 196M26 135L82 26\"/><path stroke-dasharray=\"4 3\" d=\"M167 135L26 135M82 26L82 155\"/><circle cx=\"82\" cy=\"155\" r=\"2\" fill=\"#000\"/><g fill=\"#000\" stroke=\"#fff\" stroke-width=\"3\" paint-order=\"stroke\" stroke-linejoin=\"round\" text-anchor=\"middle\"><text x=\"78\" y=\"110\" text-anchor=\"end\" font-size=\"11\">h</text><text x=\"131\" y=\"84\" text-anchor=\"start\" font-size=\"11\">13 cm</text><text x=\"120\" y=\"187\">12 cm</text></g></svg><br>समबाहु आधार की परित्रिज्या = \\(\\frac{a}{\\sqrt{3}} = \\frac{12}{\\sqrt{3}} = 4\\sqrt{3}\\) cm<br>ऊँचाई \\(h = \\sqrt{13^2 - (4\\sqrt{3})^2} = \\sqrt{169 - 48} = 11\\) cm<br>आधार का क्षेत्रफल = \\(\\frac{\\sqrt{3}}{4} \\times 144 = 36\\sqrt{3}\\) cm²<br>आयतन = \\(\\frac{1}{3} \\times 36\\sqrt{3} \\times 11 = \\boxed{132\\sqrt{3}}\\) cm³<br><br><b>अतः सही उत्तर विकल्प (1): \\(132\\sqrt{3}\\ \\text{cm}^3\\) है।</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":59,"local_id":"50059","quid":"Q1000071339","section":"MATH","topic":"Trigonometry","question":{"en":"If tanA + cotA = 2, then tan²A + cot²A = ? [SSC CGL 23/10/26 Shift 3]","hi":"यदि tanA + cotA = 2 है, तो tan²A + cot²A = ? [SSC CGL 23/10/26 Shift 3]"},"options":{"1":{"en":"4"},"2":{"en":"5"},"3":{"en":"6"},"4":{"en":"2"}},"answer":"4","solution":{"en":"\\(\\tan^2A + \\cot^2A = (\\tan A + \\cot A)^2 - 2\\tan A\\cot A\\)<br>Since \\(\\tan A \\cdot \\cot A = 1\\):<br>\\(= 2^2 - 2 = \\boxed{2}\\)<br><br><b>Hence, the correct answer is option (4): 2.</b>","hi":"\\(\\tan^2A + \\cot^2A = (\\tan A + \\cot A)^2 - 2\\tan A\\cot A\\)<br>चूँकि \\(\\tan A \\cdot \\cot A = 1\\):<br>\\(= 2^2 - 2 = \\boxed{2}\\)<br><br><b>अतः सही उत्तर विकल्प (4): 2 है।</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":60,"local_id":"50060","quid":"Q1000071340","section":"MATH","topic":"Trigonometry","question":{"en":"What is the value of \\(\\sin^2 10^\\circ + \\sin^2 20^\\circ + \\sin^2 30^\\circ + \\cdots + \\sin^2 80^\\circ\\)? [SSC CGL 23/10/26 Shift 3]","hi":"\\(\\sin^2 10^\\circ + \\sin^2 20^\\circ + \\sin^2 30^\\circ + \\cdots + \\sin^2 80^\\circ\\) का मान क्या है? [SSC CGL 23/10/26 Shift 3]"},"options":{"1":{"en":"1"},"2":{"en":"2"},"3":{"en":"3"},"4":{"en":"4"}},"answer":"4","solution":{"en":"Pair the terms as \\((10^\\circ, 80^\\circ), (20^\\circ, 70^\\circ), (30^\\circ, 60^\\circ), (40^\\circ, 50^\\circ)\\).<br>\\(\\sin^2\\theta + \\sin^2(90^\\circ - \\theta) = \\sin^2\\theta + \\cos^2\\theta = 1\\)<br>There are 4 such pairs, so the sum is \\(4 \\times 1 = \\boxed{4}\\)<br><br><b>Hence, the correct answer is option (4): 4.</b>","hi":"पदों को \\((10^\\circ, 80^\\circ), (20^\\circ, 70^\\circ), (30^\\circ, 60^\\circ), (40^\\circ, 50^\\circ)\\) के जोड़ों में बाँटिए।<br>\\(\\sin^2\\theta + \\sin^2(90^\\circ - \\theta) = \\sin^2\\theta + \\cos^2\\theta = 1\\)<br>ऐसे 4 जोड़े हैं, अतः योग \\(4 \\times 1 = \\boxed{4}\\) है।<br><br><b>अतः सही उत्तर विकल्प (4): 4 है।</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":61,"local_id":"50061","quid":"Q1000071341","section":"MATH","topic":"Data Interpretation (DI)","question":{"en":"The given bar graph illustrates Website Traffic Sources (Desktop vs. Mobile). Answer the following question based on this bar graph.<br><img src=\"https://res.cloudinary.com/mc6kb3uo/image/upload/ssc_mock/CGL-23-OCT-2026-SHIFT-3/q61.jpg\" style=\"max-width:100%;height:auto\"><br>The website's total visitors from all sources (desktop + mobile) is 1,230,000. Given the data in the bar graph, calculate the exact number of visitors from Organic Search (both desktop and mobile). If 5% of the Organic Search visitors bounce off the website immediately, how many visitors remain engaged? Round your answer to the nearest whole number.<br><img src=\"https://res.cloudinary.com/mc6kb3uo/image/upload/ssc_mock/CGL-23-OCT-2026-SHIFT-3/q61.jpg\" style=\"max-width:100%;height:auto\"> [SSC CGL 23/10/26 Shift 3]","hi":"दिया गया स्तंभ ग्राफ वेबसाइट ट्रैफिक स्रोत (डेस्कटॉप बनाम मोबाइल) दर्शाता है। इस स्तंभ ग्राफ के आधार पर निम्नलिखित प्रश्न का उत्तर दीजिए।<br><img src=\"https://res.cloudinary.com/mc6kb3uo/image/upload/ssc_mock/CGL-23-OCT-2026-SHIFT-3/q61.jpg\" style=\"max-width:100%;height:auto\"><br>वेबसाइट के सभी स्रोतों (डेस्कटॉप + मोबाइल) से कुल आगंतुक 1,230,000 हैं। स्तंभ ग्राफ के आंकड़ों के अनुसार Organic Search (डेस्कटॉप और मोबाइल दोनों) से आगंतुकों की सटीक संख्या ज्ञात कीजिए। यदि Organic Search के 5% आगंतुक वेबसाइट से तुरंत बाहर चले जाते हैं, तो कितने आगंतुक जुड़े रहते हैं? उत्तर को निकटतम पूर्ण संख्या में लिखिए।<br><img src=\"https://res.cloudinary.com/mc6kb3uo/image/upload/ssc_mock/CGL-23-OCT-2026-SHIFT-3/q61.jpg\" style=\"max-width:100%;height:auto\"> [SSC CGL 23/10/26 Shift 3]"},"options":{"1":{"en":"558000"},"2":{"en":"561000"},"3":{"en":"570,000"},"4":{"en":"579000"}},"answer":"3","solution":{"en":"From the bar graph (in thousands): Organic Search → desktop 250, mobile 350; Social Media → 75, 175; Paid Ads → 120, 85; Direct Traffic → 100, 65; Referral → 50, 75<br>Organic Search total = \\(250 + 350 = 600\\) thousand = 6,00,000 visitors<br>Bounce = \\(5\\%\\) of 6,00,000 = 30,000<br>Engaged visitors = \\(6{,}00{,}000 - 30{,}000 = \\boxed{570{,}000}\\)<br><br><b>Hence, the correct answer is option (3): 570,000.</b>","hi":"स्तंभ ग्राफ से (हज़ार में): Organic Search → डेस्कटॉप 250, मोबाइल 350; Social Media → 75, 175; Paid Ads → 120, 85; Direct Traffic → 100, 65; Referral → 50, 75<br>Organic Search कुल = \\(250 + 350 = 600\\) हज़ार = 6,00,000 आगंतुक<br>बाउंस = 6,00,000 का \\(5\\%\\) = 30,000<br>जुड़े रहने वाले आगंतुक = \\(6{,}00{,}000 - 30{,}000 = \\boxed{570{,}000}\\)<br><br><b>अतः सही उत्तर विकल्प (3): 570,000 है।</b>"},"marks":{"correct":2,"negative":0.5},"has_image":true,"images":{"question":["https://res.cloudinary.com/mc6kb3uo/image/upload/ssc_mock/CGL-23-OCT-2026-SHIFT-3/q61.jpg"]}},{"no":62,"local_id":"50062","quid":"Q1000071342","section":"MATH","topic":"Height and Distance","question":{"en":"From the top of a lighthouse of height 100 m, the angle of depression of a ship is 45°. How far is the ship from the lighthouse base? [SSC CGL 23/10/26 Shift 3]","hi":"100 m ऊँचे एक प्रकाशस्तंभ के शिखर से एक जहाज़ का अवनमन कोण 45° है। जहाज़ प्रकाशस्तंभ के आधार से कितनी दूर है? [SSC CGL 23/10/26 Shift 3]"},"options":{"1":{"en":"100 m"},"2":{"en":"200 m"},"3":{"en":"150 m"},"4":{"en":"250 m"}},"answer":"1","solution":{"en":"<svg width=\"223\" height=\"202\" viewBox=\"-21 0 223 202\" fill=\"none\" stroke=\"#000\" stroke-width=\"1.5\" font-size=\"12\"><path d=\"M26 176L176 176M26 176L26 26M34 176L34 168L26 168M176 176L26 26M48 26A22 22 0 0 1 42 42\"/><path stroke-dasharray=\"4 3\" d=\"M26 26L176 26\"/><g fill=\"#000\" stroke=\"#fff\" stroke-width=\"3\" paint-order=\"stroke\" stroke-linejoin=\"round\" text-anchor=\"middle\"><text x=\"14\" y=\"30\">A</text><text x=\"18\" y=\"187\">B</text><text x=\"0\" y=\"105\">100 m</text><text x=\"59\" y=\"44\" font-size=\"11\">45°</text><text x=\"176\" y=\"190\">C</text><text x=\"101\" y=\"192\">d</text></g></svg><br>With the height 100 m and depression \\(45^\\circ\\), the triangles gives<br>\\(\\tan 45^\\circ = \\frac{100}{d} \\Rightarrow d = \\frac{100}{1}\\)<br>\\(d = \\boxed{100}\\) m<br><br><b>Hence, the correct answer is option (1): 100 m.</b>","hi":"<svg width=\"223\" height=\"202\" viewBox=\"-21 0 223 202\" fill=\"none\" stroke=\"#000\" stroke-width=\"1.5\" font-size=\"12\"><path d=\"M26 176L176 176M26 176L26 26M34 176L34 168L26 168M176 176L26 26M48 26A22 22 0 0 1 42 42\"/><path stroke-dasharray=\"4 3\" d=\"M26 26L176 26\"/><g fill=\"#000\" stroke=\"#fff\" stroke-width=\"3\" paint-order=\"stroke\" stroke-linejoin=\"round\" text-anchor=\"middle\"><text x=\"14\" y=\"30\">A</text><text x=\"18\" y=\"187\">B</text><text x=\"0\" y=\"105\">100 m</text><text x=\"59\" y=\"44\" font-size=\"11\">45°</text><text x=\"176\" y=\"190\">C</text><text x=\"101\" y=\"192\">d</text></g></svg><br>100 m ऊँचाई और \\(45^\\circ\\) अवनमन के साथ,<br>\\(\\tan 45^\\circ = \\frac{100}{d} \\Rightarrow d = \\frac{100}{1}\\)<br>\\(d = \\boxed{100}\\) m<br><br><b>अतः सही उत्तर विकल्प (1): 100 m है।</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":63,"local_id":"50063","quid":"Q1000071343","section":"MATH","topic":"Coordinate Geometry","question":{"en":"The lines: L1 = 2x + 1 and L2 = 2x − 3 are: [SSC CGL 23/10/26 Shift 3]","hi":"रेखाएँ: L1 = 2x + 1 और L2 = 2x − 3 हैं: [SSC CGL 23/10/26 Shift 3]"},"options":{"1":{"en":"Parallel","hi":"समांतर"},"2":{"en":"Perpendicular","hi":"लंबवत"},"3":{"en":"Coincident","hi":"संपाती"},"4":{"en":"Intersecting at one point","hi":"एक बिंदु पर प्रतिच्छेदी"}},"answer":"1","solution":{"en":"Both lines have the same slope \\(m = 2\\) but different intercepts (1 and −3).<br>Equal slopes with different intercepts mean the lines never meet.<br>Hence they are \\(\\boxed{\\text{Parallel}}\\)<br><br><b>Hence, the correct answer is option (1): Parallel.</b>","hi":"दोनों रेखाओं की प्रवणता समान \\(m = 2\\) है परंतु अंतःखंड भिन्न (1 और −3) हैं।<br>समान प्रवणता और भिन्न अंतःखंड का अर्थ है कि रेखाएँ कभी नहीं मिलतीं।<br>अतः वे \\(\\boxed{\\text{समांतर}}\\) हैं।<br><br><b>अतः सही उत्तर विकल्प (1): समांतर है।</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":64,"local_id":"50064","quid":"Q1000071344","section":"MATH","topic":"Algebra","question":{"en":"What is the value of (x + 2)³ − (x − 2)³? [SSC CGL 23/10/26 Shift 3]","hi":"(x + 2)³ − (x − 2)³ का मान क्या है? [SSC CGL 23/10/26 Shift 3]"},"options":{"1":{"en":"24x² + 18"},"2":{"en":"12x² + 16"},"3":{"en":"24x² − 16"},"4":{"en":"24x²"}},"answer":"2","solution":{"en":"\\((a^3 - b^3) = (a - b)(a^2 + ab + b^2)\\) with \\(a = x+2\\), \\(b = x-2\\)<br>\\(a - b = 4\\); \\(a^2 = x^2 + 4x + 4\\), \\(ab = x^2 - 4\\), \\(b^2 = x^2 - 4x + 4\\)<br>Sum \\(= 3x^2 + 4\\)<br>Expression \\(= 4(3x^2 + 4) = \\boxed{12x^2 + 16}\\)<br><br><b>Hence, the correct answer is option (2): 12x² + 16.</b>","hi":"\\((a^3 - b^3) = (a - b)(a^2 + ab + b^2)\\), जहाँ \\(a = x+2\\), \\(b = x-2\\)<br>\\(a - b = 4\\); \\(a^2 = x^2 + 4x + 4\\), \\(ab = x^2 - 4\\), \\(b^2 = x^2 - 4x + 4\\)<br>योग \\(= 3x^2 + 4\\)<br>व्यंजक \\(= 4(3x^2 + 4) = \\boxed{12x^2 + 16}\\)<br><br><b>अतः सही उत्तर विकल्प (2): 12x² + 16 है।</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":65,"local_id":"50065","quid":"Q1000071345","section":"MATH","topic":"Algebra","question":{"en":"Find the value of (3x + 2y)² − (3x − 2y)². [SSC CGL 23/10/26 Shift 3]","hi":"(3x + 2y)² − (3x − 2y)² का मान ज्ञात कीजिए। [SSC CGL 23/10/26 Shift 3]"},"options":{"1":{"en":"12xy"},"2":{"en":"24xy"},"3":{"en":"6xy"},"4":{"en":"36xy"}},"answer":"2","solution":{"en":"\\((a + b)^2 - (a - b)^2 = 4ab\\) with \\(a = 3x\\), \\(b = 2y\\)<br>\\(= 4 \\times 3x \\times 2y = \\boxed{24xy}\\)<br><br><b>Hence, the correct answer is option (2): 24xy.</b>","hi":"\\((a + b)^2 - (a - b)^2 = 4ab\\), जहाँ \\(a = 3x\\), \\(b = 2y\\)<br>\\(= 4 \\times 3x \\times 2y = \\boxed{24xy}\\)<br><br><b>अतः सही उत्तर विकल्प (2): 24xy है।</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":66,"local_id":"50066","quid":"Q1000071346","section":"MATH","topic":"Mixture and Alligation","question":{"en":"A 25-litre solution contains acid and water in the ratio 3:2. How much acid must be added to make the ratio 4:1? [SSC CGL 23/10/26 Shift 3]","hi":"25 लीटर के एक घोल में अम्ल और जल 3:2 के अनुपात में हैं। अनुपात 4:1 करने के लिए कितना अम्ल मिलाना होगा? [SSC CGL 23/10/26 Shift 3]"},"options":{"1":{"en":"10 litres","hi":"10 लीटर"},"2":{"en":"15 litres","hi":"15 लीटर"},"3":{"en":"18 litres","hi":"18 लीटर"},"4":{"en":"25 litres","hi":"25 लीटर"}},"answer":"4","solution":{"en":"Acid = \\(\\frac{3}{5} \\times 25 = 15\\) L, water = \\(\\frac{2}{5} \\times 25 = 10\\) L<br>Water stays 10 L, so for 4 : 1 the acid must become \\(4 \\times 10 = 40\\) L<br>Acid to add = \\(40 - 15 = \\boxed{25}\\) litres<br><br><b>Hence, the correct answer is option (4): 25 litres.</b>","hi":"अम्ल = \\(\\frac{3}{5} \\times 25 = 15\\) L, जल = \\(\\frac{2}{5} \\times 25 = 10\\) L<br>जल 10 L ही रहता है, अतः 4 : 1 के लिए अम्ल \\(4 \\times 10 = 40\\) L होना चाहिए<br>मिलाने वाला अम्ल = \\(40 - 15 = \\boxed{25}\\) लीटर<br><br><b>अतः सही उत्तर विकल्प (4): 25 लीटर है।</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":67,"local_id":"50067","quid":"Q1000071347","section":"MATH","topic":"Geometry","question":{"en":"The length of a chord is 24 cm and the radius of the circle is 13 cm. Find the distance of the chord from the centre. [SSC CGL 23/10/26 Shift 3]","hi":"एक जीवा की लंबाई 24 cm है और वृत्त की त्रिज्या 13 cm है। जीवा की केंद्र से दूरी ज्ञात कीजिए। [SSC CGL 23/10/26 Shift 3]"},"options":{"1":{"en":"7 cm"},"2":{"en":"6 cm"},"3":{"en":"9 cm"},"4":{"en":"5 cm"}},"answer":"4","solution":{"en":"<svg width=\"232\" height=\"232\" viewBox=\"0 0 232 232\" fill=\"none\" stroke=\"#000\" stroke-width=\"1.5\" font-size=\"12\"><path d=\"M33 151L199 151M116 116L116 151M123 151L123 144L116 144\"/><path stroke-dasharray=\"4 3\" d=\"M116 116L199 151\"/><circle cx=\"116\" cy=\"116\" r=\"90\"/><circle cx=\"116\" cy=\"116\" r=\"2\" fill=\"#000\"/><g fill=\"#000\" stroke=\"#fff\" stroke-width=\"3\" paint-order=\"stroke\" stroke-linejoin=\"round\" text-anchor=\"middle\"><text x=\"108\" y=\"110\">O</text><text x=\"18\" y=\"160\">A</text><text x=\"214\" y=\"160\">B</text><text x=\"116\" y=\"167\">M</text><text x=\"111\" y=\"137\" text-anchor=\"end\" font-size=\"11\">d</text><text x=\"158\" y=\"167\" font-size=\"11\">12</text><text x=\"154\" y=\"145\">13</text></g></svg><br>Half of the chord = \\(\\frac{24}{2} = 12\\) cm<br>Distance from the centre = \\(\\sqrt{13^2 - 12^2} = \\sqrt{169 - 144}\\)<br>\\(= \\sqrt{25} = \\boxed{5}\\) cm<br><br><b>Hence, the correct answer is option (4): 5 cm.</b>","hi":"<svg width=\"232\" height=\"232\" viewBox=\"0 0 232 232\" fill=\"none\" stroke=\"#000\" stroke-width=\"1.5\" font-size=\"12\"><path d=\"M33 151L199 151M116 116L116 151M123 151L123 144L116 144\"/><path stroke-dasharray=\"4 3\" d=\"M116 116L199 151\"/><circle cx=\"116\" cy=\"116\" r=\"90\"/><circle cx=\"116\" cy=\"116\" r=\"2\" fill=\"#000\"/><g fill=\"#000\" stroke=\"#fff\" stroke-width=\"3\" paint-order=\"stroke\" stroke-linejoin=\"round\" text-anchor=\"middle\"><text x=\"108\" y=\"110\">O</text><text x=\"18\" y=\"160\">A</text><text x=\"214\" y=\"160\">B</text><text x=\"116\" y=\"167\">M</text><text x=\"111\" y=\"137\" text-anchor=\"end\" font-size=\"11\">d</text><text x=\"158\" y=\"167\" font-size=\"11\">12</text><text x=\"154\" y=\"145\">13</text></g></svg><br>जीवा का आधा = \\(\\frac{24}{2} = 12\\) cm<br>केंद्र से दूरी = \\(\\sqrt{13^2 - 12^2} = \\sqrt{169 - 144}\\)<br>\\(= \\sqrt{25} = \\boxed{5}\\) cm<br><br><b>अतः सही उत्तर विकल्प (4): 5 cm है।</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":68,"local_id":"50068","quid":"Q1000071348","section":"MATH","topic":"Mensuration (3D)","question":{"en":"Calculate the curved surface area (in square centimetres) of a cylinder with radius 3.5 cm and height 12 cm. (Use π = 22/7) [SSC CGL 23/10/26 Shift 3]","hi":"3.5 cm त्रिज्या और 12 cm ऊँचाई वाले बेलन का वक्र पृष्ठीय क्षेत्रफल (वर्ग सेंटीमीटर में) ज्ञात कीजिए। (π = 22/7 लीजिए) [SSC CGL 23/10/26 Shift 3]"},"options":{"1":{"en":"270"},"2":{"en":"268"},"3":{"en":"264"},"4":{"en":"277"}},"answer":"3","solution":{"en":"<svg width=\"157\" height=\"222\" viewBox=\"0 0 157 222\" fill=\"none\" stroke=\"#000\" stroke-width=\"1.5\" font-size=\"12\"><path d=\"M26 183A42 13 0 0 0 110 183M26 183L26 39M110 183L110 39\"/><path stroke-dasharray=\"4 3\" d=\"M26 183A42 13 0 0 1 110 183M68 39L110 39\"/><ellipse cx=\"68\" cy=\"39\" rx=\"42\" ry=\"13\"/><circle cx=\"68\" cy=\"39\" r=\"2\" fill=\"#000\"/><g fill=\"#000\" stroke=\"#fff\" stroke-width=\"3\" paint-order=\"stroke\" stroke-linejoin=\"round\" text-anchor=\"middle\"><text x=\"89\" y=\"24\" font-size=\"11\">3.5 cm</text><text x=\"136\" y=\"115\">12 cm</text></g></svg><br>Curved surface area \\(= 2\\pi r h\\)<br>\\(= 2 \\times \\frac{22}{7} \\times 3.5 \\times 12\\)<br>\\(= 2 \\times 22 \\times 0.5 \\times 12 = \\boxed{264}\\) cm²<br><br><b>Hence, the correct answer is option (3): 264.</b>","hi":"<svg width=\"157\" height=\"222\" viewBox=\"0 0 157 222\" fill=\"none\" stroke=\"#000\" stroke-width=\"1.5\" font-size=\"12\"><path d=\"M26 183A42 13 0 0 0 110 183M26 183L26 39M110 183L110 39\"/><path stroke-dasharray=\"4 3\" d=\"M26 183A42 13 0 0 1 110 183M68 39L110 39\"/><ellipse cx=\"68\" cy=\"39\" rx=\"42\" ry=\"13\"/><circle cx=\"68\" cy=\"39\" r=\"2\" fill=\"#000\"/><g fill=\"#000\" stroke=\"#fff\" stroke-width=\"3\" paint-order=\"stroke\" stroke-linejoin=\"round\" text-anchor=\"middle\"><text x=\"89\" y=\"24\" font-size=\"11\">3.5 cm</text><text x=\"136\" y=\"115\">12 cm</text></g></svg><br>वक्र पृष्ठीय क्षेत्रफल \\(= 2\\pi r h\\)<br>\\(= 2 \\times \\frac{22}{7} \\times 3.5 \\times 12\\)<br>\\(= 2 \\times 22 \\times 0.5 \\times 12 = \\boxed{264}\\) cm²<br><br><b>अतः सही उत्तर विकल्प (3): 264 है।</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":69,"local_id":"50069","quid":"Q1000071349","section":"MATH","topic":"Number System","question":{"en":"The decimal 0.333.. (with 3 repeating) can be written as which fraction? [SSC CGL 23/10/26 Shift 3]","hi":"दशमलव 0.333.. (3 की पुनरावृत्ति) को किस भिन्न के रूप में लिखा जा सकता है? [SSC CGL 23/10/26 Shift 3]"},"options":{"1":{"en":"3/10"},"2":{"en":"1/3"},"3":{"en":"3/12"},"4":{"en":"1/9"}},"answer":"2","solution":{"en":"Let \\(x = 0.\\overline{3}\\), then \\(10x = 3.\\overline{3}\\)<br>\\(10x - x = 3.\\overline{3} - 0.\\overline{3} \\Rightarrow 9x = 3\\)<br>\\(x = \\frac{3}{9} = \\boxed{\\frac{1}{3}}\\)<br><br><b>Hence, the correct answer is option (2): 1/3.</b>","hi":"मान लीजिए \\(x = 0.\\overline{3}\\), तब \\(10x = 3.\\overline{3}\\)<br>\\(10x - x = 3.\\overline{3} - 0.\\overline{3} \\Rightarrow 9x = 3\\)<br>\\(x = \\frac{3}{9} = \\boxed{\\frac{1}{3}}\\)<br><br><b>अतः सही उत्तर विकल्प (2): 1/3 है।</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":70,"local_id":"50070","quid":"Q1000071350","section":"MATH","topic":"Trigonometry","question":{"en":"If tanθ = 1, find sec²θ. [SSC CGL 23/10/26 Shift 3]","hi":"यदि tanθ = 1 है, तो sec²θ ज्ञात कीजिए। [SSC CGL 23/10/26 Shift 3]"},"options":{"1":{"en":"2"},"2":{"en":"0"},"3":{"en":"1"},"4":{"en":"3"}},"answer":"1","solution":{"en":"\\(\\sec^2\\theta = 1 + \\tan^2\\theta\\)<br>\\(= 1 + 1 = \\boxed{2}\\)<br><br><b>Hence, the correct answer is option (1): 2.</b>","hi":"\\(\\sec^2\\theta = 1 + \\tan^2\\theta\\)<br>\\(= 1 + 1 = \\boxed{2}\\)<br><br><b>अतः सही उत्तर विकल्प (1): 2 है।</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":71,"local_id":"50071","quid":"Q1000071351","section":"MATH","topic":"Mensuration (2D)","question":{"en":"A farmer wants to fence a square plot whose area is 1225 square metres. What will be the length of each side of the plot? [SSC CGL 23/10/26 Shift 3]","hi":"एक किसान 1225 वर्ग मीटर क्षेत्रफल वाले वर्गाकार भूखंड की बाड़ लगाना चाहता है। भूखंड की प्रत्येक भुजा की लंबाई क्या होगी? [SSC CGL 23/10/26 Shift 3]"},"options":{"1":{"en":"30 metres","hi":"30 मीटर"},"2":{"en":"45 metres","hi":"45 मीटर"},"3":{"en":"35 metres","hi":"35 मीटर"},"4":{"en":"40 metres","hi":"40 मीटर"}},"answer":"3","solution":{"en":"Area of a square \\(= a^2 = 1225\\)<br>\\(a = \\sqrt{1225} = \\boxed{35}\\) metres<br><br><b>Hence, the correct answer is option (3): 35 metres.</b>","hi":"वर्ग का क्षेत्रफल \\(= a^2 = 1225\\)<br>\\(a = \\sqrt{1225} = \\boxed{35}\\) मीटर<br><br><b>अतः सही उत्तर विकल्प (3): 35 मीटर है।</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":72,"local_id":"50072","quid":"Q1000071352","section":"MATH","topic":"Pipe and Cistern","question":{"en":"Two pipes, A and B, can fill a tank in 1 and 3 hours, respectively. If both pipes are opened together, how long will it take to fill the tank? [SSC CGL 23/10/26 Shift 3]","hi":"दो पाइप A और B एक टंकी को क्रमशः 1 और 3 घंटे में भर सकते हैं। यदि दोनों पाइप एक साथ खोल दिए जाएँ, तो टंकी भरने में कितना समय लगेगा? [SSC CGL 23/10/26 Shift 3]"},"options":{"1":{"en":"50 minutes","hi":"50 मिनट"},"2":{"en":"40 minutes","hi":"40 मिनट"},"3":{"en":"35 minutes","hi":"35 मिनट"},"4":{"en":"45 minutes","hi":"45 मिनट"}},"answer":"4","solution":{"en":"Combined rate per hour = \\(1 + \\frac{1}{3} = \\frac{4}{3}\\)<br>Time = \\(\\frac{3}{4}\\) hour = \\(\\frac{3}{4} \\times 60\\)<br>\\(= \\boxed{45}\\) minutes<br><br><b>Hence, the correct answer is option (4): 45 minutes.</b>","hi":"प्रति घंटे संयुक्त दर = \\(1 + \\frac{1}{3} = \\frac{4}{3}\\)<br>समय = \\(\\frac{3}{4}\\) घंटा = \\(\\frac{3}{4} \\times 60\\)<br>\\(= \\boxed{45}\\) मिनट<br><br><b>अतः सही उत्तर विकल्प (4): 45 मिनट है।</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":73,"local_id":"50073","quid":"Q1000071353","section":"MATH","topic":"Mensuration (3D)","question":{"en":"The lateral surface area of a right prism is 180 cm². If the perimeter of the base is 30 cm, find its height. [SSC CGL 23/10/26 Shift 3]","hi":"एक समकोणीय प्रिज्म का पार्श्व पृष्ठीय क्षेत्रफल 180 cm² है। यदि आधार का परिमाप 30 cm है, तो इसकी ऊँचाई ज्ञात कीजिए। [SSC CGL 23/10/26 Shift 3]"},"options":{"1":{"en":"5cm"},"2":{"en":"6cm"},"3":{"en":"7cm"},"4":{"en":"8cm"}},"answer":"2","solution":{"en":"Lateral surface area = perimeter of base × height<br>\\(180 = 30 \\times h \\Rightarrow h = \\frac{180}{30}\\)<br>\\(h = \\boxed{6}\\) cm<br><br><b>Hence, the correct answer is option (2): 6cm.</b>","hi":"पार्श्व पृष्ठीय क्षेत्रफल = आधार का परिमाप × ऊँचाई<br>\\(180 = 30 \\times h \\Rightarrow h = \\frac{180}{30}\\)<br>\\(h = \\boxed{6}\\) cm<br><br><b>अतः सही उत्तर विकल्प (2): 6cm है।</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":74,"local_id":"50074","quid":"Q1000071354","section":"MATH","topic":"Elementary Statistics","question":{"en":"This histogram represents the weights (in kg) of 45 people in a fitness club.<br><img src=\"https://res.cloudinary.com/mc6kb3uo/image/upload/ssc_mock/CGL-23-OCT-2026-SHIFT-3/q74.jpg\" style=\"max-width:100%;height:auto\"><br>What percentage of people weigh between 55 and 65 kg?<br><img src=\"https://res.cloudinary.com/mc6kb3uo/image/upload/ssc_mock/CGL-23-OCT-2026-SHIFT-3/q74.jpg\" style=\"max-width:100%;height:auto\"> [SSC CGL 23/10/26 Shift 3]","hi":"यह हिस्टोग्राम एक फिटनेस क्लब के 45 लोगों के भार (kg में) को दर्शाता है।<br><img src=\"https://res.cloudinary.com/mc6kb3uo/image/upload/ssc_mock/CGL-23-OCT-2026-SHIFT-3/q74.jpg\" style=\"max-width:100%;height:auto\"><br>55 और 65 kg के बीच कितने प्रतिशत लोगों का भार है?<br><img src=\"https://res.cloudinary.com/mc6kb3uo/image/upload/ssc_mock/CGL-23-OCT-2026-SHIFT-3/q74.jpg\" style=\"max-width:100%;height:auto\"> [SSC CGL 23/10/26 Shift 3]"},"options":{"1":{"en":"37.8%"},"2":{"en":"40%"},"3":{"en":"44.5%"},"4":{"en":"50%"}},"answer":"1","solution":{"en":"From the histogram: 40–45 → 5, 45–50 → 8, 50–55 → 12, 55–60 → 10, 60–65 → 7, 65–70 → 3 (total 45)<br>People weighing 55–65 kg = \\(10 + 7 = 17\\)<br>Required percentage = \\(\\frac{17}{45} \\times 100 = 37.78\\% \\approx \\boxed{37.8\\%}\\)<br><br><b>Hence, the correct answer is option (1): 37.8%.</b>","hi":"हिस्टोग्राम से: 40–45 → 5, 45–50 → 8, 50–55 → 12, 55–60 → 10, 60–65 → 7, 65–70 → 3 (कुल 45)<br>55–65 kg भार वाले लोग = \\(10 + 7 = 17\\)<br>अभीष्ट प्रतिशत = \\(\\frac{17}{45} \\times 100 = 37.78\\% \\approx \\boxed{37.8\\%}\\)<br><br><b>अतः सही उत्तर विकल्प (1): 37.8% है।</b>"},"marks":{"correct":2,"negative":0.5},"has_image":true,"images":{"question":["https://res.cloudinary.com/mc6kb3uo/image/upload/ssc_mock/CGL-23-OCT-2026-SHIFT-3/q74.jpg"]}},{"no":75,"local_id":"50075","quid":"Q1000071355","section":"MATH","topic":"Elementary Statistics","question":{"en":"This histogram represents the weights (in kg) of 45 people in a fitness club.<br><img src=\"https://res.cloudinary.com/mc6kb3uo/image/upload/ssc_mock/CGL-23-OCT-2026-SHIFT-3/q75.jpg\" style=\"max-width:100%;height:auto\"><br>What is the approximate mid-point of the class interval with the least number of people?<br><img src=\"https://res.cloudinary.com/mc6kb3uo/image/upload/ssc_mock/CGL-23-OCT-2026-SHIFT-3/q75.jpg\" style=\"max-width:100%;height:auto\"> [SSC CGL 23/10/26 Shift 3]","hi":"यह हिस्टोग्राम एक फिटनेस क्लब के 45 लोगों के भार (kg में) को दर्शाता है।<br><img src=\"https://res.cloudinary.com/mc6kb3uo/image/upload/ssc_mock/CGL-23-OCT-2026-SHIFT-3/q75.jpg\" style=\"max-width:100%;height:auto\"><br>सबसे कम लोगों वाले वर्ग अंतराल का अनुमानित मध्य-बिंदु क्या है?<br><img src=\"https://res.cloudinary.com/mc6kb3uo/image/upload/ssc_mock/CGL-23-OCT-2026-SHIFT-3/q75.jpg\" style=\"max-width:100%;height:auto\"> [SSC CGL 23/10/26 Shift 3]"},"options":{"1":{"en":"42.5"},"2":{"en":"67.5"},"3":{"en":"62.5"},"4":{"en":"72.5"}},"answer":"2","solution":{"en":"Frequencies are 5, 8, 12, 10, 7, 3 for the intervals 40–45, 45–50, 50–55, 55–60, 60–65, 65–70.<br>The least number of people (3) is in the interval 65–70 kg.<br>Mid-point = \\(\\frac{65 + 70}{2} = \\boxed{67.5}\\)<br><br><b>Hence, the correct answer is option (2): 67.5.</b>","hi":"अंतरालों 40–45, 45–50, 50–55, 55–60, 60–65, 65–70 के बारंबारता क्रमशः 5, 8, 12, 10, 7, 3 हैं।<br>सबसे कम लोग (3) अंतराल 65–70 kg में हैं।<br>मध्य-बिंदु = \\(\\frac{65 + 70}{2} = \\boxed{67.5}\\)<br><br><b>अतः सही उत्तर विकल्प (2): 67.5 है।</b>"},"marks":{"correct":2,"negative":0.5},"has_image":true,"images":{"question":["https://res.cloudinary.com/mc6kb3uo/image/upload/ssc_mock/CGL-23-OCT-2026-SHIFT-3/q75.jpg"]}}]},"ENGLISH":{"seconds":900,"questions":[{"no":76,"local_id":"50076","quid":"Q1000071356","section":"ENGLISH","topic":"Antonym","question":{"en":"Select the most appropriate antonym of the given word. <b>Adorn</b> [SSC CGL 23/10/26 Shift 3]"},"options":{"1":{"en":"Decorate"},"2":{"en":"Disfigure"},"3":{"en":"Beautify"},"4":{"en":"Accessorize"}},"answer":"2","solution":{"en":"<b>Adorn (सजाना) = decorate or beautify.</b><br><b>Decorate (सजाना)</b> = adorn<br><b>Disfigure (बिगाड़ना)</b> = spoil the appearance ✔<br><b>Beautify (सुंदर बनाना)</b> = improve appearance; <b>accessorize</b> = add accessories.<br><br><b>Hence, the correct answer is option (2): Disfigure.</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":77,"local_id":"50077","quid":"Q1000071357","section":"ENGLISH","topic":"Direct Indirect (Narration)","question":{"en":"Convert the below given indirect speech into direct speech appropriately:<br>He said that he had been living in India for five years. [SSC CGL 23/10/26 Shift 3]"},"options":{"1":{"en":"He said, “He live in India for five years”."},"2":{"en":"He said, “I have been living in India for five years”."},"3":{"en":"He said, “I lived in India for five years”."},"4":{"en":"He said, “I had lived in India for five years”."}},"answer":"2","solution":{"en":"<b>Rule: Past perfect continuous reverses to present perfect continuous.</b><br>“Had been living” becomes “have been living.”<br>The reported “he” becomes “I.”<br>The other options retain past forms or use incorrect agreement.<br><br><b>Hence, the correct answer is option (2): He said, “I have been living in India for five years”.</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":78,"local_id":"50078","quid":"Q1000071358","section":"ENGLISH","topic":"Spotting Errors","question":{"en":"Spot the error in the following sentence and identify the INCORRECT part.<br>She is <b>good in</b> English and Mathematics. [SSC CGL 23/10/26 Shift 3]"},"options":{"1":{"en":"English and Mathematics"},"2":{"en":"good in"},"3":{"en":"She is"},"4":{"en":"No error"}},"answer":"2","solution":{"en":"<b>Rule: The idiomatic construction is “good at” a subject or skill.</b><br>Correct sentence: “She is <b>good at</b> English and Mathematics.”<br>“Good in” is not appropriate for academic proficiency.<br>The other parts are correct.<br><br><b>Hence, the correct answer is option (2): good in.</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":79,"local_id":"50079","quid":"Q1000071359","section":"ENGLISH","topic":"Antonym","question":{"en":"What is the antonym of the word “tenacious”? [SSC CGL 23/10/26 Shift 3]"},"options":{"1":{"en":"Angry"},"2":{"en":"Flated"},"3":{"en":"Hesitant"},"4":{"en":"Strong"}},"answer":"3","solution":{"en":"<b>Tenacious (दृढ़) = persistent and determined.</b><br><b>Hesitant (संकोची)</b> = reluctant or lacking determination ✔<br>Angry describes emotion; “flated” is not an antonym.<br>Strong is closer to a synonym.<br><br><b>Hence, the correct answer is option (3): Hesitant.</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":80,"local_id":"50080","quid":"Q1000071360","section":"ENGLISH","topic":"Idioms and Phrases","question":{"en":"Choose the correct meaning of idiom given below:<br>“Poetic justice” [SSC CGL 23/10/26 Shift 3]"},"options":{"1":{"en":"Justice through courts"},"2":{"en":"Punishment fits the crime"},"3":{"en":"Irony where villain suffers fittingly"},"4":{"en":"Justice delayed"}},"answer":"3","solution":{"en":"<b>Poetic justice (उपयुक्त प्रतिफल) = deserved misfortune, often ironically fitting.</b><br>Example: “The cheat was himself cheated—a case of poetic justice.”<br>It need not involve courts or formal punishment.<br>The key is fitting ironic retribution.<br><br><b>Hence, the correct answer is option (3): Irony where villain suffers fittingly.</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":81,"local_id":"50081","quid":"Q1000071361","section":"ENGLISH","topic":"Idioms and Phrases","question":{"en":"Choose the correct meaning of idiom given below:<br>“No love lost” [SSC CGL 23/10/26 Shift 3]"},"options":{"1":{"en":"Mutual dislike"},"2":{"en":"Deep friendship"},"3":{"en":"Unspoken love"},"4":{"en":"Neutrality"}},"answer":"1","solution":{"en":"<b>No love lost (पारस्परिक अरुचि) = mutual dislike.</b><br>Example: “There is no love lost between the two rivals.”<br>Deep friendship and unspoken love are opposite ideas.<br>The expression is stronger than neutrality.<br><br><b>Hence, the correct answer is option (1): Mutual dislike.</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":82,"local_id":"50082","quid":"Q1000071362","section":"ENGLISH","topic":"Spotting Errors","question":{"en":"Find the part of the sentence that contains an error:<br>The employee were (1)/ pulled out (2)/ of the task (3)/ for failing to keep it up. (4) [SSC CGL 23/10/26 Shift 3]"},"options":{"1":{"en":"(1)"},"2":{"en":"(2)"},"3":{"en":"(3)"},"4":{"en":"(4)"}},"answer":"1","solution":{"en":"<b>Rule: The singular subject “employee” takes “was.”</b><br>Part (1) should read “The employee <b>was</b>.”<br>“Were” requires a plural subject.<br>The remaining parts are correct.<br><br><b>Hence, the correct answer is option (1): (1).</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":83,"local_id":"50083","quid":"Q1000071363","section":"ENGLISH","topic":"Fill in the Blanks","question":{"en":"Fill in the blank with the most appropriate option:<br>Her remarks were not only misinformed but also ___, undermining years of community-led advocacy. [SSC CGL 23/10/26 Shift 3]"},"options":{"1":{"en":"derogatory"},"2":{"en":"contentious"},"3":{"en":"illustrative"},"4":{"en":"preliminary"}},"answer":"1","solution":{"en":"<b>Derogatory (अपमानजनक) = insulting or disparaging.</b><br>Derogatory remarks could undermine community advocacy.<br>“Contentious” means controversial, which need not be damaging.<br>Illustrative and preliminary do not fit the negative parallel.<br><br><b>Hence, the correct answer is option (1): derogatory.</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":84,"local_id":"50084","quid":"Q1000071364","section":"ENGLISH","topic":"Sentence Improvement","question":{"en":"Choose the most suitable option to replace the underlined part of the sentence:<br>The chair was placed directly <b>underneath of</b> the lamp. [SSC CGL 23/10/26 Shift 3]"},"options":{"1":{"en":"below"},"2":{"en":"beneath"},"3":{"en":"underneath"},"4":{"en":"under"}},"answer":"3","solution":{"en":"<b>Rule: “Underneath” is a complete preposition and does not take “of.”</b><br>Correct sentence: “directly <b>underneath</b> the lamp.”<br>“Below,” “beneath” and “under” are possible alternatives but not the keyed replacement.<br>The error is the redundant “of.”<br><br><b>Hence, the correct answer is option (3): underneath.</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":85,"local_id":"50085","quid":"Q1000071365","section":"ENGLISH","topic":"Sentence Improvement","question":{"en":"Choose the most suitable option to replace the underlined part of the sentence:<br>Neither the manager nor the employees <b>knows</b> the correct procedure. [SSC CGL 23/10/26 Shift 3]"},"options":{"1":{"en":"know"},"2":{"en":"knew"},"3":{"en":"have known"},"4":{"en":"is knowing"}},"answer":"1","solution":{"en":"<b>Rule: With “neither … nor,” the verb agrees with the nearer subject.</b><br>The nearer subject “employees” is plural, so “know” is correct.<br>“Knows” is singular; “knew” unnecessarily changes tense.<br>“Is knowing” is an inappropriate stative continuous form.<br><br><b>Hence, the correct answer is option (1): know.</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":86,"local_id":"50086","quid":"Q1000071366","section":"ENGLISH","topic":"Direct Indirect (Narration)","question":{"en":"A sentence is provided in direct speech. From the four given options, choose the one that most accurately conveys the sentence in its corresponding indirect speech.<br>The principal said, “Should any student violate the rule again, they will face strict disciplinary action.” [SSC CGL 23/10/26 Shift 3]"},"options":{"1":{"en":"The principal said that if any student violated the rule again, they would face strict disciplinary action."},"2":{"en":"The principal warned that if a student should violate the rule again, he will face strict action."},"3":{"en":"The principal said any student who violates the rule will face action."},"4":{"en":"The principal announced that should any student violated the rule, they would face action."}},"answer":"1","solution":{"en":"<b>Rule: The inverted condition becomes an “if” clause, and “will” becomes “would.”</b><br>“Should any student violate” becomes “if any student violated.”<br>The pronoun “they” and “strict disciplinary action” are retained.<br>The other options fail to backshift or alter the structure incorrectly.<br><br><b>Hence, the correct answer is option (1): The principal said that if any student violated the rule again, they would face strict disciplinary action.</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":87,"local_id":"50087","quid":"Q1000071367","section":"ENGLISH","topic":"Para Jumbles (PQRS)","question":{"en":"Rearrange the following sentences in correct order to make a meaningful passage.<br>1. The software is compiled and checked for bugs.<br>2. The client requirements are discussed and documented.<br>3. Once approved, development of features begins.<br>4. Final deployment is carried out on the live server. [SSC CGL 23/10/26 Shift 3]"},"options":{"1":{"en":"2-1-3-4"},"2":{"en":"1-2-3-4"},"3":{"en":"3-2-1-4"},"4":{"en":"2-3-1-4"}},"answer":"4","solution":{"en":"<b>Order: 2-3-1-4</b><br>Requirements are documented, and approved features are developed.<br>The software is then compiled and checked for bugs.<br>Deployment on the live server is last.<br><br><b>Hence, the correct answer is option (4): 2-3-1-4.</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":88,"local_id":"50088","quid":"Q1000071368","section":"ENGLISH","topic":"Para Jumbles (PQRS)","question":{"en":"Rearrange the following sentences in correct order to make a meaningful sentence.<br>P: in fostering innovation and collaboration<br>Q: plays a critical role<br>R: across interdisciplinary fields<br>S: institutional support [SSC CGL 23/10/26 Shift 3]"},"options":{"1":{"en":"SQRP"},"2":{"en":"QSRP"},"3":{"en":"SRQP"},"4":{"en":"RSQP"}},"answer":"1","solution":{"en":"<b>Order: SQRP</b><br>S supplies the subject and Q the main predicate.<br>R identifies the interdisciplinary setting.<br>P states the areas in which support is critical.<br><br><b>Hence, the correct answer is option (1): SQRP.</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":89,"local_id":"50089","quid":"Q1000071369","section":"ENGLISH","topic":"Para Jumbles (PQRS)","question":{"en":"Rearrange the following sentences in correct order to make a meaningful sentence.<br>P. to detect early-stage structural vulnerabilities in bridges<br>Q. using AI-driven sensors and real-time analytics<br>R. a nationwide safety audit mechanism<br>S. has been deployed by the Ministry of Transport [SSC CGL 23/10/26 Shift 3]"},"options":{"1":{"en":"RQSP"},"2":{"en":"QRSP"},"3":{"en":"RSQP"},"4":{"en":"PRSQ"}},"answer":"3","solution":{"en":"<b>Order: RSQP</b><br>R supplies the subject and S the passive predicate.<br>Q explains the technology used by the mechanism.<br>P states its purpose: detecting structural vulnerabilities.<br><br><b>Hence, the correct answer is option (3): RSQP.</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":90,"local_id":"50090","quid":"Q1000071370","section":"ENGLISH","topic":"Cloze Test","question":{"en":"In the passage below, certain words have been removed. Read the passage thoroughly and choose the most suitable option to complete each blank appropriately.<br><br>Technological advancement has long promised liberation—from drudgery, error, and even mortality. Yet, the deeper paradox of the digital era is that while it expands capacity, it often contracts (1)___. Algorithms increasingly make decisions once reserved for deliberative humans: from loan approvals to parole assessments. Though marketed as neutral, such systems inevitably inherit the biases of their makers, disguising human judgments as computational objectivity. In this sense, technology becomes less a tool than a (2)___, shaping choices rather than merely executing them. The problem is not intelligence, but (3)___—where efficiency is privileged over transparency, and speed over scrutiny. Once outcomes are automated, dissent is harder to formulate, not because it’s unwelcome, but because it becomes (4)___. Citizens may sense unfairness but lack the language or access to challenge opaque systems. The solution is not to reject automation, but to embed in its design the capacity for critique. What society requires is not more data, but a deeper ethics—an insistence that technological systems remain (5)___ to those they claim to serve.<br><br><br>What should come in the place of blank number 1? [SSC CGL 23/10/26 Shift 3]"},"options":{"1":{"en":"autonomy"},"2":{"en":"productivity"},"3":{"en":"anonymity"},"4":{"en":"intelligence"}},"answer":"1","solution":{"en":"<b>Autonomy (स्वायत्तता) = freedom to make one’s own decisions.</b><br>Algorithms take over decisions once made by humans, reducing autonomy.<br>Productivity, anonymity and intelligence are not what the expanded capacity contracts.<br><br><b>Hence, the correct answer is option (1): autonomy.</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":91,"local_id":"50091","quid":"Q1000071371","section":"ENGLISH","topic":"Cloze Test","question":{"en":"In the passage below, certain words have been removed. Read the passage thoroughly and choose the most suitable option to complete each blank appropriately.<br><br>Technological advancement has long promised liberation—from drudgery, error, and even mortality. Yet, the deeper paradox of the digital era is that while it expands capacity, it often contracts (1)___. Algorithms increasingly make decisions once reserved for deliberative humans: from loan approvals to parole assessments. Though marketed as neutral, such systems inevitably inherit the biases of their makers, disguising human judgments as computational objectivity. In this sense, technology becomes less a tool than a (2)___, shaping choices rather than merely executing them. The problem is not intelligence, but (3)___—where efficiency is privileged over transparency, and speed over scrutiny. Once outcomes are automated, dissent is harder to formulate, not because it’s unwelcome, but because it becomes (4)___. Citizens may sense unfairness but lack the language or access to challenge opaque systems. The solution is not to reject automation, but to embed in its design the capacity for critique. What society requires is not more data, but a deeper ethics—an insistence that technological systems remain (5)___ to those they claim to serve.<br><br><br>What should come in the place of blank number 2? [SSC CGL 23/10/26 Shift 3]"},"options":{"1":{"en":"mirror"},"2":{"en":"gatekeeper"},"3":{"en":"prosthetic"},"4":{"en":"amplifier"}},"answer":"2","solution":{"en":"<b>Gatekeeper (द्वारपाल) = something controlling access or outcomes.</b><br>Technology shapes choices rather than simply executing human instructions.<br>A mirror reflects, a prosthetic supplements ability, and an amplifier increases strength.<br>Only “gatekeeper” conveys control over decisions.<br><br><b>Hence, the correct answer is option (2): gatekeeper.</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":92,"local_id":"50092","quid":"Q1000071372","section":"ENGLISH","topic":"Cloze Test","question":{"en":"In the passage below, certain words have been removed. Read the passage thoroughly and choose the most suitable option to complete each blank appropriately.<br><br>Technological advancement has long promised liberation—from drudgery, error, and even mortality. Yet, the deeper paradox of the digital era is that while it expands capacity, it often contracts (1)___. Algorithms increasingly make decisions once reserved for deliberative humans: from loan approvals to parole assessments. Though marketed as neutral, such systems inevitably inherit the biases of their makers, disguising human judgments as computational objectivity. In this sense, technology becomes less a tool than a (2)___, shaping choices rather than merely executing them. The problem is not intelligence, but (3)___—where efficiency is privileged over transparency, and speed over scrutiny. Once outcomes are automated, dissent is harder to formulate, not because it’s unwelcome, but because it becomes (4)___. Citizens may sense unfairness but lack the language or access to challenge opaque systems. The solution is not to reject automation, but to embed in its design the capacity for critique. What society requires is not more data, but a deeper ethics—an insistence that technological systems remain (5)___ to those they claim to serve.<br><br><br>What should come in the place of blank number 3? [SSC CGL 23/10/26 Shift 3]"},"options":{"1":{"en":"delegation"},"2":{"en":"underestimated"},"3":{"en":"optimization"},"4":{"en":"humanization"}},"answer":"3","solution":{"en":"<b>Optimization (अनुकूलन) = maximizing efficiency or performance.</b><br>The following clause prioritizes efficiency and speed over transparency and scrutiny.<br>Delegation assigns tasks, while humanization emphasizes human values.<br>“Underestimated” is grammatically unsuitable.<br><br><b>Hence, the correct answer is option (3): optimization.</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":93,"local_id":"50093","quid":"Q1000071373","section":"ENGLISH","topic":"Cloze Test","question":{"en":"In the passage below, certain words have been removed. Read the passage thoroughly and choose the most suitable option to complete each blank appropriately.<br><br>Technological advancement has long promised liberation—from drudgery, error, and even mortality. Yet, the deeper paradox of the digital era is that while it expands capacity, it often contracts (1)___. Algorithms increasingly make decisions once reserved for deliberative humans: from loan approvals to parole assessments. Though marketed as neutral, such systems inevitably inherit the biases of their makers, disguising human judgments as computational objectivity. In this sense, technology becomes less a tool than a (2)___, shaping choices rather than merely executing them. The problem is not intelligence, but (3)___—where efficiency is privileged over transparency, and speed over scrutiny. Once outcomes are automated, dissent is harder to formulate, not because it’s unwelcome, but because it becomes (4)___. Citizens may sense unfairness but lack the language or access to challenge opaque systems. The solution is not to reject automation, but to embed in its design the capacity for critique. What society requires is not more data, but a deeper ethics—an insistence that technological systems remain (5)___ to those they claim to serve.<br><br><br>What should come in the place of blank number 4? [SSC CGL 23/10/26 Shift 3]"},"options":{"1":{"en":"articulate"},"2":{"en":"tenacious"},"3":{"en":"redundant"},"4":{"en":"invisible"}},"answer":"4","solution":{"en":"<b>Invisible (अदृश्य) = hidden from view.</b><br>Opaque automated systems make dissent difficult to formulate because processes become invisible.<br>Citizens cannot access or understand how decisions are made.<br>Articulate, tenacious and redundant do not fit.<br><br><b>Hence, the correct answer is option (4): invisible.</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":94,"local_id":"50094","quid":"Q1000071374","section":"ENGLISH","topic":"Cloze Test","question":{"en":"In the passage below, certain words have been removed. Read the passage thoroughly and choose the most suitable option to complete each blank appropriately.<br><br>Technological advancement has long promised liberation—from drudgery, error, and even mortality. Yet, the deeper paradox of the digital era is that while it expands capacity, it often contracts (1)___. Algorithms increasingly make decisions once reserved for deliberative humans: from loan approvals to parole assessments. Though marketed as neutral, such systems inevitably inherit the biases of their makers, disguising human judgments as computational objectivity. In this sense, technology becomes less a tool than a (2)___, shaping choices rather than merely executing them. The problem is not intelligence, but (3)___—where efficiency is privileged over transparency, and speed over scrutiny. Once outcomes are automated, dissent is harder to formulate, not because it’s unwelcome, but because it becomes (4)___. Citizens may sense unfairness but lack the language or access to challenge opaque systems. The solution is not to reject automation, but to embed in its design the capacity for critique. What society requires is not more data, but a deeper ethics—an insistence that technological systems remain (5)___ to those they claim to serve.<br><br><br>What should come in the place of blank number 5? [SSC CGL 23/10/26 Shift 3]"},"options":{"1":{"en":"accountable"},"2":{"en":"responsive"},"3":{"en":"legible"},"4":{"en":"restrictive"}},"answer":"1","solution":{"en":"<b>Accountable (उत्तरदायी) = answerable for decisions and consequences.</b><br>Ethical systems must remain accountable to the people they serve.<br>Responsiveness and legibility are useful but do not express responsibility as strongly.<br>Restrictive contradicts the aim.<br><br><b>Hence, the correct answer is option (1): accountable.</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":95,"local_id":"50095","quid":"Q1000071375","section":"ENGLISH","topic":"Para Jumbles (PQRS)","question":{"en":"Rearrange the following sentences in correct order to make a meaningful sentence.<br>P: continues to shape legal consciousness<br>Q: within postcolonial judicial reasoning<br>R: the legacy of colonial jurisprudence<br>S: in subtle but significant ways [SSC CGL 23/10/26 Shift 3]"},"options":{"1":{"en":"RPSQ"},"2":{"en":"RPQS"},"3":{"en":"QRSP"},"4":{"en":"PRSQ"}},"answer":"1","solution":{"en":"<b>Order: RPSQ</b><br>R supplies the subject, and P the main predicate.<br>S describes how the influence operates.<br>Q locates it within postcolonial judicial reasoning.<br><br><b>Hence, the correct answer is option (1): RPSQ.</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":96,"local_id":"50096","quid":"Q1000071376","section":"ENGLISH","topic":"Para Jumbles (PQRS)","question":{"en":"Rearrange the following sentences in correct order to make a meaningful sentence.<br>P: at the intersection of caste and gender<br>Q: the vulnerability of Dalit women<br>R: is compounded<br>S: by systemic exclusions [SSC CGL 23/10/26 Shift 3]"},"options":{"1":{"en":"SQPR"},"2":{"en":"QRSP"},"3":{"en":"QSRP"},"4":{"en":"PRSQ"}},"answer":"2","solution":{"en":"<b>Order: QRSP</b><br>Q supplies the subject, and R the passive verb.<br>S identifies the compounding force: systemic exclusions.<br>P locates these exclusions at the intersection of caste and gender.<br><br><b>Hence, the correct answer is option (2): QRSP.</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":97,"local_id":"50097","quid":"Q1000071377","section":"ENGLISH","topic":"Homophones and Homonyms","question":{"en":"Select the most appropriate homonym to fill in the blank.<br>My grandmother placed fruits and flowers on the ___ as an offering to the Sun God. [SSC CGL 23/10/26 Shift 3]"},"options":{"1":{"en":"altar"},"2":{"en":"alter"},"3":{"en":"praise"},"4":{"en":"abjective"}},"answer":"1","solution":{"en":"<b>Altar (वेदी) = a sacred table or platform for offerings.</b><br>Fruits and flowers are placed on an altar.<br>“Alter” means change, “praise” means commend.<br>“Abjective” is not appropriate here.<br><br><b>Hence, the correct answer is option (1): altar.</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":98,"local_id":"50098","quid":"Q1000071378","section":"ENGLISH","topic":"Spelling Check","question":{"en":"Select the INCORRECTLY spelt word. [SSC CGL 23/10/26 Shift 3]"},"options":{"1":{"en":"vertebraites"},"2":{"en":"unnatural"},"3":{"en":"understand"},"4":{"en":"vanish"}},"answer":"1","solution":{"en":"<b>Vertebrates (कशेरुकी) = animals with backbones.</b><br><b>Vertebraites</b> incorrectly inserts “i” after “a.”<br><b>Unnatural</b> = not natural; <b>understand</b> = comprehend.<br><b>Vanish</b> = disappear; these are correct.<br><br><b>Hence, the correct answer is option (1): vertebraites.</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":99,"local_id":"50099","quid":"Q1000071379","section":"ENGLISH","topic":"One Word Substitution","question":{"en":"Someone who is capable of doing anything is called. [SSC CGL 23/10/26 Shift 3]"},"options":{"1":{"en":"Omnipotent"},"2":{"en":"Omnipresent"},"3":{"en":"Omniscient"},"4":{"en":"God"}},"answer":"1","solution":{"en":"<b>Omnipotent (सर्वशक्तिमान) = having unlimited power.</b><br><b>Omnipresent (सर्वव्यापी)</b> = present everywhere<br><b>Omniscient (सर्वज्ञ)</b> = knowing everything<br>“God” is a being, not the precise adjective requested.<br><br><b>Hence, the correct answer is option (1): Omnipotent.</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":100,"local_id":"50100","quid":"Q1000071380","section":"ENGLISH","topic":"Para Jumbles (PQRS)","question":{"en":"Choose the correct option to rearrange the following sentences to form a coherent paragraph:<br>D. At last, we have gained our political freedom.<br>C. We make a strong promise to our people.<br>B. We will fight against poverty and suffering.<br>A. We will also end gender and all other discrimination. [SSC CGL 23/10/26 Shift 3]"},"options":{"1":{"en":"DCBA"},"2":{"en":"ABDC"},"3":{"en":"CBAD"},"4":{"en":"DACB"}},"answer":"1","solution":{"en":"<b>Order: D-C-B-A</b><br>D announces the achievement of political freedom.<br>C introduces a promise to the people.<br>B states the fight against poverty, and A adds the pledge against discrimination.<br><br><b>Hence, the correct answer is option (1): DCBA.</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false}]}}};